/*
 * app.h - types and entry points shared by the application modules.
 */
#ifndef APP_H
#define APP_H

#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>

#include "FreeRTOS.h"
#include "timers.h"

/* Features of one block of samples (acq.c). */
struct feat
{
    float rms_mg;           /* RMS acceleration, DC removed */
    float peak_mg;          /* largest |sample - mean| */
    uint16_t raw_max;       /* largest raw ADC count, for range checks */
};

/* Summary of SUMMARY_BLOCKS blocks, sent to store and uplink. */
struct summary
{
    uint32_t seq;
    uint32_t blocks;
    float rms_mg;           /* RMS over the period */
    float peak_mg;          /* largest block peak */
    float crest;            /* peak / rms */
    int16_t temp_c10;       /* last environment reading, 0.1 C */
    uint16_t rh_pct10;      /* 0.1 %RH */
    uint8_t afe_gain;
    bool alarm;             /* rms_mg above ALARM_RMS_MG */
};

/* Environment reading (env.c). */
struct env_sample
{
    int16_t temp_c10;
    uint16_t rh_pct10;
    TickType_t at;
};

/* acq.c */
void acq_start( UBaseType_t prio, uint16_t stack_words );
void acq_last_summary( struct summary * out );
void acq_print_stats( char * buf, size_t len );

/* env.c */
void env_timer_cb( TimerHandle_t t );
void env_last( struct env_sample * out );

/* store.c */
void store_start( UBaseType_t prio, uint16_t stack_words );
void store_post( const struct summary * s );

/* uplink.c */
void uplink_start( UBaseType_t prio, uint16_t stack_words );
void uplink_post( const struct summary * s );

/* console.c, cli_cmds.c */
void console_start( UBaseType_t prio, uint16_t stack_words );
void console_write( const char * s );
uint32_t console_rx_overruns( void );
void cli_register_commands( void );

/* bus.c: exclusive access to I2C1 (AFE, environment sensor, EEPROM). Hold the
 * lock for a whole transaction, or a sequence that must not be split. */
void bus_init( void );
void bus_lock( void );
void bus_unlock( void );

/* sys_timers.c */
enum sys_timer_id { SYS_TIMER_ENV, SYS_TIMER_WDG, SYS_TIMER_LED, SYS_TIMER_COUNT };
void sys_timers_start( void );
void sys_timer_hit( enum sys_timer_id id );
void sys_timers_print( char * buf, size_t len );

#endif /* APP_H */

--- app/bus.c ---
/*
 * bus.c - I2C1 bus lock, shared by acq (AFE), the timer task (environment
 * sensor) and store (EEPROM).
 */
#include "FreeRTOS.h"
#include "semphr.h"

#include "app.h"
#include "trace.h"

static SemaphoreHandle_t s_bus;

void bus_init( void )
{
    s_bus = xSemaphoreCreateBinary();
    configASSERT( s_bus != NULL );
    ( void ) xSemaphoreGive( s_bus );          /* bus starts free */
}

void bus_lock( void )
{
    if( xSemaphoreTake( s_bus, 0 ) != pdPASS )
    {
        trace_bus( TR_BUS_WAIT );
        ( void ) xSemaphoreTake( s_bus, portMAX_DELAY );
    }
    trace_bus( TR_BUS_TAKE );
}

void bus_unlock( void )
{
    trace_bus( TR_BUS_GIVE );
    ( void ) xSemaphoreGive( s_bus );
}

