/*
 * cli_cmds.c - console commands (FreeRTOS-Plus-CLI). task-stats and
 * run-time-stats are the ones from the FreeRTOS+CLI demo.
 */
#include <stdio.h>
#include <string.h>

#include "FreeRTOS.h"
#include "task.h"

#include "FreeRTOS_CLI.h"

#include "app.h"
#include "trace.h"

static void pad_task_heading( char ** p )
{
    strcpy( *p, "Task" );
    *p += strlen( *p );

    /* Line the column up with the task names that vTaskList() pads. */
    for( size_t x = strlen( "Task" ); x < ( configMAX_TASK_NAME_LEN - 3 ); x++ )
    {
        **p = ' ';
        ( *p )++;
        **p = '\0';
    }
}

static BaseType_t cmd_task_stats( char * buf, size_t len, const char * cmd )
{
    const char * const hdr = "     State   Priority  Stack    #\r\n************************************************\r\n";

    ( void ) cmd;
    ( void ) len;
    pad_task_heading( &buf );
    strcpy( buf, hdr );
    vTaskList( buf + strlen( hdr ) );
    return pdFALSE;
}

static BaseType_t cmd_run_time_stats( char * buf, size_t len, const char * cmd )
{
    const char * const hdr = "  Abs Time      % Time\r\n****************************************\r\n";

    ( void ) cmd;
    ( void ) len;
    pad_task_heading( &buf );
    strcpy( buf, hdr );
    vTaskGetRunTimeStats( buf + strlen( hdr ) );
    return pdFALSE;
}

static BaseType_t cmd_timer_stats( char * buf, size_t len, const char * cmd )
{
    ( void ) cmd;
    sys_timers_print( buf, len );
    return pdFALSE;
}

static BaseType_t cmd_acq_stats( char * buf, size_t len, const char * cmd )
{
    ( void ) cmd;
    acq_print_stats( buf, len );
    return pdFALSE;
}

static BaseType_t cmd_report( char * buf, size_t len, const char * cmd )
{
    struct summary s;
    struct env_sample e;
    char line[ 96 ];

    ( void ) cmd;
    acq_last_summary( &s );
    env_last( &e );

    snprintf( line, sizeof line, "summary %lu: rms %.1f mg  peak %.1f mg  crest %.2f  gain %u%s\r\n",
              ( unsigned long ) s.seq, ( double ) s.rms_mg, ( double ) s.peak_mg,
              ( double ) s.crest, ( unsigned ) s.afe_gain, s.alarm ? "  ALARM" : "" );
    strncpy( buf, line, len );
    snprintf( line, sizeof line, "env: %.1f C  %.1f %%RH\r\n",
              ( double ) e.temp_c10 / 10.0, ( double ) e.rh_pct10 / 10.0 );
    strncat( buf, line, len - strlen( buf ) - 1u );
    return pdFALSE;
}

static BaseType_t cmd_trace( char * buf, size_t len, const char * cmd )
{
    BaseType_t plen;
    const char * arg = FreeRTOS_CLIGetParameter( cmd, 1, &plen );

    if( ( arg != NULL ) && ( strncmp( arg, "stop", ( size_t ) plen ) == 0 ) )
    {
        trace_stop();
        snprintf( buf, len, "trace stopped\r\n" );
        return pdFALSE;
    }
    return trace_dump( buf, len );          /* pdTRUE while more lines remain */
}

static const CLI_Command_Definition_t s_cmds[] =
{
    { "task-stats", "\r\ntask-stats:\r\n Displays a table showing the state of each FreeRTOS task\r\n", cmd_task_stats, 0 },
    { "run-time-stats", "\r\nrun-time-stats:\r\n Displays a table showing how much processing time each FreeRTOS task has used\r\n", cmd_run_time_stats, 0 },
    { "timer-stats", "\r\ntimer-stats:\r\n Software timer runs and lateness since boot\r\n", cmd_timer_stats, 0 },
    { "acq-stats", "\r\nacq-stats:\r\n ADC DMA and block counters since boot\r\n", cmd_acq_stats, 0 },
    { "report", "\r\nreport:\r\n Last summary and environment reading\r\n", cmd_report, 0 },
    { "trace", "\r\ntrace [stop]:\r\n Dump the event trace (TRACE_ENABLE builds), or stop recording\r\n", cmd_trace, -1 },
};

void cli_register_commands( void )
{
    for( size_t i = 0; i < sizeof s_cmds / sizeof s_cmds[ 0 ]; i++ )
    {
        ( void ) FreeRTOS_CLIRegisterCommand( &s_cmds[ i ] );
    }
}

--- app/console.c ---
/*
 * console.c - UART1 command console. The RX interrupt feeds a stream buffer;
 * the cli task assembles lines and runs them through FreeRTOS-Plus-CLI.
 * Output is written with polled UART writes.
 */
#include <string.h>

#include "FreeRTOS.h"
#include "stream_buffer.h"
#include "task.h"

#include "FreeRTOS_CLI.h"

#include "app.h"
#include "board.h"
#include "mcu_ll.h"

#define CONSOLE_RX_BUF      64u
#define CONSOLE_LINE_MAX    64u

static StreamBufferHandle_t s_rx;
static volatile uint32_t s_rx_overruns;

void UART1_IRQHandler( void )
{
    BaseType_t xHigherPriorityTaskWoken = pdFALSE;

    while( ll_uart_rx_ready( UART1 ) )
    {
        char c = ll_uart_getc( UART1 );
        ( void ) xStreamBufferSendFromISR( s_rx, &c, 1u, &xHigherPriorityTaskWoken );
    }
    if( ll_uart_overrun( UART1 ) )
    {
        ll_uart_clear_overrun( UART1 );
        s_rx_overruns++;
    }
    portYIELD_FROM_ISR( xHigherPriorityTaskWoken );
}

void console_write( const char * s )
{
    while( *s != '\0' ) { board_console_putc( *s++ ); }
}

static void cli_task( void * arg )
{
    static char line[ CONSOLE_LINE_MAX ];
    char * out = FreeRTOS_CLIGetOutputBuffer();
    uint32_t n = 0u;
    char c;

    ( void ) arg;
    console_write( "\r\nsensor node 2.4.1\r\n> " );

    for( ; ; )
    {
        if( xStreamBufferReceive( s_rx, &c, 1u, portMAX_DELAY ) != 1u ) { continue; }

        if( ( c == '\r' ) || ( c == '\n' ) )
        {
            if( n == 0u ) { console_write( "\r\n> " ); continue; }
            line[ n ] = '\0';
            console_write( "\r\n" );

            BaseType_t more;
            do
            {
                more = FreeRTOS_CLIProcessCommand( line, out, configCOMMAND_INT_MAX_OUTPUT_SIZE );
                console_write( out );
            } while( more != pdFALSE );

            n = 0u;
            console_write( "\r\n> " );
        }
        else if( ( c == '\b' ) || ( c == 0x7F ) )
        {
            if( n > 0u ) { n--; }
        }
        else if( n < ( CONSOLE_LINE_MAX - 1u ) )
        {
            line[ n++ ] = c;
            board_console_putc( c );                    /* echo */
        }
    }
}

void console_start( UBaseType_t prio, uint16_t stack_words )
{
    s_rx = xStreamBufferCreate( CONSOLE_RX_BUF, 1u );
    configASSERT( s_rx != NULL );
    cli_register_commands();

