// Return the first item that starts with `prefix` and is at most
// `max_len` bytes long, or the fallback if none matches.
fn find_or<'a>(items: &'a [String], prefix: &'a str, max_len: &'a usize, fallback: &'a str) -> &'a str {
    for s in items {
        if s.starts_with(prefix) && s.len() <= *max_len {
            return s;
        }
    }
    fallback
}

fn main() {
    let items = vec![String::from("alpha"), String::from("beta")];
    let limit = 10;
    let found;
    {
        let prefix = String::from("b");
        found = find_or(&items, &prefix, &limit, "none");
    }
    println!("{found}");
}

