fn digital_root(n: u64) -> (u64, u32) {
    let mut current = n;
    let mut rounds: u32 = 0;

    while current >= 10 {
        let mut sum = 0;
        let mut temp = current;

        while temp > 0 {
            sum += temp % 10;
            temp /= 10;
        }

        current = sum;
        rounds += 1;
    }

    (current, rounds)
}

