// Write `next`: the state of a door after an action.
// Rules:
// - Closed + Pull        -> Open
// - Open + Push          -> Closed
// - Closed + Lock(c)     -> Locked { code: c }
// - Locked + Unlock(c)   -> Closed, but only when c equals the door's code;
//                           a wrong code leaves it Locked with the same code
// - every other pair     -> no change

#[derive(Debug, Clone, Copy, PartialEq)]
enum Door {
    Open,
    Closed,
    Locked { code: u16 },
}

#[derive(Debug, Clone, Copy)]
enum Action {
    Push,
    Pull,
    Lock(u16),
    Unlock(u16),
}

fn next(door: Door, action: Action) -> Door {
    match (door, action) {
        (Door::Closed, Action::Pull) => Door::Open,
        (Door::Open, Action::Push) => Door::Closed,
        (Door::Closed, Action::Lock(code)) => Door::Locked { code },
        (Door::Locked { code }, Action::Unlock(code2)) if code == code2 => Door::Closed,
        (Door::Locked { code }, Action::Unlock(_)) => Door::Locked { code },
        (door, _) => door,
    }
}

fn main() {
    let mut door = Door::Closed;
    for action in [Action::Lock(42), Action::Pull, Action::Unlock(7), Action::Unlock(42), Action::Pull] {
        door = next(door, action);
        println!("{action:?} -> {door:?}");
    }
}
