// Write a text cleaner that copies only when it has to.
//
// Run:    rustc --edition 2024 -o main p7.rs && ./main
// Submit: runs hidden tests against clean and clean_all.
//
// 1. clean(s): trim spaces at both ends, collapse every run of spaces inside
//    into one space, and lowercase ASCII letters. If the trimmed slice is
//    already clean (no double spaces, no uppercase), return it BORROWED: it is
//    a slice of `s`, so no allocation. Otherwise return an OWNED String.
//    Only ' ' counts as a space here.
// 2. clean_all(lines): clean every line. The results may borrow from the
//    strings the lines point to ('a), not from the `lines` slice itself.
// The signatures are given; read what each lifetime promises before you start.
// Do not change the signatures or main.

use std::borrow::Cow;

fn clean(s: &str) -> Cow<'_, str> {
    let trimmed = s.trim_matches(' ');

    let mut needs_change = trimmed.chars().any(|c| c.is_ascii_uppercase());
    if !needs_change {
        let mut prev_space = false;
        for ch in trimmed.chars() {
            if ch == ' ' {
                if prev_space {
                    needs_change = true;
                    break;
                }
                prev_space = true;
            } else {
                prev_space = false;
            }
        }
    }

    if !needs_change {
        return Cow::Borrowed(trimmed);
    }

    let mut out = String::with_capacity(trimmed.len());
    let mut prev_space = false;
    for ch in trimmed.chars() {
        if ch == ' ' {
            if !prev_space {
                out.push(' ');
                prev_space = true;
            }
        } else {
            out.push(ch.to_ascii_lowercase());
            prev_space = false;
        }
    }
    Cow::Owned(out)
}

fn clean_all<'a>(lines: &[&'a str]) -> Vec<Cow<'a, str>> {
    lines.iter().map(|line| clean(line)).collect()
}

fn main() {
    let text = String::from("  ready  \nTwo   Spaces\nfine\n");
    let cleaned = {
        let lines: Vec<&str> = text.lines().collect();
        clean_all(&lines)
    }; // `lines` is dropped here; `cleaned` borrows from `text`
    for c in &cleaned {
        let how = if matches!(c, Cow::Borrowed(_)) { "borrowed" } else { "owned" };
        println!("{c:?} {how}");
    }
}

