    Text(String),
    Sub(Box<Section>),
    List(Vec<Item>),
}

fn count_titles(item: &Item) -> usize {
    match item {
        Item::Text(_) => 0,
        Item::Sub(s) => 1 + count_titles(&s.body),
        Item::List(items) => items.iter().map(count_titles).sum(),
    }
}

