fn from_word(text: &str, word: &str) -> String {
    let lower_text = text.to_lowercase();
    let lower_word = word.to_lowercase();

    match lower_text.find(&lower_word) {
        Some(pos) => {
            // Convert byte position in lower_text back into a character boundary in text.
            let mut orig_pos = 0usize;
            let mut lower_pos = 0usize;

            for (idx, ch) in text.char_indices() {
                let lowered = ch.to_lowercase().to_string();
                if lower_pos == pos {
                    orig_pos = idx;
                    break;
                }
                lower_pos += lowered.len();
                orig_pos = idx + ch.len_utf8();
            }

            text[orig_pos..].to_string()
        }
        None => String::from("(not found)"),
    }
}

fn main() {
    println!("{}", from_word("Trip to BERLIN", "berlin"));
    println!("{}", from_word("\u{130}zmir to BERLIN", "berlin")); // "İzmir to BERLIN"
    println!("{}", from_word("\u{130}zmir \u{c7}ay", "\u{e7}ay")); // "İzmir Çay", "çay"
}

