```ts
import { useEffect, useState } from "react";
import { searchProducts, type Product } from "../api/search";

export function useSearch(query: string, inStockOnly: boolean) {
  const [results, setResults] = useState<Product[]>([]);
  const [total, setTotal] = useState(0);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const trimmed = query.trim();

    if (trimmed.length < 2) {
      setResults([]);
      setTotal(0);
      setLoading(false);
      setError(null);
      return;
    }

    const controller = new AbortController();
    const timer = window.setTimeout(() => {
      setLoading(true);
      setError(null);

      searchProducts(query, inStockOnly, controller.signal)
        .then((res) => {
          setResults(res.items);
          setTotal(res.total);
        })
        .catch((err) => {
          if (err instanceof DOMException && err.name === "AbortError") {
            return;
          }
          setError("Search failed. Try again.");
        })
        .finally(() => {
          if (!controller.signal.aborted) {
            setLoading(false);
          }
        });
    }, 300);

    return () => {
      clearTimeout(timer);
      controller.abort();
    };
  }, [query, inStockOnly]);

  return { results, total, loading, error };
}
```

Line by line:
- I trim the query once and use that for the length check.
- If the query is shorter than 2 characters, I clear the list, reset the total, turn off loading, and clear any error.
- I create an `AbortController` so a later keystroke can cancel the in-flight request.
- I start a 300 ms timer so we only search after the user pauses typing.
- Inside the timer, I set loading on, clear the error, and fire the request with the abort signal.
- On success, I store the returned items and total.
- On error, I ignore aborts and only show the failure message for real failures.
- In `finally`, I turn loading off unless this request was aborted.
- In the cleanup, I clear the pending timer and abort any request from the previous render, so older queries can’t overwrite newer ones.

This way, the UI only applies the latest live search for the text currently in the box.

