import { mkdirSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import type { RunRecord } from "./types.ts";

// runs/<runId>/messages.json: the whole run, for debugging and for the ticket.
export function saveRecord(record: RunRecord, dir = "runs"): string {
  const folder = join(dir, record.runId);
  mkdirSync(folder, { recursive: true });
  const path = join(folder, "messages.json");
  writeFileSync(path, `${JSON.stringify(record, null, 2)}\n`);
  return path;
}

