From 704c7966474657973e86b220c1055ec8a5c63666 Mon Sep 17 00:00:00 2001
From: Gateway team <gateway-team@example.com>
Date: Mon, 5 Oct 2026 23:40:00 +0000
Subject: [PATCH] queue: block on semaphores instead of a condition variable

Two bugs come from wakeups the condition variable loses: the stall where
acquisition waits for space while the queue is empty, and the stop that
sometimes hangs until systemd kills us. A semaphore post is counted even
when nobody is waiting yet, so neither can happen any more.

- rq_put waits on `slots`, rq_get waits on `items`; the mutex only
  guards the indices
- stop: the SIGTERM handler posts one stop token per worker (sem_post is
  async-signal-safe); rq_get returns NULL for a token. rq_close is gone.

Bench, 200 stop/start cycles (run 3 s, SIGTERM, TimeoutStopSec=10):
  main:   12 of 200 killed by the timeout
  branch: 0 of 200 killed, longest stop 1036 ms
---
 src/main.c       |  2 +-
 src/ring_queue.c | 60 +++++++++++++++++++++++-------------------------
 src/ring_queue.h | 16 +++++++------
 3 files changed, 39 insertions(+), 39 deletions(-)

diff --git a/src/main.c b/src/main.c
index 2372c0f..0ec408b 100644
--- a/src/main.c
+++ b/src/main.c
@@ -35,6 +35,7 @@ static void on_stop(int sig)
 {
 	(void)sig;
 	g_stop = 1;
+	rq_wake(&g_queue, GW_N_WORKERS);   /* sem_post: async-signal-safe */
 }

 static void on_hup(int sig)
@@ -206,7 +207,6 @@ int main(int argc, char **argv)

 	LOG_I("stopping");
 	thr_set_state("stopping");
-	rq_close(&g_queue);
 	uplink_stop(&g_uplink);
 	for (i = 0; i < GW_N_WORKERS; i++) {
 		struct timespec deadline;
diff --git a/src/ring_queue.c b/src/ring_queue.c
index afc345b..c1ad06b 100644
--- a/src/ring_queue.c
+++ b/src/ring_queue.c
@@ -1,42 +1,41 @@
 /* ring_queue.c: bounded queue of frames, acquisition -> workers.
  *
  * One producer (the acquisition thread), GW_N_WORKERS consumers.
+ * Two counting semaphores do the blocking: a post is never lost, even if
+ * nobody is waiting yet. The mutex only guards the indices.
  */
+#include <errno.h>
+
 #include "ring_queue.h"
 #include "log.h"

 int rq_init(struct ring_queue *q)
 {
-	int err;
-
 	q->head = q->tail = q->count = 0;
-	q->closed = false;
 	q->puts = q->gets = q->put_waits = q->get_waits = 0;
-	err = pthread_mutex_init(&q->lock, NULL);
-	if (err == 0)
-		err = pthread_cond_init(&q->changed, NULL);
-	return err;
+	if (sem_init(&q->slots, 0, GW_QUEUE_DEPTH) != 0 ||
+	    sem_init(&q->items, 0, 0) != 0)
+		return errno;
+	return pthread_mutex_init(&q->lock, NULL);
 }

 int rq_put(struct ring_queue *q, struct gw_buf *b)
 {
-	pthread_mutex_lock(&q->lock);
-	while (q->count == GW_QUEUE_DEPTH && !q->closed) {
-		q->put_waits++;
-		thr_set_state("rq_put wait");
-		pthread_cond_wait(&q->changed, &q->lock);
+	thr_set_state("rq_put wait");
+	while (sem_wait(&q->slots) != 0) {
+		if (errno != EINTR)
+			return -1;
 	}
 	thr_set_state("run");
-	if (q->closed) {
-		pthread_mutex_unlock(&q->lock);
-		return -1;
-	}
+
+	pthread_mutex_lock(&q->lock);
 	q->slot[q->tail] = b;
 	q->tail = (q->tail + 1) % GW_QUEUE_DEPTH;
 	q->count++;
 	q->puts++;
-	pthread_cond_signal(&q->changed);
 	pthread_mutex_unlock(&q->lock);
+
+	sem_post(&q->items);
 	return 0;
 }

@@ -44,37 +43,36 @@ struct gw_buf *rq_get(struct ring_queue *q)
 {
 	struct gw_buf *b = NULL;

-	pthread_mutex_lock(&q->lock);
-	while (q->count == 0 && !q->closed) {
-		q->get_waits++;
-		thr_set_state("rq_get wait");
-		pthread_cond_wait(&q->changed, &q->lock);
-	}
+	thr_set_state("rq_get wait");
+	if (sem_wait(&q->items) != 0)         /* interrupted: we are stopping */
+		return NULL;
 	thr_set_state("run");
+
+	pthread_mutex_lock(&q->lock);
 	if (q->count > 0) {
 		b = q->slot[q->head];
 		q->head = (q->head + 1) % GW_QUEUE_DEPTH;
 		q->count--;
 		q->gets++;
-		pthread_cond_signal(&q->changed);
 	}
 	pthread_mutex_unlock(&q->lock);
-	return b;
+
+	if (b != NULL)
+		sem_post(&q->slots);
+	return b;                             /* NULL: a stop token */
 }

-/* Called once, by main, after the acquisition loop has returned: no put can
- * race with it, and a bool store is atomic on every target we build for. */
-void rq_close(struct ring_queue *q)
+void rq_wake(struct ring_queue *q, int n)
 {
-	q->closed = true;
-	pthread_cond_broadcast(&q->changed);
+	while (n-- > 0)
+		sem_post(&q->items);
 }

 void rq_stats(struct ring_queue *q, struct rq_stats *st)
 {
 	pthread_mutex_lock(&q->lock);
 	st->count = q->count;
-	st->closed = q->closed;
+	st->closed = false;
 	st->puts = q->puts;
 	st->gets = q->gets;
 	st->put_waits = q->put_waits;
diff --git a/src/ring_queue.h b/src/ring_queue.h
index 765ae5d..7fcb56d 100644
--- a/src/ring_queue.h
+++ b/src/ring_queue.h
@@ -3,18 +3,19 @@
 #define RING_QUEUE_H

 #include <pthread.h>
+#include <semaphore.h>
 #include <stdbool.h>

 #include "gw.h"

 struct ring_queue {
-	pthread_mutex_t  lock;
-	pthread_cond_t   changed;        /* count went up or down */
+	pthread_mutex_t  lock;           /* head, tail, count, stats */
+	sem_t            slots;          /* free slots */
+	sem_t            items;          /* queued frames, plus stop tokens */
 	struct gw_buf   *slot[GW_QUEUE_DEPTH];
 	unsigned         head;           /* next to get */
 	unsigned         tail;           /* next free slot */
 	unsigned         count;
-	bool             closed;
 	/* stats, under lock */
 	unsigned long    puts, gets, put_waits, get_waits;
 };
@@ -26,12 +27,13 @@ struct rq_stats {
 };

 int            rq_init(struct ring_queue *q);
-/* Blocks while the queue is full. Returns -1 if the queue was closed. */
+/* Blocks while the queue is full. */
 int            rq_put(struct ring_queue *q, struct gw_buf *b);
-/* Blocks while the queue is empty. Returns NULL once closed and empty. */
+/* Blocks while the queue is empty. Returns NULL when woken to stop. */
 struct gw_buf *rq_get(struct ring_queue *q);
-/* Wake every waiter; puts fail from now on, gets drain what is left. */
-void           rq_close(struct ring_queue *q);
+/* Wakes n blocked rq_get() calls with nothing to take, so they return NULL.
+ * Only calls sem_post(), so it is safe in a signal handler. */
+void           rq_wake(struct ring_queue *q, int n);
 void           rq_stats(struct ring_queue *q, struct rq_stats *st);

 #endif

