#[derive(Debug)]
pub enum Expr {
    Num(i64),
    Add(Box<Expr>, Box<Expr>),
    Mul(Box<Expr>, Box<Expr>),
}

use Expr::{Add, Mul, Num};

pub fn add(a: Expr, b: Expr) -> Expr {
    Add(Box::new(a), Box::new(b))
}

pub fn mul(a: Expr, b: Expr) -> Expr {
    Mul(Box::new(a), Box::new(b))
}

pub fn eval(e: &Expr) -> i64 {
    match e {
        Num(n) => *n,
        Add(a, b) => eval(a) + eval(b), // &Box<Expr> coerces to &Expr
        Mul(a, b) => eval(a) * eval(b),
    }
}

pub fn count_nums(e: &Expr) -> usize {
    match e {
        Num(_) => 1,
        Add(a, b) | Mul(a, b) => count_nums(a) + count_nums(b),
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn single_number() {
        assert_eq!(eval(&Num(7)), 7);
        assert_eq!(count_nums(&Num(7)), 1);
    }

    #[test]
    fn nested() {
        // (2 + 3) * 4
        let e = mul(add(Num(2), Num(3)), Num(4));
        assert_eq!(eval(&e), 20);
        assert_eq!(count_nums(&e), 3);
    }

    #[test]
    fn helpers_build_boxes() {
        match add(Num(1), Num(2)) {
            Add(a, b) => {
                assert_eq!(eval(&a), 1);
                assert_eq!(eval(&b), 2);
            }
            other => panic!("expected Add, got {other:?}"),
