    public async Task<TimelineDto?> GetTimelineAsync(int shipmentId)
    {
        var sw = Stopwatch.StartNew();

        var shipment = await _db.Shipments
            .Include(s => s.Product)
            .Include(s => s.Events)
            .Include(s => s.TemperatureReadings)   // TRK-412
            .FirstOrDefaultAsync(s => s.Id == shipmentId);

        if (shipment is null)
            return null;

        var dto = new TimelineDto
        {
            ShipmentId = shipment.Id,
            Reference = shipment.Reference,
            Lane = $"{shipment.OriginPort} → {shipment.DestinationPort}",
            Status = shipment.Status.ToString(),
            MinCelsius = shipment.Product.MinCelsius,
            MaxCelsius = shipment.Product.MaxCelsius,
        };

        foreach (var e in shipment.Events.OrderBy(e => e.OccurredAt))
        {
            dto.Events.Add(new TimelineEventDto(e.OccurredAt, e.Code, e.Description, e.Location));
        }

        // TRK-409: loggers report raw values; apply the calibration that was valid when the reading was taken.
        foreach (var r in shipment.TemperatureReadings.OrderBy(r => r.RecordedAt))
        {
            var calibration = await _db.SensorCalibrations
                .Where(c => c.SensorId == r.SensorId && c.ValidFrom <= r.RecordedAt)
                .OrderByDescending(c => c.ValidFrom)
                .FirstOrDefaultAsync();

            var celsius = r.RawCelsius + (calibration?.OffsetCelsius ?? 0m);

            dto.Readings.Add(new TemperatureReadingDto
            {
                RecordedAt = r.RecordedAt,
                SensorId = r.SensorId,
                Celsius = Math.Round(celsius, 1),
                Excursion = celsius < shipment.Product.MinCelsius || celsius > shipment.Product.MaxCelsius,
            });
        }

        // TRK-412: "current reading" tile. Readings in SQL lag up to 15 minutes behind the device.
        if (shipment.Status == ShipmentStatus.InTransit && shipment.TelemetryDeviceId is not null)
        {
            var latest = await _telemetry.GetLatestAsync(shipment.TelemetryDeviceId);
            dto.Current = new CurrentReadingDto(latest.RecordedAt, latest.Celsius, latest.BatteryPercent);
        }

        _logger.LogInformation(
            "Timeline built for {Reference}: events={Events} readings={Readings} elapsed={Elapsed}ms",
            shipment.Reference, dto.Events.Count, dto.Readings.Count, sw.ElapsedMilliseconds);

        return dto;
    }
}

