   2 | // A tiny type that prints a line when it is dropped.
   3 | // `struct` is covered in 04 and `impl Drop` in 11. Here they only make drops visible.
   4 | struct Tracer(&'static str);
   5 | 
   6 | impl Drop for Tracer {
   7 |     fn drop(&mut self) {
   8 |         println!("  drop {}", self.0);
   9 |     }
  10 | }
  11 | 
  12 | fn finish(t: Tracer) {
  13 |     println!("finish got {}", t.0);
  14 | }
  15 | 
  16 | fn main() {
  17 |     let _first = Tracer("first");
  18 |     let _second = Tracer("second");
  19 |     {
  20 |         let _inner = Tracer("inner");
  21 |         println!("leaving inner block");
  22 |     }
  23 |     let moved = Tracer("moved");
  24 |     finish(moved);
  25 |     println!("back in main");
  26 | 
  27 |     // `_` is not a binding: a new value written there is dropped at once.
  28 |     let _ = Tracer("unbound");
  29 |     // But `let _ = kept;` on an existing variable does nothing: `kept` still owns it.
  30 |     let kept = Tracer("kept");
  31 |     let _ = kept;
  32 |     println!("after let _ = kept");
  33 | 
  34 |     // A tuple drops its fields first to last, after later locals.
  35 |     let _pair = (Tracer("pair.0"), Tracer("pair.1"));
  36 |     println!("leaving main");
  37 | }

