use std::borrow::Cow;

fn clean(s: &str) -> Cow<'_, str> {
    let trimmed = s.trim();
    let mut out = String::new();
    let mut prev_space = false;
    let mut changed = trimmed.len() != s.len();

    for ch in trimmed.chars() {
        if ch == ' ' {
            if prev_space {
                changed = true;
                continue;
            }
            prev_space = true;
            out.push(' ');
        } else {
            let lower = ch.to_ascii_lowercase();
            if lower != ch {
                changed = true;
            }
            prev_space = false;
            out.push(lower);
        }
    }

    if !changed {
        Cow::Borrowed(trimmed)
    } else {
        Cow::Owned(out)
    }
}

fn clean_all<'a>(lines: &[&'a str]) -> Vec<Cow<'a, str>> {
    lines.iter().map(|s| clean(s)).collect()
}

fn main() {
    let text = String::from("  ready  \nTwo   Spaces\nfine\n");
    let cleaned = {
        let lines: Vec<&str> = text.lines().collect();
        clean_all(&lines)
    }; // `lines` is dropped here; `cleaned` borrows from `text`
    for c in &cleaned {
        let how = if matches!(c, Cow::Borrowed(_)) { "borrowed" } else { "owned" };
        println!("{c:?} {how}");
    }
}
