import { useEffect, useState } from "react";
import { formatDistanceToNow } from "date-fns";
import { api } from "../../lib/api";
import { CurrentReadingTile } from "./CurrentReadingTile";
import { EventList } from "./EventList";
import { TimelineChart } from "./TimelineChart";

interface Props {
  shipmentId: number;
  range: { from: string; to: string };
}

export function ShipmentTimeline({ shipmentId, range }: Props) {
  const [timeline, setTimeline] = useState<any>(null);
  const [lastUpdated, setLastUpdated] = useState<Date | null>(null);

  const filters = { from: range.from, to: range.to, includeReadings: true };

  const loadTimeline = () => {
    api
      .get(`/api/shipments/${shipmentId}/timeline`, { params: filters })
      .then((res: any) => {
        setTimeline(res.data);
        setLastUpdated(new Date());
      });
  };

  useEffect(() => {
    loadTimeline();
  }, [shipmentId, filters]);

  // TRK-418: refresh every 30 seconds so the control room sees new readings
  useEffect(() => {
    setInterval(loadTimeline, 30_000);
  }, [shipmentId]);

  const excursions = timeline
    ? timeline.readings.filter((r: any) => r.excursion).length
    : 0;

  return (
    <section className="shipment-timeline">
      <header className="shipment-timeline__header">
        <h2>Timeline</h2>
        {excursions > 0 && (
          <span className="badge badge--danger">{excursions} excursions</span>
        )}
        {lastUpdated && (
          <span className="muted">Updated {formatDistanceToNow(lastUpdated)} ago</span>
        )}
      </header>

      {timeline && (
        <>
          <CurrentReadingTile current={timeline.current} />
          <TimelineChart
            points={timeline.readings.map((r: any) => ({
              x: r.recordedAt,
              y: r.temp,
              excursion: r.excursion,
            }))}
            min={timeline.minCelsius}
            max={timeline.maxCelsius}
            unit="°C"
          />
          <EventList events={timeline.events} />
        </>
      )}
    </section>
  );
}

