use std::ops::Add;

// Goal: add up any slice of numbers, whatever the number type.
fn total<T>(items: &[T]) -> Option<T>
where
    T: Copy + Add<Output = T>,
{
    if items.is_empty() {
        return None;
    }

    let mut sum = items[0];
    for x in &items[1..] {
        sum = sum + *x;
    }
    Some(sum)
}

fn main() {
    let ints = [3, 4, 5];
    let floats = [0.5, 0.25];
    let empty_ints: [i32; 0] = [];

    println!("{:?}", total(&ints));
    println!("{:?}", total(&floats));
    println!("{:?}", total(&empty_ints));
}
