// Write the methods of Budget.
// Rules:
// - new(limit) starts with nothing spent.
// - spend(amount) refuses an amount that would go over the limit: it returns
//   false and changes nothing. Otherwise it records the amount and returns true.
// - remaining() is how much can still be spent.
// - close() turns the budget into a report like "spent 7 of 10". The budget is
//   not needed after that.

struct Budget {
    limit: u32,
    spent: u32,
}

impl Budget {
    fn new(limit: u32) -> Self {
        Budget { limit, spent: 0 }
    }

    fn spend(&mut self, amount: u32) -> bool {
        // Compare against what is left: `self.spent + amount` could overflow.
        if amount > self.remaining() {
            return false;
        }
        self.spent += amount;
        true
    }

    fn remaining(&self) -> u32 {
        self.limit - self.spent
    }

    fn close(self) -> String {
        format!("spent {} of {}", self.spent, self.limit)
    }
}

fn main() {
    let mut b = Budget::new(10);
    println!("{}", b.spend(4));
    println!("{}", b.spend(8));
    println!("{}", b.spend(3));
    println!("remaining {}", b.remaining());
    println!("{}", b.close());
}

