/// (smallest, largest), or None for an empty slice.
/// min_max(&[4, 9, 1]) == Some((1, 9))
pub fn min_max<T: PartialOrd + Clone>(items: &[T]) -> Option<(T, T)> {
    if items.is_empty() {
        return None;
    }

    let mut min = items[0].clone();
    let mut max = items[0].clone();

    for x in &items[1..] {
        if *x < min {
            min = x.clone();
        }
        if *x > max {
            max = x.clone();
        }
    }

    Some((min, max))
}

fn main() {
    println!("{:?}", min_max(&[4, 9, 1]));
    println!("{:?}", min_max(&[2.5, -1.0]));
    println!("{:?}", min_max(&['q', 'b', 'x']));
    let none: [i32; 0] = [];
    println!("{:?}", min_max(&none));
}
