fn eval(expr: &str) -> Result<i64, CalcError> {
    let mut parts = expr.split_whitespace();
    let a = parts.next().ok_or(CalcError::Format)?;
    let op = parts.next().ok_or(CalcError::Format)?;
    let b = parts.next().ok_or(CalcError::Format)?;
