/*
 * cli_cmds.c - console commands (FreeRTOS-Plus-CLI). task-stats and
 * run-time-stats are the ones from the FreeRTOS+CLI demo.
 */
#include <stdio.h>
#include <string.h>

#include "FreeRTOS.h"
