fn word_at(text: &str, n: usize) -> &str {
    let mut start = None;
    let mut word_index = 0usize;

    for (i, ch) in text.char_indices() {
        if ch == ' ' {
            if let Some(s) = start.take() {
                if word_index == n {
                    return &text[s..i];
                }
                word_index += 1;
            }
        } else if start.is_none() {
            start = Some(i);
        }
    }

    if let Some(s) = start {
        if word_index == n {
            return &text[s..];
        }
    }

    ""
}

