export interface ValidationResult {
  valid: boolean;
  message?: string;
}

export async function validateRemote(
  rule: string,
  value: string,
  country: string,
): Promise<ValidationResult> {
  const params = new URLSearchParams({ value, country });
  const res = await fetch(`/api/validate/${rule}?${params}`);
  if (!res.ok) {
    throw new Error(`validate ${rule} failed: ${res.status}`);
  }
  return res.json();
}

