import { useState, type CSSProperties, type ReactNode } from 'react';
import { useForm } from './FormProvider';
import { useRemoteValidation } from './useRemoteValidation';
import type { FieldSchema, FieldValue } from './types';

interface FieldProps {
  field: FieldSchema;
  value: FieldValue;
  onChange: (name: string, value: FieldValue) => void;
  style?: CSSProperties;
  children?: ReactNode;
}

export function Field({ field, value, onChange, style, children }: FieldProps) {
  const { errors } = useForm();
  const [text, setText] = useState(() => toText(value));
  useRemoteValidation(field, text);

  const id = `f-${field.name}`;
  const error = errors[field.name];

  if (field.type === 'checkbox') {
    return (
      <div className="field field-checkbox" style={style}>
        <input
          id={id}
          type="checkbox"
          checked={value === true}
          onChange={(e) => onChange(field.name, e.target.checked)}
        />
        <label htmlFor={id}>{field.label}</label>
        {children}
      </div>
    );
  }

  return (
    <div className="field" style={style}>
      <label htmlFor={id}>
        {field.label}
        {field.required && ' *'}
      </label>
      {field.type === 'select' ? (
        <select
          id={id}
          value={typeof value === 'string' ? value : ''}
          onChange={(e) => onChange(field.name, e.target.value)}
        >
          <option value="">Select...</option>
          {field.options?.map((option) => (
            <option key={option.value} value={option.value}>
              {option.label}
            </option>
          ))}
        </select>
      ) : (
        <input
          id={id}
          type={field.type === 'date' ? 'date' : 'text'}
          inputMode={field.type === 'number' ? 'decimal' : undefined}
          value={text}
          aria-invalid={error ? true : undefined}
          onChange={(e) => {
            setText(e.target.value);
            onChange(field.name, fromText(field, e.target.value));
          }}
        />
      )}
      {children}
      {error && (
        <p className="field-error" role="alert">
          {error}
        </p>
      )}
    </div>
  );
}

function toText(value: FieldValue): string {
  return value === undefined || typeof value === 'boolean' ? '' : value;
}

function fromText(field: FieldSchema, text: string): FieldValue {
  if (field.type === 'number') {
    const normalised = text.replace(/[,\s]/g, '');
    return normalised === '' ? undefined : normalised;
  }
  return text;
}

