}

export function FormProvider({ schema, initialValues = {}, children }: FormProviderProps) {
  const [values, setValues] = useState<FormValues>(initialValues);
  const [errors, setErrors] = useState<FormErrors>({});

  const setValue = (name: string, value: FieldValue) => {
    setValues((prev) => ({ ...prev, [name]: value }));
  };

  const setError = (name: string, message: string | undefined) => {
    setErrors((prev) => (prev[name] === message ? prev : { ...prev, [name]: message }));
  };

  return (
    <FormContext value={{ schema, values, errors, setValue, setError }}>
      {children}
    </FormContext>
  );
}

export function useForm(): FormContextValue {
  const ctx = useContext(FormContext);
  if (!ctx) {
    throw new Error('useForm must be used inside <FormProvider>');
  }
  return ctx;
}

