import { useCallback, useEffect } from 'react';
import { validateRemote } from '../api/validate';
import { debounce } from './debounce';
import { useForm } from './FormProvider';
import type { FieldSchema } from './types';

export function useRemoteValidation(field: FieldSchema, text: string) {
  const { values, setError } = useForm();
  const country = typeof values['company.country'] === 'string' ? values['company.country'] : '';

  const check = useCallback(
    debounce(async (value: string) => {
      const result = await validateRemote(field.validate!, value, country);
      setError(field.name, result.valid ? undefined : result.message);
    }, 400),
    [field.name],
  );

  useEffect(() => {
    if (field.validate && text.trim() !== '') {
      check(text);
    }
  }, [text, check]);
}

--- src/form/visibility.ts ---
import type { FieldSchema, FormValues } from './types';

export function isVisible(field: FieldSchema, values: FormValues): boolean {
  if (!field.showIf) {
    return true;
  }
  return values[field.showIf.field] === field.showIf.equals;
}

