/* log.c: line logger (one mutex around the FILE) and the thread table. */
#include <pthread.h>
#include <stdarg.h>
#include <stdio.h>
#include <string.h>
#include <time.h>
#include <unistd.h>

#include "log.h"

bool g_log_verbose;

static pthread_mutex_t log_lock = PTHREAD_MUTEX_INITIALIZER;
static FILE *log_fp;
static const char *log_path;

struct thr_slot {
	char            name[16];
	pid_t           tid;
	const char     *state;
	struct timespec since;           /* CLOCK_MONOTONIC */
	bool            exited;
};

static pthread_mutex_t thr_lock = PTHREAD_MUTEX_INITIALIZER;
static struct thr_slot thr_table[THR_MAX];
static int thr_count;
static __thread struct thr_slot *thr_self;

int log_open(const char *path, bool verbose)
{
	g_log_verbose = verbose;
	log_path = path;
	log_fp = path ? fopen(path, "a") : stderr;
	if (log_fp == NULL)
		return -1;
	setvbuf(log_fp, NULL, _IOLBF, 0);
	return 0;
}

void log_reopen(void)
{
	FILE *fp;

	if (log_path == NULL)
		return;
	pthread_mutex_lock(&log_lock);
	fp = fopen(log_path, "a");
	if (fp != NULL) {
		setvbuf(fp, NULL, _IOLBF, 0);
		fclose(log_fp);
		log_fp = fp;
	}
	pthread_mutex_unlock(&log_lock);
}

void log_msg(char level, const char *fmt, ...)
{
	struct timespec ts;
	struct tm tm;
	char line[512];
	int n;
	va_list ap;

	clock_gettime(CLOCK_REALTIME, &ts);
	gmtime_r(&ts.tv_sec, &tm);
	n = snprintf(line, sizeof(line), "%04d-%02d-%02d %02d:%02d:%02d.%03ld %c %-5s ",
		     tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour,
		     tm.tm_min, tm.tm_sec, ts.tv_nsec / 1000000, level,
		     thr_self ? thr_self->name : "?");
	va_start(ap, fmt);
	vsnprintf(line + n, sizeof(line) - n, fmt, ap);
	va_end(ap);

	pthread_mutex_lock(&log_lock);
	fputs(line, log_fp);
	fputc('\n', log_fp);
	pthread_mutex_unlock(&log_lock);
}

void thr_register(const char *name)
{
	pthread_mutex_lock(&thr_lock);
	if (thr_count < THR_MAX) {
		thr_self = &thr_table[thr_count++];
		snprintf(thr_self->name, sizeof(thr_self->name), "%s", name);
		thr_self->tid = gettid();
		thr_self->state = "run";
		clock_gettime(CLOCK_MONOTONIC, &thr_self->since);
	}
	pthread_mutex_unlock(&thr_lock);
}

void thr_set_state(const char *state)
{
	if (thr_self == NULL)
		return;
	pthread_mutex_lock(&thr_lock);
	if (thr_self->state != state) {
		thr_self->state = state;
		clock_gettime(CLOCK_MONOTONIC, &thr_self->since);
	}
	pthread_mutex_unlock(&thr_lock);
}

void thr_exited(void)
{
	thr_set_state("exited");
	pthread_mutex_lock(&thr_lock);
	if (thr_self != NULL)
		thr_self->exited = true;
	pthread_mutex_unlock(&thr_lock);
}

void thr_dump(void)
{
	struct timespec now;
	int i;

	clock_gettime(CLOCK_MONOTONIC, &now);
	pthread_mutex_lock(&thr_lock);
	LOG_W("  %-6s %-6s %-16s %s", "thread", "tid", "state", "for");
	for (i = 0; i < thr_count; i++) {
		const struct thr_slot *t = &thr_table[i];
		double secs = (now.tv_sec - t->since.tv_sec) +
			      (now.tv_nsec - t->since.tv_nsec) / 1e9;

		LOG_W("  %-6s %-6d %-16s %.1f s", t->name, (int)t->tid, t->state, secs);
	}
	pthread_mutex_unlock(&thr_lock);
}

--- src/log.h ---
/* log.h: line logger and the thread table the watchdog dumps. */
#ifndef GW_LOG_H
#define GW_LOG_H

#include <stdbool.h>

extern bool g_log_verbose;

int  log_open(const char *path, bool verbose);   /* path NULL: stderr */
void log_reopen(void);                           /* after logrotate moved the file */
void log_msg(char level, const char *fmt, ...) __attribute__((format(printf, 2, 3)));

#define LOG_D(...) do { if (g_log_verbose) log_msg('D', __VA_ARGS__); } while (0)
#define LOG_I(...) log_msg('I', __VA_ARGS__)
#define LOG_W(...) log_msg('W', __VA_ARGS__)
#define LOG_E(...) log_msg('E', __VA_ARGS__)

/* Thread table. Each thread registers itself once, then marks what it is
 * about to block on, so a dump shows where every thread is. */
#define THR_MAX 8

void thr_register(const char *name);
void thr_set_state(const char *state);           /* a string literal */
void thr_exited(void);
void thr_dump(void);                             /* one log line per thread */

#endif

--- src/main.c ---
/* main.c: sensor-gw: sensor hub -> queue -> workers -> collector.
 *
 *   sensor-gw -d /dev/ttyS2 -c collector.local:8443 -i <device-id> [-l file] [-v]
 *
 * Threads: main runs acquisition; wk0..wk3 encode and upload; wdog prints
 * stats and dumps state when uploads stop. Signals: TERM/INT stop,
 * HUP reopens the log (logrotate), USR1 asks for a stats line now.
 */
#include <errno.h>
#include <pthread.h>
#include <semaphore.h>
#include <signal.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>

#include "acq.h"
#include "buf_pool.h"
#include "log.h"
#include "ring_queue.h"
#include "uplink.h"
#include "worker.h"

static volatile sig_atomic_t g_stop;
static sem_t g_stats_req;              /* posted by SIGUSR1 */

static struct ring_queue g_queue;
static struct buf_pool   g_pool;
static struct uplink     g_uplink;
static struct gw         g_gw = { &g_queue, &g_pool, &g_uplink };

static void on_stop(int sig)
{
	(void)sig;
	g_stop = 1;
}

static void on_hup(int sig)
{
	(void)sig;
	log_reopen();
}

static void on_usr1(int sig)
{
	(void)sig;
	sem_post(&g_stats_req);        /* async-signal-safe */
}

static void log_stats(void)
{
	struct rq_stats q;
	struct pool_stats p;
	struct uplink_stats u;

	rq_stats(&g_queue, &q);
	pool_stats(&g_pool, &p);
	uplink_stats(&g_uplink, &u);
	LOG_I("stats queue %u/%d puts %lu gets %lu | pool free %d min %d waits %lu | "
	      "uplink slots %d in_flight %u max %u sent %lu 429 %lu rejected %lu failed %lu",
	      q.count, GW_QUEUE_DEPTH, q.puts, q.gets, p.nfree, p.min_free, p.waits,
	      u.slots_free, u.in_flight, u.in_flight_max, u.sent, u.http_429,
	      u.rejected, u.failed);
}

static void dump_state(const char *why)
{
	struct rq_stats q;
	struct pool_stats p;
	struct uplink_stats u;

	rq_stats(&g_queue, &q);
	pool_stats(&g_pool, &p);
	uplink_stats(&g_uplink, &u);
	LOG_W("%s, state dump follows", why);
	LOG_W("  queue  count %u/%d closed %d puts %lu gets %lu put_waits %lu get_waits %lu",
	      q.count, GW_QUEUE_DEPTH, q.closed, q.puts, q.gets, q.put_waits, q.get_waits);
	LOG_W("  pool   free %d/%d waits %lu", p.nfree, GW_POOL_BUFS, p.waits);
	LOG_W("  uplink slots %d in_flight %u sent %lu 429 %lu rejected %lu failed %lu",
	      u.slots_free, u.in_flight, u.sent, u.http_429, u.rejected, u.failed);
	thr_dump();
}

static sem_t g_wdog_quit;              /* posted once by main at stop */

static void *wdog_main(void *arg)
{
	struct timespec one_s = { 1, 0 };
	unsigned ticks = 0;
	bool dumped = false;

	(void)arg;
	thr_register("wdog");
	while (sem_trywait(&g_wdog_quit) != 0) {
		struct uplink_stats u;

		thr_set_state("sleep");
		nanosleep(&one_s, NULL);
		thr_set_state("run");
		if (sem_trywait(&g_stats_req) == 0 || ++ticks % GW_STATS_EVERY_S == 0)
			log_stats();

		uplink_stats(&g_uplink, &u);
		if (u.since_sent_s >= GW_STALL_S && !dumped) {
			dump_state("no frame uploaded for 30 s");
			dumped = true;
		} else if (u.since_sent_s < GW_STALL_S) {
			dumped = false;
		}
	}
	thr_exited();
	return NULL;
}

static int install(int sig, void (*fn)(int))
{
	struct sigaction sa = { .sa_handler = fn };

	sigemptyset(&sa.sa_mask);
	if (sigaction(sig, &sa, NULL) != 0) {
		fprintf(stderr, "sigaction(%d): %s\n", sig, strerror(errno));
		return -1;
	}
	return 0;
}

static void usage(void)
{
	fprintf(stderr, "usage: sensor-gw -d tty -c host:port -i device-id [-l logfile] [-v]\n");
	exit(2);
}

int main(int argc, char **argv)
{
	const char *dev = NULL, *collector = NULL, *device = NULL, *logfile = NULL;
	struct worker workers[GW_N_WORKERS];
	pthread_t wk_tid[GW_N_WORKERS], wdog_tid;
	struct acq acq;
	char host[128], *port;
	bool verbose = false;
	sigset_t set;
	int opt, i;

	while ((opt = getopt(argc, argv, "d:c:i:l:v")) != -1) {
		switch (opt) {
		case 'd': dev = optarg; break;
		case 'c': collector = optarg; break;
		case 'i': device = optarg; break;
		case 'l': logfile = optarg; break;
		case 'v': verbose = true; break;
		default: usage();
		}
	}
	if (!dev || !collector || !device)
		usage();
	snprintf(host, sizeof(host), "%s", collector);
	port = strrchr(host, ':');
	if (port == NULL)
		usage();
	*port++ = '\0';

	if (log_open(logfile, verbose) != 0) {
		perror(logfile);
		return 1;
	}
	thr_register("acq");
	LOG_I("sensor-gw %s starting: %d workers, queue %d, pool %d, uplink slots %d",
	      GW_VERSION, GW_N_WORKERS, GW_QUEUE_DEPTH, GW_POOL_BUFS, GW_UPLINK_SLOTS);

	sem_init(&g_stats_req, 0, 0);
	sem_init(&g_wdog_quit, 0, 0);
	if (install(SIGTERM, on_stop) || install(SIGINT, on_stop) ||
	    install(SIGHUP, on_hup) || install(SIGUSR1, on_usr1))
		return 1;
	signal(SIGPIPE, SIG_IGN);

	if (rq_init(&g_queue) || pool_init(&g_pool) ||
	    uplink_init(&g_uplink, host, port, device)) {
		LOG_E("init failed");
		return 1;
	}
	if (acq_open(&acq, dev, &g_gw) != 0) {
		LOG_E("%s: %s", dev, strerror(errno));
		return 1;
	}

	for (i = 0; i < GW_N_WORKERS; i++) {
		workers[i].gw = &g_gw;
		workers[i].idx = i;
		snprintf(workers[i].name, sizeof(workers[i].name), "wk%d", i);
		pthread_create(&wk_tid[i], NULL, worker_main, &workers[i]);
