fn find_index(items: &[&str], target: &str) -> Option<usize> {
    for i in 0..items.len() {
        if items[i] == target {
            return Some(i);
        }
    }
    None
}

fn print_next(items: &[&str], target: &str) {
    match find_index(items, target) {
        Some(i) if i + 1 < items.len() => println!("{}", items[i + 1]),
        Some(_) => println!("No item after {}", target),
        None => println!("Target {} not found", target),
    }
}

fn main() {
    let items = ["a", "b", "c"];

    print_next(&items, "b");
    print_next(&items, "c");
    print_next(&items, "z");
}

