fn load(attempt: u32) -> Result<i32, LoadError> {
    if attempt < 2 {
        return Err(LoadError::TimedOut);
    }
    let n: i32 = "x7".parse().map_err(LoadError::BadData)?;
    Ok(n)
}

fn main() {
    // Retry up to 4 times, but only on timeouts.
    for attempt in 0..4 {
        match load(attempt) {
            Ok(n) => {
                println!("loaded {n}");
                break;
            }
            Err(LoadError::TimedOut) => {
                println!("attempt {attempt} failed: timed out");
                continue;
            }
            Err(LoadError::BadData(e)) => {
                println!("attempt {attempt} failed: bad data: {e}");
                break;
            }
        }
    }
}
