use std::fmt;
use std::num::ParseIntError;

#[derive(Debug, PartialEq)]
enum CalcError {
    Format,
    BadNumber(ParseIntError),
    UnknownOp(String),
    DivByZero,
    Overflow,
}

// Given.
impl fmt::Display for CalcError {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        match self {
            CalcError::Format => write!(f, "expected <number> <op> <number>"),
            CalcError::BadNumber(e) => write!(f, "bad number: {e}"),
            CalcError::UnknownOp(op) => write!(f, "unknown operator {op:?}"),
            CalcError::DivByZero => write!(f, "division by zero"),
            CalcError::Overflow => write!(f, "result does not fit in i64"),
        }
    }
}

impl std::error::Error for CalcError {}

impl From<ParseIntError> for CalcError {
    fn from(e: ParseIntError) -> Self {
        CalcError::BadNumber(e)
    }
}

fn eval(expr: &str) -> Result<i64, CalcError> {
    let parts: Vec<&str> = expr.split_whitespace().collect();
    let [a, op, b] = parts.as_slice() else {
        return Err(CalcError::Format);
    };
    let a: i64 = a.parse()?;
    let b: i64 = b.parse()?;
    // checked_* return None instead of panicking on overflow.
    let result = match *op {
        "+" => a.checked_add(b),
        "-" => a.checked_sub(b),
        "*" => a.checked_mul(b),
        "/" if b == 0 => return Err(CalcError::DivByZero),
        "/" => a.checked_div(b), // i64::MIN / -1 overflows
        other => return Err(CalcError::UnknownOp(other.to_string())),
    };
    result.ok_or(CalcError::Overflow)
}

fn eval_lines(text: &str) -> (Vec<i64>, Vec<String>) {
    let mut good = Vec::new();
    let mut bad = Vec::new();
    for (i, line) in text.lines().enumerate() {
        if line.trim().is_empty() {
            continue;
        }
        match eval(line) {
            Ok(n) => good.push(n),
            Err(e) => bad.push(format!("line {}: {e}", i + 1)),
        }
    }
    (good, bad)
}

fn main() {
    for expr in ["6 * 7", "1 / 0", "9223372036854775807 + 1", "2 ^ 3", "x + 1", "5 -"] {
        match eval(expr) {
            Ok(n) => println!("{expr} = {n}"),
            Err(e) => println!("{expr}: {e}"),
        }
    }
    println!("{:?}", eval_lines("1 + 2\n\n8 / 0\n10 - 4"));
}

