import type { LlmClient, LlmResponse } from "./llm.ts";
import type { AgentMessage, AgentName, PipelineConfig, RunRecord, RunStatus } from "./types.ts";
import { createAgents } from "./agents.ts";
import { loadPrompt } from "./prompts.ts";

export type PipelineDeps = {
  llm: LlmClient;
  config: PipelineConfig;
  now?: () => Date;
  log?: (line: string) => void;
  signal?: AbortSignal;
};

// The researcher's notes run to several hundred words and the coder only needs
// the gist, so the handoff condenses them into a short brief first.
export async function summarize(
  llm: LlmClient,
  model: string,
  notes: string,
  maxWords = 120,
  signal?: AbortSignal,
): Promise<LlmResponse> {
  const system = loadPrompt("summarizer", { maxWords });
  return llm.complete({ agent: "summarizer", model, system, input: notes, signal });
}

export function verdict(review: string): "APPROVED" | "CHANGES_REQUESTED" {
  const last = review.trim().split("\n").at(-1) ?? "";
  return /^VERDICT:\s*APPROVED\b/.test(last) ? "APPROVED" : "CHANGES_REQUESTED";
}

const wordCount = (text: string) => text.split(/\s+/).filter(Boolean).length;

function firstLine(text: string, max = 150): string {
  const line = text.trim().split("\n")[0] ?? "";
  return line.length > max ? `${line.slice(0, max - 3)}...` : line;
}

export async function runPipeline(
  run: { runId: string; ticket: string; task: string },
  deps: PipelineDeps,
): Promise<RunRecord> {
  const { llm, config, signal } = deps;
  const now = deps.now ?? (() => new Date());
  const log = deps.log ?? ((line: string) => console.log(line));
  const agents = createAgents(llm, config, signal);

  const messages: AgentMessage[] = [];
  const queue: AgentMessage[] = [];
  const startedAt = now().toISOString();
  let status: RunStatus = "escalated";

  // Revision rounds used per change under review, so the coder and the
  // reviewer can't send work back and forth forever.
  const rounds = new Map<string, number>();

  function send(from: AgentName, to: AgentName, content: string, extra: Partial<AgentMessage> = {}) {
    const msg: AgentMessage = {
      id: `m${messages.length + 1}`,
      from,
      to,
      content,
      timestamp: now().toISOString(),
      ...extra,
    };
    messages.push(msg);
    queue.push(msg);
    const u = msg.usage;
    const cost = u ? `, ${u.model}, ${u.tokens} tokens, ${u.toolCalls} tool calls, ${(u.ms / 1000).toFixed(1)}s` : "";
    log(`${msg.id} ${from} -> ${to}: ${wordCount(content)} words${cost} | ${firstLine(content)}`);
  }

  send("orchestrator", "researcher", run.task);

  while (queue.length > 0) {
    const msg = queue.shift()!;

    switch (msg.to) {
      case "researcher": {
        const res = await agents.researcher.run(msg.content);
        send("researcher", "summarizer", res.content, { inReplyTo: msg.id, usage: res.usage });
        break;
      }

      case "summarizer": {
        const res = await summarize(llm, config.models.summarizer, msg.content, config.handoff.maxWords, signal);
        send("summarizer", "coder", res.text, { inReplyTo: msg.id, usage: res.usage });
        break;
      }

      case "coder": {
        // The coder works from its brief, the reviews sent to it and its own earlier changes.
        const coderInput = messages
          .filter((m) => m.to === "coder" || m.from === "coder")
          .map((m) => `[From ${m.from}]: ${m.content}`)
          .join("\n\n");
        const res = await agents.coder.run(coderInput);
        send("coder", "reviewer", res.content, { inReplyTo: msg.id, usage: res.usage });
        break;
      }

      case "reviewer": {
        // The reviewer judges the code on its own merits: it gets the coder's messages only.
        const reviewerInput = messages
          .filter((m) => m.from === "coder")
          .map((m) => `[From ${m.from}]: ${m.content}`)
          .join("\n\n");
        const res = await agents.reviewer.run(reviewerInput);

        if (verdict(res.content) === "APPROVED") {
          status = "approved";
          send("reviewer", "orchestrator", res.content, { inReplyTo: msg.id, usage: res.usage });
          break;
        }

        const used = rounds.get(msg.id) ?? 0;
        if (used >= config.review.maxRevisionRounds) {
          status = "escalated";
          send("reviewer", "orchestrator", `ESCALATED after ${used} revision rounds.\n\n${res.content}`, {
            inReplyTo: msg.id,
            usage: res.usage,
          });
          break;
        }
        rounds.set(msg.id, used + 1);
        log(`review of ${msg.id}: CHANGES_REQUESTED, revision round ${used + 1}/${config.review.maxRevisionRounds}`);
        send("reviewer", "coder", res.content, { inReplyTo: msg.id, usage: res.usage });
        break;
      }

      case "orchestrator":
        // The run's last message: nothing left to route.
        break;
    }
  }

  const totals = messages.reduce(
    (t, m) => ({ tokens: t.tokens + (m.usage?.tokens ?? 0), toolCalls: t.toolCalls + (m.usage?.toolCalls ?? 0) }),
    { tokens: 0, toolCalls: 0 },
  );

  return {
    runId: run.runId,
    ticket: run.ticket,
    status,
    startedAt,
    finishedAt: now().toISOString(),
    config,
    totals,
    messages,
  };
}

