// The few calls the pipeline makes to the company's issue tracker.

const BASE = process.env.TRACKER_URL ?? "http://tracker.internal/api";

async function call<T>(method: string, path: string, body?: unknown): Promise<T> {
  const res = await fetch(`${BASE}${path}`, {
    method,
    headers: {
      "content-type": "application/json",
      authorization: `Bearer ${process.env.TRACKER_TOKEN}`,
    },
    body: body === undefined ? undefined : JSON.stringify(body),
  });
  if (!res.ok) throw new Error(`tracker ${method} ${path}: ${res.status}`);
  return (await res.json()) as T;
}

// The ticket as the researcher sees it: "KEY: title", a blank line, the description.
export async function fetchTicket(key: string): Promise<string> {
  const t = await call<{ key: string; title: string; description: string }>("GET", `/issues/${key}`);
  return `${t.key}: ${t.title}\n\n${t.description}`;
}

export async function commentOnTicket(key: string, text: string): Promise<void> {
  await call("POST", `/issues/${key}/comments`, { body: text });
}

// Takes the oldest open ticket with the label and marks it as taken, or null.
export async function claimNextTicket(label: string): Promise<string | null> {
  const r = await call<{ key: string | null }>("POST", "/queues/claim", { label, claimant: "agent-pipeline" });
  return r.key;
}

export async function nextRunId(): Promise<string> {
  const r = await call<{ value: number }>("POST", "/counters/agent-pipeline-run/next");
  return String(r.value);
}

--- src/types.ts ---
export type AgentName = "orchestrator" | "researcher" | "summarizer" | "coder" | "reviewer";

// What one call through llm-gw cost. A call can be several model turns when the
// agent uses tools; tokens are all of them, as llm-gw bills them.
export type Usage = {
  model: string;
  tokens: number;
  toolCalls: number;
  ms: number;
};

export type AgentMessage = {
  id: string; // m1, m2, ... in the order they were sent
  from: AgentName;
  to: AgentName;
  content: string;
  timestamp: string; // ISO 8601, UTC
  inReplyTo?: string; // the message this one answers
  usage?: Usage; // the call that produced this message
};

export type PipelineConfig = {
  models: Record<"researcher" | "summarizer" | "coder" | "reviewer", string>;
  handoff: { maxWords: number };
  review: { maxRevisionRounds: number };
};

export type RunStatus = "approved" | "escalated";

export type RunRecord = {
  runId: string;
  ticket: string;
  status: RunStatus;
  startedAt: string;
  finishedAt: string;
  config: PipelineConfig;
  totals: { tokens: number; toolCalls: number };
  messages: AgentMessage[];
};

--- src/worker.ts ---
// The agent-pipeline service. Polls the tracker for agent-ok tickets and runs up
// to WORKER_CONCURRENCY of them at once, all in this one Node process.
import { gatewayClient } from "./llm.ts";
import { loadConfig, runTicket } from "./run.ts";
import { saveRecord } from "./runs.ts";
import { claimNextTicket, commentOnTicket, fetchTicket, nextRunId } from "./tracker.ts";

const CONCURRENCY = Number(process.env.WORKER_CONCURRENCY ?? 4);
const POLL_MS = 30_000;

const llm = gatewayClient();
const config = loadConfig();
let running = 0;

async function poll() {
  while (running < CONCURRENCY) {
    const key = await claimNextTicket("agent-ok");
    if (!key) return;
    const runId = await nextRunId();
    running += 1;
    void runTicket(key, runId, {
      llm,
      config,
      fetchTicket,
      save: (record) => void saveRecord(record),
      comment: commentOnTicket,
    }).finally(() => {
      running -= 1;
    });
  }
}

console.log(`agent-pipeline worker: concurrency ${CONCURRENCY}, polling every ${POLL_MS / 1000}s`);
setInterval(() => {
  poll().catch((err) => console.error("poll failed:", err));
}, POLL_MS);
await poll();

