/// Sum of the `n` largest values in `items`, as an `i64`, so it never overflows.
/// Equal values count separately. If `n` is larger than `items.len()`, every
/// item is summed; `n = 0` gives 0. The caller's slice is not changed.
pub fn top_sum(items: &[i32], n: usize) -> i64 {
    let mut sorted = items.to_vec();
    sorted.sort_unstable_by(|a, b| b.cmp(a));
    sorted.iter().take(n).map(|&x| x as i64).sum()
}

/// Panics if `f` breaks any promise in `top_sum`'s doc comment;
/// returns normally for a correct implementation.
pub fn check_top_sum(f: fn(&[i32], usize) -> i64) {
    // Empty input and zero-count edge cases.
    let empty: [i32; 0] = [];
    assert_eq!(f(&empty, 0), 0);
    assert_eq!(f(&empty, 10), 0);

    // Normal case with ordering, duplicates, and partial selection.
    let items = [5, 1, 5, 3, 2];
    let original = items;
    assert_eq!(f(&items, 0), 0);
    assert_eq!(f(&items, 1), 5);
    assert_eq!(f(&items, 2), 10);
    assert_eq!(f(&items, 3), 13);
    assert_eq!(f(&items, 99), 16);
    assert_eq!(items, original);

    // Negative values and sum-as-i64 behavior.
    let mixed = [i32::MAX, -1, i32::MAX, 0];
    let mixed_original = mixed;
    assert_eq!(f(&mixed, 1), i32::MAX as i64);
    assert_eq!(f(&mixed, 2), (i32::MAX as i64) * 2);
    assert_eq!(f(&mixed, 3), (i32::MAX as i64) * 2 - 1);
    assert_eq!(f(&mixed, 10), (i32::MAX as i64) * 2 - 1);
    assert_eq!(mixed, mixed_original);
}

