use std::borrow::Cow;

fn clean(s: &str) -> Cow<'_, str> {
    let trimmed = s.trim_matches(' ');
    let mut needs_change = trimmed.len() != s.len();

    let mut out = String::new();
    let mut prev_space = false;

    for ch in trimmed.chars() {
        if ch == ' ' {
            if prev_space {
                needs_change = true;
                continue;
            }
            prev_space = true;
            out.push(' ');
        } else {
            let lc = ch.to_ascii_lowercase();
            if lc != ch {
                needs_change = true;
            }
            prev_space = false;
            out.push(lc);
        }
    }

    if !needs_change {
        Cow::Borrowed(s)
    } else {
        Cow::Owned(out)
    }
}

