mod ledger {
    pub struct Account {
        cents: u64,
        ops: u32,
    }

    impl Account {
        pub fn open() -> Account {
            Account { cents: 0, ops: 0 }
        }

        pub fn deposit(&mut self, cents: u64) {
            self.cents += cents;
            self.ops += 1;
        }

        pub fn withdraw(&mut self, cents: u64) -> bool {
            let fee = super::ledger::fees::withdrawal_fee(cents);
            let total = cents + fee;
            if total > self.cents {
                false
            } else {
                self.cents -= total;
                self.ops += 1;
                true
            }
        }

