pub fn shorten(s: &str, max_chars: usize) -> String {
    if s.chars().count() <= max_chars {
        return s.to_string();
    }
    let mut out = String::new();
    for c in s.chars() {
        if out.chars().count() == max_chars - 1 {
            break;
        }
        out.push(c);
    }
    out.push('…');
    out
}

