/// If `s` has at most `max_chars` chars, return it unchanged.
/// Otherwise return its first `max_chars - 1` chars followed by '…'
/// (one char), so the result has exactly `max_chars` chars.
/// `max_chars` is always at least 1. Must never panic.
/// shorten("naïve idea", 4) == "naï…"
pub fn shorten(s: &str, max_chars: usize) -> String {
    let count = s.chars().count();
    if count <= max_chars {
        s.to_string()
    } else {
        let mut out = String::new();
        out.extend(s.chars().take(max_chars - 1));
        out.push('…');
        out
    }
}

fn main() {
    println!("{}", shorten("naïve idea", 4));
    println!("{}", shorten("short", 10));
    println!("{}", shorten("日本語のテキスト", 3));
}
