/// (smallest, largest), or None for an empty slice.
/// min_max(&[4, 9, 1]) == Some((1, 9))
pub fn min_max<T: PartialOrd + Copy>(items: &[T]) -> Option<(T, T)> {
    if items.is_empty() {
        return None;
    }
    let mut min = items[0];
    let mut max = items[0];
    for &x in &items[1..] {
        if x < min {
            min = x;
        }
        if x > max {
            max = x;
        }
    }
    Some((min, max))
}

