import { Field } from './Field';
import { useForm } from './FormProvider';
import { isVisible } from './visibility';
import type { FieldValue, FormValues, SectionSchema } from './types';

interface FormRendererProps {
  onSubmit: (values: FormValues) => void;
}

export function FormRenderer({ onSubmit }: FormRendererProps) {
  const { schema, values, setValue } = useForm();

  return (
    <form
      className="dynamic-form"
      onSubmit={(e) => {
        e.preventDefault();
        onSubmit(values);
      }}
    >
      <h1>{schema.title}</h1>
      {schema.sections.map((section) => (
        <Section
          key={section.id}
          section={section}
          values={values}
          onChange={(name, value) => setValue(name, value)}
        />
      ))}
      <button type="submit">Submit</button>
    </form>
  );
}

interface SectionProps {
  section: SectionSchema;
  values: FormValues;
  onChange: (name: string, value: FieldValue) => void;
}

function Section({ section, values, onChange }: SectionProps) {
  const fields = section.fields.filter((field) => isVisible(field, values));

  return (
    <fieldset className="form-section">
      <legend>{section.title}</legend>
      <div className="form-grid">
        {fields.map((field, index) => (
          <Field
            key={index}
            field={field}
            value={values[field.name]}
            onChange={onChange}
            style={{ gridColumn: field.width === 'half' ? 'span 1' : 'span 2' }}
          >
            {field.help && <p className="field-help">{field.help}</p>}
          </Field>
        ))}
      </div>
    </fieldset>
  );
}

