// Reference solution for exercise 1 (never shown to the learner).
// Run runs the tests: rustc --edition 2024 --test -o main ex1_give_back.rs && ./main
//
// exclaim: take a String, add "!" to its end, and hand the same String back.
//   `text.push('!')` changes a String, so the binding must be mutable. A
//   parameter can be declared mutable too: `fn exclaim(mut text: String)`.
// longer: take two Strings and return the longer one (the first one on a tie).
//   The other one is dropped when the function returns. Do not clone.
//
// Predict before you run: in `longer`, when is the shorter string freed?

fn exclaim(mut text: String) -> String {
    text.push('!');
    text
}

fn longer(a: String, b: String) -> String {
    // The String not returned is dropped (freed) when this function returns.
    if a.len() >= b.len() { a } else { b }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn exclaim_adds_one_mark() {
        assert_eq!(exclaim(String::from("hi")), "hi!");
        assert_eq!(exclaim(String::new()), "!");
    }

    #[test]
    fn longer_picks_the_longer() {
        assert_eq!(longer(String::from("ab"), String::from("abc")), "abc");
        assert_eq!(longer(String::from("abcd"), String::from("x")), "abcd");
    }

    #[test]
    fn longer_prefers_the_first_on_a_tie() {
        assert_eq!(longer(String::from("xy"), String::from("zw")), "xy");
    }

    #[test]
    fn longer_returns_the_same_buffer_not_a_copy() {
        let a = String::from("a long one");
        let address = a.as_ptr(); // where a's text lives on the heap
        let result = longer(a, String::from("short"));
        assert_eq!(result.as_ptr(), address, "moved back, so the text should not have been copied");
    }
}


[for entity 715 · exercise 2: backup]
// Reference solution for exercise 2 (never shown to the learner).
// Run runs the tests: rustc --edition 2024 --test -o main ex2_backup.rs && ./main
//
// backup: return (the original String itself, an independent copy of it).
//   The first element must be the SAME heap buffer you were given (moved, not
//   copied); the second must be a new buffer with the same text.
//   Try `(original, original.clone())` first and read the error. Why does the
//   order of the two operations matter?
// twice: return the point twice. Why is no clone() needed here?

fn backup(original: String) -> (String, String) {
    // Clone first, while `original` is still ours; then move the original out.
    let copy = original.clone();
    (original, copy)
}

fn twice(point: (i32, i32)) -> ((i32, i32), (i32, i32)) {
    // (i32, i32) is Copy: using `point` twice copies it twice.
    (point, point)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn backup_has_the_same_text() {
        let (a, b) = backup(String::from("data"));
        assert_eq!(a, "data");
        assert_eq!(b, "data");
    }

    #[test]
    fn first_is_the_original_buffer_second_is_new() {
        let s = String::from("data");
        let address = s.as_ptr();
        let (a, b) = backup(s);
        assert_eq!(a.as_ptr(), address, "the first element should be the original, moved back");
        assert_ne!(b.as_ptr(), address, "the second element should be a deep copy");
    }

    #[test]
    fn twice_copies_a_copy_type() {
        assert_eq!(twice((1, 2)), ((1, 2), (1, 2)));
    }
}


