import { useState } from "react";
import type { CheckboxField, FieldConfig, FormConfig, MultiSelectField, NumberField } from "../api/formConfig";

type ValueOf<F extends FieldConfig> = F extends NumberField
  ? number
  : F extends CheckboxField
    ? boolean
    : F extends MultiSelectField
      ? string[]
      : F extends { readonly kind: "select"; readonly options: readonly { readonly value: infer V }[] }
        ? V
        : string;

/** Typed values for any form: pass its config and every field gets its own type. */
export type FormValuesOf<C extends FormConfig> = {
  -readonly [F in C["fields"][number] as F["name"]]: ValueOf<F>;
};

export function useFormValues<C extends FormConfig>(config: C) {
  const [values, setValues] = useState<FormValuesOf<C>>(() => initialValues(config));

  function setField<K extends keyof FormValuesOf<C>>(name: K, value: FormValuesOf<C>[K]) {
    setValues((prev) => ({ ...prev, [name]: value }));
  }

  return { values, setField };
}

function initialValues<C extends FormConfig>(config: C): FormValuesOf<C> {
  const entries = config.fields.map((f) => [f.name, "defaultValue" in f ? f.defaultValue : undefined]);
  return Object.fromEntries(entries) as FormValuesOf<C>;
}

