fn parse_setting(line: &str) -> Result<(String, u32), String> {
    let (key, value) = line
        .split_once('=')
        .ok_or_else(|| format!("missing '=' in line: {line}"))?;
    let number = value
        .trim()
        .parse::<u32>()
        .map_err(|_| format!("bad number in line: {line}"))?;
    Ok((key.trim().to_string(), number))
}

fn main() {
    let lines = ["width = 40", "height = 12", "depth: 3", "count = -1"];
    let mut total = 0;

    for line in lines {
        match parse_setting(line) {
            Ok((key, n)) => {
                println!("{key} -> {n}");
                total += n;
            }
            Err(err) => {
                eprintln!("skip bad line: {err}");
            }
        }
    }

    println!("total {total}");
}

