--- src/uplink.c ---
/* uplink.c - queue of event messages, sent as UDP datagrams */
#include <arpa/inet.h>
#include <netinet/in.h>
#include <pthread.h>
#include <stdio.h>
#include <string.h>
#include <sys/socket.h>
#include <time.h>
#include <unistd.h>

#include "config.h"
#include "msgpool.h"
#include "stats.h"
#include "telemetryd.h"

static pthread_mutex_t q_lock = PTHREAD_MUTEX_INITIALIZER;
static pthread_cond_t q_cond = PTHREAD_COND_INITIALIZER;
static struct msg *q_head, *q_tail;

void uplink_post(struct msg *m)
{
	m->next = NULL;
	pthread_mutex_lock(&q_lock);
	if (q_tail != NULL)
		q_tail->next = m;
	else
		q_head = m;
	q_tail = m;
	pthread_cond_signal(&q_cond);
	pthread_mutex_unlock(&q_lock);
}

static struct msg *uplink_take(void)
{
	struct timespec until;
	struct msg *m;

	clock_gettime(CLOCK_REALTIME, &until);
	until.tv_sec += 1;		/* wake up now and then to see g_stop */

	pthread_mutex_lock(&q_lock);
	while (q_head == NULL && !g_stop)
		if (pthread_cond_timedwait(&q_cond, &q_lock, &until) != 0)
			break;
	m = q_head;
	if (m != NULL) {
		q_head = m->next;
		if (q_head == NULL)
			q_tail = NULL;
	}
	pthread_mutex_unlock(&q_lock);
	return m;
}

void *uplink_thread(void *arg)
{
	const struct tlm_config *cfg = config_get();
	struct sockaddr_in to = { .sin_family = AF_INET };
	int s;

	(void)arg;
	to.sin_port = htons(cfg->uplink_port);
	inet_pton(AF_INET, cfg->uplink_host, &to.sin_addr);
	s = socket(AF_INET, SOCK_DGRAM, 0);
	if (s < 0) {
		perror("telemetryd: socket");
		return NULL;
	}

	while (!g_stop) {
		struct msg *m = uplink_take();

		if (m == NULL)
			continue;
		if (sendto(s, m->data, m->len, 0, (struct sockaddr *)&to, sizeof(to)) >= 0)
			stats_inc(&g_stats.events_sent);
		msgpool_put(m);
	}
	close(s);
	return NULL;
}

--- src/writer.c ---
/* writer.c - drains both rings into the telemetry file, 64 records a write */
#include <errno.h>
#include <fcntl.h>
#include <stdio.h>
#include <string.h>
#include <time.h>
#include <unistd.h>

#include "config.h"
#include "stats.h"
#include "telemetryd.h"

void writer_flush(struct writer *w)
{
	size_t off = 0;

	while (off < w->len) {
		ssize_t n = write(w->fd, w->buf + off, w->len - off);

		if (n < 0) {
			if (errno == EINTR)
				continue;
			fprintf(stderr, "telemetryd: write: %s\n", strerror(errno));
			break;
		}
		off += (size_t)n;
	}
	stats_add(&g_stats.bytes_written, off);
	w->len = 0;
}

/* Moves what is in the rings into the batch buffer; returns records moved. */
size_t writer_drain(struct writer *w)
{
	size_t moved = 0;

	for (unsigned ch = 0; ch < TLM_CHANNELS; ch++) {
		const struct tlm_rec *rec;

		while ((rec = ring_peek(w->ring[ch])) != NULL) {
			if (tlm_rec_crc(rec) != rec->crc)
				stats_inc(&g_stats.crc_errors);	/* written anyway */
			memcpy(w->buf + w->len, rec, sizeof(*rec));
			ring_pop(w->ring[ch]);
			stats_inc(&g_stats.written);
			w->len += sizeof(*rec);
			moved++;
			if (w->len == sizeof(w->buf))
				writer_flush(w);
		}
	}
	return moved;
}

void *writer_thread(void *arg)
{
	struct writer *w = arg;
	const struct tlm_config *cfg = config_get();
	const struct timespec idle = { .tv_sec = 0, .tv_nsec = 1000000 };

	w->fd = open(cfg->out_path, O_WRONLY | O_CREAT | O_APPEND, 0644);
	if (w->fd < 0) {
		fprintf(stderr, "telemetryd: %s: %s\n", cfg->out_path, strerror(errno));
		return NULL;
	}

	while (!g_stop) {
		if (writer_drain(w) == 0) {
			writer_flush(w);
			nanosleep(&idle, NULL);
		}
	}
	writer_drain(w);
	writer_flush(w);
	close(w->fd);
	return NULL;
}

--- tests/msgpool_stress.c ---
/*
 * msgpool_stress.c - three threads take and give back message buffers as
 * fast as they can (in the daemon: two capture threads and the status thread
 * take, the uplink thread gives back). A side table records which thread
 * holds each buffer, so a buffer handed out twice is caught at once.
 *
 *   msgpool_stress [-n takes per thread]
 */
#include <inttypes.h>
#include <pthread.h>
#include <stdatomic.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>

#include "msgpool.h"

#define THREADS		3
#define SHOW_MAX	5
#define HOLD_SPIN	50

static uint32_t s_takes = 2000000;
static _Atomic uint64_t s_double, s_empty;
static _Atomic unsigned s_shown;
static _Atomic uint8_t s_holder[MSG_POOL_SIZE];	/* 0: in the pool */
static uintptr_t s_base;			/* lowest buffer address */

static unsigned index_of(const struct msg *m)
{
	return (unsigned)(((uintptr_t)m - s_base) / sizeof(struct msg));
}

static void *taker(void *arg)
{
	uint8_t id = (uint8_t)(uintptr_t)arg;

	for (uint32_t i = 0; i < s_takes; i++) {
		struct msg *m = msgpool_get();
		uint8_t holder = 0;

		if (m == NULL) {
			atomic_fetch_add(&s_empty, 1);
			continue;
		}
		if (!atomic_compare_exchange_strong(&s_holder[index_of(m)], &holder, id)) {
			atomic_fetch_add(&s_double, 1);
			if (atomic_fetch_add(&s_shown, 1) < SHOW_MAX)
				printf("  thread %u, take %" PRIu32 ": got buffer %u, which thread %u holds\n",
				       id, i, index_of(m), holder);
			continue;	/* not ours: leave it with its holder */
		}
		memset(m->data, id, 16);
		for (volatile int spin = 0; spin < HOLD_SPIN; spin++)
			;
		atomic_store(&s_holder[index_of(m)], 0);
		msgpool_put(m);
	}
	return NULL;
}

int main(int argc, char **argv)
{
	pthread_t t[THREADS];
	unsigned free_count = 0;
	struct msg *m;
	int opt;

	setvbuf(stdout, NULL, _IOLBF, 0);
	while ((opt = getopt(argc, argv, "n:")) != -1)
		if (opt == 'n')
			s_takes = (uint32_t)strtoul(optarg, NULL, 10);

	printf("msgpool_stress: %d threads x %" PRIu32 " takes, pool of %d\n",
	       THREADS, s_takes, MSG_POOL_SIZE);
	msgpool_init();
	s_base = UINTPTR_MAX;
	{
		struct msg *all[MSG_POOL_SIZE];

		for (unsigned i = 0; i < MSG_POOL_SIZE; i++) {
			all[i] = msgpool_get();
			if ((uintptr_t)all[i] < s_base)
				s_base = (uintptr_t)all[i];
		}
		for (unsigned i = MSG_POOL_SIZE; i-- > 0; )
			msgpool_put(all[i]);
	}
	for (unsigned i = 0; i < THREADS; i++)
		pthread_create(&t[i], NULL, taker, (void *)(uintptr_t)(i + 1));
	for (unsigned i = 0; i < THREADS; i++)
		pthread_join(t[i], NULL);

	/* Every buffer is back now: the free list must hold each one once. */
	while ((m = msgpool_get()) != NULL && free_count <= 4 * MSG_POOL_SIZE) {
		memset(m->data, 0, sizeof(m->data));
		free_count++;
	}
	if (free_count > 4 * MSG_POOL_SIZE)
		printf("msgpool_stress: free list does not end (more than %d gets)\n", 4 * MSG_POOL_SIZE);
	else
		printf("msgpool_stress: free list holds %u of %d buffers\n", free_count, MSG_POOL_SIZE);
	printf("msgpool_stress: %" PRIu64 " takes of a held buffer, %" PRIu64 " empty pool: %s\n",
	       (uint64_t)s_double, (uint64_t)s_empty,
	       s_double || free_count != MSG_POOL_SIZE ? "FAIL" : "PASS");
	return s_double || free_count != MSG_POOL_SIZE;
}

--- tests/ring_stress.c ---
/*
 * ring_stress.c - push records through one ring as fast as both sides can go
 * and check every record that comes out: right sequence number, good CRC.
 *
 *   ring_stress [-n records]
 *
 * Samples are built from the sequence number (seq * 20 + i), so a bad record
 * shows where its samples came from.
 */
#include <inttypes.h>
#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>

#include "ring.h"

#define SHOW_MAX 4		/* of each kind */

static struct ring s_ring;
static uint32_t s_total = 20000000;

static int16_t sample_of(uint32_t seq, unsigned i)
{
	return (int16_t)((seq * TLM_REC_SAMPLES + i) & 0x7fff);
}

static void make_rec(struct tlm_rec *rec, uint32_t seq)
{
	rec->seq = seq;
	rec->channel = 0;
	rec->nsamples = TLM_REC_SAMPLES;
	rec->t_ns = (uint64_t)seq * 50000;
	for (unsigned i = 0; i < TLM_REC_SAMPLES; i++)
		rec->samples[i] = sample_of(seq, i);
	rec->flags = 0;
	rec->crc = tlm_rec_crc(rec);
}

static void *producer(void *arg)
{
	(void)arg;
	for (uint32_t seq = 0; seq < s_total; ) {
		struct tlm_rec *rec = ring_reserve(&s_ring);

		if (rec == NULL)
			continue;
		make_rec(rec, seq++);
		ring_commit(&s_ring);
	}
	return NULL;
}

/* How many samples of rec were written for this seq, and for one lap before. */
static void sample_origin(const struct tlm_rec *rec, uint32_t seq, int *now, int *lap)
{
	*now = *lap = 0;
	for (unsigned i = 0; i < TLM_REC_SAMPLES; i++) {
		if (rec->samples[i] == sample_of(seq, i))
			(*now)++;
		else if (rec->samples[i] == sample_of(seq - RING_SLOTS, i))
			(*lap)++;
	}
}

static uint64_t s_bad_crc, s_bad_seq;
static unsigned s_shown_seq, s_shown_crc;

static void *consumer(void *arg)
{
	(void)arg;
	for (uint32_t want = 0; want < s_total; ) {
		const struct tlm_rec *rec = ring_peek(&s_ring);
		int now, lap;

		if (rec == NULL)
			continue;
		if (rec->seq != want) {
			s_bad_seq++;
			if (s_shown_seq++ < SHOW_MAX)
				printf("  #%" PRIu32 ": seq %" PRIu32 " (%+" PRId32 "), crc %s\n",
				       want, rec->seq, (int32_t)(rec->seq - want),
				       tlm_rec_crc(rec) == rec->crc ? "ok" : "bad");
		} else if (tlm_rec_crc(rec) != rec->crc) {
			s_bad_crc++;
			sample_origin(rec, want, &now, &lap);
			if (s_shown_crc++ < SHOW_MAX)
				printf("  #%" PRIu32 ": seq ok, crc bad: samples %d from #%" PRIu32
				       ", %d from #%" PRIu32 ", t_ns %" PRIu64 "\n",
				       want, now, want, lap, want - RING_SLOTS, rec->t_ns);
		}
		ring_pop(&s_ring);
		want++;
	}
	return NULL;
}

int main(int argc, char **argv)
{
	pthread_t p, c;
	struct timespec t0, t1;
	int opt;

	setvbuf(stdout, NULL, _IOLBF, 0);
	while ((opt = getopt(argc, argv, "n:")) != -1)
		if (opt == 'n')
			s_total = (uint32_t)strtoul(optarg, NULL, 10);

	printf("ring_stress: %" PRIu32 " records, ring of %u x %zu bytes, 1 producer, 1 consumer\n",
	       s_total, RING_SLOTS, sizeof(struct tlm_rec));
	ring_init(&s_ring);
	clock_gettime(CLOCK_MONOTONIC, &t0);
	pthread_create(&c, NULL, consumer, NULL);
	pthread_create(&p, NULL, producer, NULL);
	pthread_join(p, NULL);
	pthread_join(c, NULL);
	clock_gettime(CLOCK_MONOTONIC, &t1);

	printf("ring_stress: %" PRIu32 " read, %" PRIu64 " wrong seq, %" PRIu64 " bad crc in %.2f s: %s\n",
	       s_total, s_bad_seq, s_bad_crc,
	       (double)(t1.tv_sec - t0.tv_sec) + (t1.tv_nsec - t0.tv_nsec) / 1e9,
	       s_bad_seq + s_bad_crc ? "FAIL" : "PASS");
	return s_bad_seq + s_bad_crc ? 1 : 0;
}

