// Reference solution for exercise 3 (never shown to the learner).
// Run runs the tests: rustc --edition 2024 --test -o main ex3_sign.rs && ./main
//
// sign: append "\n-- " followed by `name` to `text`, unless `text` already ends
//   with exactly that signature (then leave it alone). `text.ends_with(..)`
//   checks the end; `push_str` appends. Why must `text` be &mut String here?
// initials: the first character of each space-separated word, upper-cased,
//   as a new String: "rapid eye movement" -> "REM". `c.to_ascii_uppercase()`
//   upper-cases one char; `String::new()` and `push(c)` build the result.

fn sign(text: &mut String, name: &str) {
    let signature = format!("\n-- {name}");
    if !text.ends_with(&signature) {
        text.push_str(&signature);
    }
}

fn initials(full: &str) -> String {
    let mut out = String::new();
    let mut at_word_start = true;
    for c in full.chars() {
        if c == ' ' {
            at_word_start = true;
        } else if at_word_start {
            out.push(c.to_ascii_uppercase());
            at_word_start = false;
        }
    }
    out
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn signs_once() {
        let mut note = String::from("see you");
        sign(&mut note, "me");
        assert_eq!(note, "see you\n-- me");
        sign(&mut note, "me");
        assert_eq!(note, "see you\n-- me", "signing twice should not add a second signature");
    }

    #[test]
    fn a_different_name_signs_again() {
        let mut note = String::from("ok\n-- me");
        sign(&mut note, "you");
        assert_eq!(note, "ok\n-- me\n-- you");
    }

    #[test]
    fn initials_of_words() {
        assert_eq!(initials("rapid eye movement"), "REM");
        assert_eq!(initials("  as  soon as possible "), "ASAP");
        assert_eq!(initials(""), "");
    }
}



