// reader_bus_test.cpp
// Unit tests for ReaderBus, with a fake clock and a fake RS485 port.

#include "reader_bus.h"

#include <gtest/gtest.h>

#include <optional>

#include "clock.h"

// The fake clock: tests set it, and task_delay() moves it forward.
static uint32_t g_now_ms = 0;
uint32_t now_ms() { return g_now_ms; }
void task_delay(uint32_t ms) { g_now_ms += ms; }

// A reader that answers `reply_after_ms` after it is polled, or never.
class FakePort : public Rs485Port {
public:
    explicit FakePort(std::optional<uint32_t> reply_after_ms) : reply_after_ms_(reply_after_ms) {}

    void send_poll(uint8_t) override { polled_at_ = g_now_ms; }
    bool reply_ready() override {
        return reply_after_ms_ && g_now_ms - polled_at_ >= *reply_after_ms_;
    }
    ReaderReply read_reply() override { return {}; }

private:
    std::optional<uint32_t> reply_after_ms_;
    uint32_t polled_at_ = 0;
};

class ReaderBusTest : public ::testing::Test {
protected:
    os::Mutex bus_mutex_;
    static void ignore_card(uint8_t, uint32_t) {}
};

TEST_F(ReaderBusTest, ReplyArrivesInTime) {
    g_now_ms = 0;
    FakePort port(20);
    ReaderBus bus(port, bus_mutex_, ignore_card);

    port.send_poll(1);
    EXPECT_TRUE(bus.wait_for_reply(50));
}

TEST_F(ReaderBusTest, NoReplyTimesOutAfter50ms) {
    g_now_ms = 0;
    FakePort port(std::nullopt);
    ReaderBus bus(port, bus_mutex_, ignore_card);

    port.send_poll(1);
    EXPECT_FALSE(bus.wait_for_reply(50));
    EXPECT_GE(g_now_ms, 50u);
}


