        Grid {
            cells: vec![0; width * height],
            width,
            height,
        }
    }

    pub fn get(&self, x: usize, y: usize) -> u8 {
        if x >= self.width {
            panic!("x out of range: {x}");
        }
        if y >= self.height {
            panic!("y out of range: {y}");
