/// Panics if `f` breaks any promise in `top_sum`'s doc comment;
/// returns normally for a correct implementation.
pub fn check_top_sum(f: fn(&[i32], usize) -> i64) {
    // Empty input and zero-count edge cases.
    let empty: [i32; 0] = [];
    assert_eq!(f(&empty, 0), 0);
