// Reference solution for exercise 1 (never shown to the learner).
// Run runs the tests: rustc --edition 2024 --test -o main ex1_give_back.rs && ./main
//
// exclaim: take a String, add "!" to its end, and hand the same String back.
//   `text.push('!')` changes a String, so the binding must be mutable. A
//   parameter can be declared mutable too: `fn exclaim(mut text: String)`.
// longer: take two Strings and return the longer one (the first one on a tie).
//   The other one is dropped when the function returns. Do not clone.
//
// Predict before you run: in `longer`, when is the shorter string freed?

fn exclaim(mut text: String) -> String {
    text.push('!');
    text
}

fn longer(a: String, b: String) -> String {
    // The String not returned is dropped (freed) when this function returns.
    if a.len() >= b.len() { a } else { b }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn exclaim_adds_one_mark() {
        assert_eq!(exclaim(String::from("hi")), "hi!");
        assert_eq!(exclaim(String::new()), "!");
    }

    #[test]
    fn longer_picks_the_longer() {
        assert_eq!(longer(String::from("ab"), String::from("abc")), "abc");
        assert_eq!(longer(String::from("abcd"), String::from("x")), "abcd");
    }

    #[test]
    fn longer_prefers_the_first_on_a_tie() {
        assert_eq!(longer(String::from("xy"), String::from("zw")), "xy");
    }

    #[test]
    fn longer_returns_the_same_buffer_not_a_copy() {
        let a = String::from("a long one");
        let address = a.as_ptr(); // where a's text lives on the heap
        let result = longer(a, String::from("short"));
        assert_eq!(result.as_ptr(), address, "moved back, so the text should not have been copied");
    }
}


