use std::fmt::Display;

struct Span<T> {
    lo: T,
    hi: T,
}

impl<T> Span<T> {
    fn new(lo: T, hi: T) -> Span<T> {
        Span { lo, hi }
    }
}

impl<T: PartialOrd> Span<T> {
    fn contains(&self, x: &T) -> bool {
        &self.lo <= x && x <= &self.hi
    }
}

impl<T: Display> Span<T> {
    fn label(&self) -> String {
        format!("{}..{}", self.lo, self.hi)
    }
}

impl Span<f64> {
    fn width(&self) -> f64 {
        self.hi - self.lo
    }
}

impl Span<i32> {
    fn width(&self) -> i32 {
        self.hi - self.lo
    }
}

fn main() {
    let a = Span::new(1, 5);
    let b = Span::new(vec![1], vec![3]);
    let c = Span::new(0.5, 2.0);
    println!("{}", a.contains(&3)); // 1
    println!("{}", a.label()); // 2
    println!("{}", b.contains(&vec![2, 9])); // 3
    println!("{}", b.label()); // 4
    println!("{}", a.width()); // 5
    println!("{}", c.width()); // 6
}
