# Support agent: runtime and eval config
# repo support/cx-agents, support_agent/config/agent.yaml @ 7f3c2a1 (tag r46, 18 Sep 2026)

agent:
  name: support-agent
  runtime: cx-loop 2.3            # in-house agent loop: model -> tools -> model
  model: model-v2                 # the model provider
  temperature: 0.7
  max_output_tokens: 700
  max_tool_rounds: 12

tools:
  manifest: tools/tools.prod.json # r46: 46 tools from 9 MCP servers, via tool-gateway
  send: all                       # every tool definition on every model call
  on_error: return_to_model       # the tool's error JSON goes back to the model as the result

context:
  max_input_tokens: 16000         # cost and latency guard, set Mar 2025 (prototype, 6 tools)
  system_prompt:
    file: prompts/system_v4.md    # 410 tokens: persona and tone; never trimmed
  policy:
    file: prompts/support_rules_v7.md   # 2,310 tokens: refunds, goodwill, returns, escalation
    inject_as: first_user_message       # moved out of the system prompt in r31 (PR #1840)
  trim:
    strategy: oldest_first        # drop whole messages from the start until under max_input_tokens
    keep_last: 4

limits:                           # enforced by payments-mcp, not by the agent
  refund_max_pence: 10000
  applies_to: [issue_refund]

eval:
  suite: evals/support-eval-v3.jsonl    # 200 tasks, frozen 28 Apr 2026
  sandbox:
    base: synthetic dataset, 5,000 customers and 21,400 orders
    fixtures: per task; dates relative to the run date
  runs_per_task: 1
  temperature: 0.7                # same as production
  grader:
    pass_if: all(outcome_checks) and expected_tools_called
    outcome_checks: sandbox state diffs (orders, payments, returns, crm) and an LLM judge on the final reply
    expected_tools: from the reference trajectories, written in Apr 2026 against r24
    failure_classifier: LLM judge; labels the first failed check
                      # wrong_tool | wrong_arguments | policy_not_followed | no_tool_call | other


