use std::mem;

struct Batch {
    steps: Vec<String>,
}

impl Batch {
    fn add(&mut self, step: &str) {
        self.steps.push(step.to_string());
    }

    fn commit(mut self) -> Vec<String> {
        let steps = mem::take(&mut self.steps);
        println!("commit {} steps", steps.len());
        steps
    }
}

impl Drop for Batch {
    fn drop(&mut self) {
        if !self.steps.is_empty() {
            println!("rollback {} steps", self.steps.len());
        }
    }
}

fn run(all_ok: bool) {
    let mut batch = Batch { steps: Vec::new() };
    batch.add("reserve");
    if !all_ok {
        return;
    }
    batch.add("confirm");
    let _steps = batch.commit();
}

fn main() {
    run(true);
    println!("--");
    run(false);
}

