/*
 * bus.c - I2C1 bus lock, shared by acq (AFE), the timer task (environment
 * sensor) and store (EEPROM).
 */
#include "FreeRTOS.h"
#include "semphr.h"

#include "app.h"
#include "trace.h"

static SemaphoreHandle_t s_bus;

void bus_init( void )
{
    s_bus = xSemaphoreCreateBinary();
    configASSERT( s_bus != NULL );
    ( void ) xSemaphoreGive( s_bus );          /* bus starts free */
}

void bus_lock( void )
{
    if( xSemaphoreTake( s_bus, 0 ) != pdPASS )
    {
        trace_bus( TR_BUS_WAIT );
        ( void ) xSemaphoreTake( s_bus, portMAX_DELAY );
    }
    trace_bus( TR_BUS_TAKE );
}

void bus_unlock( void )
{
    trace_bus( TR_BUS_GIVE );
    ( void ) xSemaphoreGive( s_bus );
}

