--- app/store.c ---
/*
 * store.c - writes each summary as a 128-byte record to the I2C EEPROM
 * (32 KB ring of 256 records, 64-byte pages).
 */
#include <string.h>

#include "FreeRTOS.h"
#include "queue.h"
#include "task.h"

#include "app.h"
#include "board.h"
#include "i2c.h"

#define EEPROM_SIZE         32768u
#define EEPROM_PAGE         64u
#define REC_SIZE            128u
#define STORE_QUEUE_LEN     4u

static QueueHandle_t s_store_q;
static uint16_t s_wr_addr;

static uint16_t crc16( const uint8_t * d, uint32_t n )
{
    uint16_t crc = 0xFFFFu;

    for( uint32_t i = 0; i < n; i++ )
    {
        crc ^= ( uint16_t ) d[ i ] << 8;
        for( int b = 0; b < 8; b++ )
        {
            crc = ( crc & 0x8000u ) ? ( uint16_t ) ( ( crc << 1 ) ^ 0x1021u ) : ( uint16_t ) ( crc << 1 );
        }
    }
    return crc;
}

static void record_write( uint16_t addr, const uint8_t * rec )
{
    uint8_t buf[ 2u + EEPROM_PAGE ];

    bus_lock();
    for( uint32_t off = 0; off < REC_SIZE; off += EEPROM_PAGE )
    {
        uint16_t a = ( uint16_t ) ( addr + off );

        buf[ 0 ] = ( uint8_t ) ( a >> 8 );
        buf[ 1 ] = ( uint8_t ) ( a & 0xFFu );
        memcpy( &buf[ 2 ], &rec[ off ], EEPROM_PAGE );
        ( void ) i2c_write( I2C_ADDR_EEPROM, buf, sizeof buf );

        /* Write cycle, 5 ms max: the EEPROM does not ACK its address until done. */
        while( i2c_probe( I2C_ADDR_EEPROM ) != I2C_OK )
        {
            vTaskDelay( 1 );
        }
    }
    bus_unlock();
}

static void store_task( void * arg )
{
    struct summary s;
    uint8_t rec[ REC_SIZE ];

    ( void ) arg;

    for( ; ; )
    {
        ( void ) xQueueReceive( s_store_q, &s, portMAX_DELAY );

        memset( rec, 0xFF, sizeof rec );
        memcpy( rec, &s, sizeof s );
        uint16_t crc = crc16( rec, REC_SIZE - 2u );
        rec[ REC_SIZE - 2u ] = ( uint8_t ) ( crc >> 8 );
        rec[ REC_SIZE - 1u ] = ( uint8_t ) ( crc & 0xFFu );

        record_write( s_wr_addr, rec );
        s_wr_addr = ( uint16_t ) ( ( s_wr_addr + REC_SIZE ) % EEPROM_SIZE );
    }
}

void store_start( UBaseType_t prio, uint16_t stack_words )
{
    s_store_q = xQueueCreate( STORE_QUEUE_LEN, sizeof( struct summary ) );
    configASSERT( s_store_q != NULL );

    BaseType_t ok = xTaskCreate( store_task, "store", stack_words, NULL, prio, NULL );
    configASSERT( ok == pdPASS );
    ( void ) ok;
}

void store_post( const struct summary * s )
{
    ( void ) xQueueSend( s_store_q, s, 0 );
}

--- app/sys_timers.c ---
/*
 * sys_timers.c - software timers (run by the FreeRTOS timer task) and the
 * lateness statistics behind the "timer-stats" command.
 */
#include <stdio.h>

#include "FreeRTOS.h"
#include "task.h"
#include "timers.h"

#include "app.h"
#include "board.h"

#define ENV_PERIOD_MS   1000u
#define WDG_PERIOD_MS   250u        /* watchdog timeout is 1000 ms */
#define LED_PERIOD_MS   1000u

struct tstat
{
    const char * name;
    TickType_t period;
    uint32_t runs;
    TickType_t due;
    TickType_t last;
    TickType_t late_max;            /* latest start after the due time */
    TickType_t gap_max;             /* longest time between two runs */
};

static struct tstat s_tstat[ SYS_TIMER_COUNT ] =
{
    [ SYS_TIMER_ENV ] = { .name = "env", .period = pdMS_TO_TICKS( ENV_PERIOD_MS ) },
    [ SYS_TIMER_WDG ] = { .name = "wdg", .period = pdMS_TO_TICKS( WDG_PERIOD_MS ) },
    [ SYS_TIMER_LED ] = { .name = "led", .period = pdMS_TO_TICKS( LED_PERIOD_MS ) },
};

/* Called at the start of each callback, in the timer task. */
void sys_timer_hit( enum sys_timer_id id )
{
    struct tstat * ts = &s_tstat[ id ];
    TickType_t now = xTaskGetTickCount();

    if( ts->runs == 0u )
    {
        ts->due = now;
    }
    else if( ( now - ts->last ) > ts->gap_max )
    {
        ts->gap_max = now - ts->last;
    }

    if( ( now - ts->due ) > ts->late_max )
    {
        ts->late_max = now - ts->due;
    }
    ts->due += ts->period;
    ts->last = now;
    ts->runs++;
}

static void wdg_timer_cb( TimerHandle_t t )
{
    ( void ) t;
    sys_timer_hit( SYS_TIMER_WDG );
    board_wdg_kick();
}

static void led_timer_cb( TimerHandle_t t )
{
    static bool on;

    ( void ) t;
    sys_timer_hit( SYS_TIMER_LED );
    on = !on;
    board_led( on );
}

void sys_timers_start( void )
{
    TimerHandle_t env = xTimerCreate( "env", pdMS_TO_TICKS( ENV_PERIOD_MS ), pdTRUE, NULL, env_timer_cb );
    TimerHandle_t wdg = xTimerCreate( "wdg", pdMS_TO_TICKS( WDG_PERIOD_MS ), pdTRUE, NULL, wdg_timer_cb );
    TimerHandle_t led = xTimerCreate( "led", pdMS_TO_TICKS( LED_PERIOD_MS ), pdTRUE, NULL, led_timer_cb );

    configASSERT( ( env != NULL ) && ( wdg != NULL ) && ( led != NULL ) );
    ( void ) xTimerStart( env, 0 );
    ( void ) xTimerStart( wdg, 0 );
    ( void ) xTimerStart( led, 0 );
    board_wdg_start();
}

void sys_timers_print( char * buf, size_t len )
{
    int n = snprintf( buf, len, "timer  period_ms  runs     late_max_ms  gap_max_ms\r\n" );

    for( int i = 0; ( i < SYS_TIMER_COUNT ) && ( n > 0 ) && ( ( size_t ) n < len ); i++ )
    {
        const struct tstat * ts = &s_tstat[ i ];
        n += snprintf( buf + n, len - ( size_t ) n, "%-5s  %9lu  %-7lu  %11lu  %10lu\r\n",
                       ts->name, ( unsigned long ) ts->period, ( unsigned long ) ts->runs,
                       ( unsigned long ) ts->late_max, ( unsigned long ) ts->gap_max );
    }
}

--- app/trace.c ---
/*
 * trace.c - fixed-size event ring. Timestamps come from the 1 MHz trace
 * timer (board_us), ticks from the FreeRTOS tick count. Task switches are
 * recorded by traceTASK_SWITCHED_IN (FreeRTOSConfig.h).
 */
#ifdef TRACE_ENABLE

#include <stdio.h>
#include <string.h>

#include "FreeRTOS.h"
#include "task.h"

#include "board.h"
#include "trace.h"

#define TRACE_EVENTS    1024u

enum tr_type { TR_RUN, TR_DMA, TR_BLK, TR_DONE, TR_BUS };

struct tr_ev
{
    uint32_t us;
    uint32_t tick;
    void * task;
    uint32_t n;
    float rms, pk;
    uint16_t ndtr;
    uint8_t type, half, waiting, bus;
};

static struct tr_ev s_ev[ TRACE_EVENTS ];
static uint32_t s_head, s_count, s_dump_pos;
static volatile bool s_stopped;

static struct tr_ev * tr_put( uint8_t type, uint32_t tick )
{
    static struct tr_ev s_dummy;
    struct tr_ev * e = &s_dummy;
    UBaseType_t saved = taskENTER_CRITICAL_FROM_ISR();

    if( !s_stopped )
    {
        e = &s_ev[ s_head ];
        s_head = ( s_head + 1u ) % TRACE_EVENTS;
        if( s_count < TRACE_EVENTS ) { s_count++; }
        memset( e, 0, sizeof *e );
        e->us = board_us();
        e->tick = tick;
        e->type = type;
    }
    taskEXIT_CRITICAL_FROM_ISR( saved );
    return e;
}

/* traceTASK_SWITCHED_IN, inside the kernel with interrupts masked. */
void trace_task_in( void * tcb )
{
    tr_put( TR_RUN, xTaskGetTickCountFromISR() )->task = tcb;
}

void trace_isr_dma( uint32_t half, UBaseType_t waiting )
{
    struct tr_ev * e = tr_put( TR_DMA, xTaskGetTickCountFromISR() );
    e->half = ( uint8_t ) half;
    e->waiting = ( uint8_t ) waiting;
}

void trace_blk_start( uint32_t blk, uint32_t half, uint32_t ndtr, UBaseType_t waiting )
{
    struct tr_ev * e = tr_put( TR_BLK, xTaskGetTickCount() );
    e->n = blk;
    e->half = ( uint8_t ) half;
    e->ndtr = ( uint16_t ) ndtr;
    e->waiting = ( uint8_t ) waiting;
}

void trace_blk_end( uint32_t blk, uint32_t half, uint32_t ndtr, float rms_mg, float peak_mg )
{
    struct tr_ev * e = tr_put( TR_DONE, xTaskGetTickCount() );
    e->n = blk;
    e->half = ( uint8_t ) half;
    e->ndtr = ( uint16_t ) ndtr;
    e->rms = rms_mg;
    e->pk = peak_mg;
}

void trace_bus( enum tr_bus what )
{
    struct tr_ev * e = tr_put( TR_BUS, xTaskGetTickCount() );
    e->bus = ( uint8_t ) what;
    e->task = xTaskGetCurrentTaskHandle();
}

void trace_stop( void )
{
    s_stopped = true;
}

/* One line per call; returns pdTRUE while more lines remain (FreeRTOS+CLI). */
BaseType_t trace_dump( char * buf, size_t len )
{
    static const char * const bus_word[] = { "wait", "take", "give" };
    uint32_t first = ( s_head + TRACE_EVENTS - s_count ) % TRACE_EVENTS;

    if( s_dump_pos == 0u )
    {
        trace_stop();
        snprintf( buf, len, "trace: %lu events, t_ms from the first event\r\n"
                            "     t_ms      tick  event\r\n", ( unsigned long ) s_count );
        s_dump_pos = 1u;
        return pdTRUE;
    }

    const struct tr_ev * e = &s_ev[ ( first + s_dump_pos - 1u ) % TRACE_EVENTS ];
    float t = ( float ) ( e->us - s_ev[ first ].us ) / 1000.0f;
    int n = snprintf( buf, len, "%9.3f  %8lu  ", ( double ) t, ( unsigned long ) e->tick );

    switch( e->type )
    {
        case TR_RUN:
            snprintf( buf + n, len - n, "run   %s\r\n", pcTaskGetName( ( TaskHandle_t ) e->task ) );
            break;
        case TR_DMA:
            snprintf( buf + n, len - n, "dma   half=%u waiting=%u\r\n", e->half, e->waiting );
            break;
        case TR_BLK:
            snprintf( buf + n, len - n, "blk   #%lu half=%u ndtr=%u waiting=%u\r\n",
                      ( unsigned long ) e->n, e->half, e->ndtr, e->waiting );
            break;
        case TR_DONE:
            snprintf( buf + n, len - n, "done  #%lu half=%u ndtr=%u rms=%.1f pk=%.1f\r\n",
                      ( unsigned long ) e->n, e->half, e->ndtr, ( double ) e->rms, ( double ) e->pk );
            break;
        default:
            snprintf( buf + n, len - n, "bus   %s %s\r\n", bus_word[ e->bus ],
                      pcTaskGetName( ( TaskHandle_t ) e->task ) );
            break;
    }

    if( ++s_dump_pos > s_count )
    {
        s_dump_pos = 0u;
        return pdFALSE;
    }
    return pdTRUE;
}

#endif /* TRACE_ENABLE */

