/*
 * board.h - sensor node board support: 80 MHz Cortex-M4F, 4 NVIC priority bits.
 *
 * mcu.h is the vendor device header (CMSIS core + IRQn_Type + registers);
 * mcu_ll.h are the vendor low-level peripheral drivers. Neither is in this repo.
 */
#ifndef BOARD_H
#define BOARD_H

#include <stdbool.h>
#include <stdint.h>
#include "mcu.h"

/* Interrupt lines used by the application (IRQn_Type values from mcu.h). */
#define ADC_DMA_IRQn        DMA2_CH0_IRQn       /* 56: ADC samples, circular DMA */
#define CONSOLE_UART_IRQn   UART1_IRQn          /* 37: CLI, 115200 8N1 */
#define RADIO_UART_IRQn     UART2_IRQn          /* 38: radio module, 115200 8N1 */

/* ADC: timer-triggered at ADC_SAMPLE_HZ, 12-bit, one channel (accelerometer). */
#define ADC_SAMPLE_HZ       8000u
#define ADC_MG_PER_COUNT    4.88f               /* +-10 g over 4096 counts at AFE gain 1 */

/* DMA interrupt flags returned by board_adc_dma_flags(). */
#define DMA_FLAG_HT         ( 1u << 0 )         /* first half of the buffer written */
#define DMA_FLAG_TC         ( 1u << 1 )         /* second half written, wrapped to 0 */
#define DMA_FLAG_TE         ( 1u << 2 )         /* transfer error */

/* Board-level I2C addresses (7-bit), all on I2C1 at 100 kHz. */
#define I2C_ADDR_AFE        0x2Cu               /* programmable-gain front end */
#define I2C_ADDR_ENV        0x44u               /* temperature / humidity sensor */
#define I2C_ADDR_EEPROM     0x50u               /* 32 KB EEPROM, 64-byte pages */

void     board_init( void );
void     board_irq_init( void );

void     board_adc_start( uint16_t * buf, uint32_t n_samples );
uint32_t board_adc_dma_flags( void );
void     board_adc_dma_clear( uint32_t flags );
uint32_t board_adc_dma_remaining( void );       /* DMA count register: samples left before wrap */

uint32_t board_us( void );                      /* 32-bit, 1 MHz, runs in sleep */
uint32_t board_runtime_counter( void );         /* 32-bit, 10 kHz, run-time stats */

void     board_wdg_start( void );               /* independent watchdog, 1.0 s */
void     board_wdg_kick( void );

void     board_console_putc( char c );          /* polled */
void     board_radio_putc( char c );            /* polled */
void     board_radio_wake( void );              /* pulse the module's WAKE pin */

void     board_led( bool on );

#endif /* BOARD_H */

