/*
 * i2c.c - polled I2C master. Each call busy-waits on the status flags; at
 * 100 kHz a byte takes about 90 us on the wire.
 */
#include "i2c.h"

#include "mcu_ll.h"

#define I2C_FLAG_TIMEOUT    20000u      /* status polls, about 2 ms at 80 MHz */

static int wait_flag( uint32_t flag )
{
    uint32_t n = I2C_FLAG_TIMEOUT;

    while( !ll_i2c_flag( I2C1, flag ) )
    {
        if( ll_i2c_flag( I2C1, LL_I2C_FLAG_NACK ) )
        {
            ll_i2c_clear_flag( I2C1, LL_I2C_FLAG_NACK );
            ll_i2c_stop( I2C1 );
            return I2C_ERR_NACK;
        }
        if( --n == 0u )
        {
            ll_i2c_stop( I2C1 );
            return I2C_ERR_TMO;
        }
    }
    return I2C_OK;
}

static int send_bytes( const uint8_t * data, size_t len )
{
    for( size_t i = 0; i < len; i++ )
    {
        int rc = wait_flag( LL_I2C_FLAG_TXE );
        if( rc != I2C_OK ) { return rc; }
        ll_i2c_write_byte( I2C1, data[ i ] );
    }
    return wait_flag( LL_I2C_FLAG_TC );
}

int i2c_write( uint8_t addr, const uint8_t * data, size_t len )
{
    ll_i2c_start( I2C1, addr, LL_I2C_WRITE, len );
    int rc = send_bytes( data, len );
    if( rc == I2C_OK ) { ll_i2c_stop( I2C1 ); }
    return rc;
}

static int recv_bytes( uint8_t * rd, size_t len )
{
    for( size_t i = 0; i < len; i++ )
    {
        int rc = wait_flag( LL_I2C_FLAG_RXNE );
        if( rc != I2C_OK ) { return rc; }
        rd[ i ] = ll_i2c_read_byte( I2C1 );
    }
    ll_i2c_stop( I2C1 );
    return I2C_OK;
}

int i2c_write_read( uint8_t addr, const uint8_t * wr, size_t wr_len,
                    uint8_t * rd, size_t rd_len )
{
    ll_i2c_start( I2C1, addr, LL_I2C_WRITE, wr_len );
    int rc = send_bytes( wr, wr_len );
    if( rc != I2C_OK ) { return rc; }

    ll_i2c_start( I2C1, addr, LL_I2C_READ, rd_len );     /* repeated start */
    return recv_bytes( rd, rd_len );
}

int i2c_read( uint8_t addr, uint8_t * rd, size_t rd_len )
{
    ll_i2c_start( I2C1, addr, LL_I2C_READ, rd_len );
    return recv_bytes( rd, rd_len );
}

int i2c_probe( uint8_t addr )
{
    ll_i2c_start( I2C1, addr, LL_I2C_WRITE, 0u );
    int rc = wait_flag( LL_I2C_FLAG_TC );
    if( rc == I2C_OK ) { ll_i2c_stop( I2C1 ); }
    return rc;
}

