/*
 * i2c.h - polled I2C master on I2C1 (100 kHz). Not thread safe: callers hold
 * the bus lock (app/bus.h) around every transaction.
 */
#ifndef I2C_H
#define I2C_H

#include <stddef.h>
#include <stdint.h>

#define I2C_OK          0
#define I2C_ERR_NACK   -1
#define I2C_ERR_TMO    -2

int i2c_write( uint8_t addr, const uint8_t * data, size_t len );
int i2c_write_read( uint8_t addr, const uint8_t * wr, size_t wr_len,
                    uint8_t * rd, size_t rd_len );
int i2c_read( uint8_t addr, uint8_t * rd, size_t rd_len );
int i2c_probe( uint8_t addr );          /* address only; I2C_OK if it ACKs */

#endif /* I2C_H */

