fn parse_range(text: &str) -> Option<(u32, u32)> {
    let (left, right) = match text.split_once('-') {
        Some(parts) => parts,
        None => return None,
    };

    let start = match left.trim().parse::<u32>() {
        Ok(n) => n,
        Err(_) => return None,
    };

    let end = match right.trim().parse::<u32>() {
        Ok(n) => n,
        Err(_) => return None,
    };

    if start > end {
        None
    } else {
        Some((start, end))
    }
}

fn total_covered(lines: &[&str]) -> u32 {
    let mut total = 0;
    for line in lines {
        if let Some((start, end)) = parse_range(line) {
            total += end - start + 1;
        }
    }
    total
}

fn main() {
    for line in ["3-7", " 10 - 10 ", "8-2", "x-4", "12"] {
        println!("{line:?} -> {:?}", parse_range(line));
    }
    println!("covered {}", total_covered(&["3-7", "8-2", "1-1", "junk"]));
}

