/// a / b, or None when b is 0.
fn safe_div(a: i32, b: i32) -> Option<i32> {
    if b == 0 {
        return None;
    }
    Some(a / b)
}

/// The sum when both are present, otherwise None.
/// Hint: match on the tuple (a, b).
fn add_both(a: Option<i32>, b: Option<i32>) -> Option<i32> {
    match (a, b) {
        (Some(x), Some(y)) => Some(x + y),
        _ => None,
    }
}

/// The item at index i, or "?" when i is out of range. Must never panic.
fn item_or_question(items: &[&str], i: usize) -> String {
    match items.get(i) {
        Some(item) => item.to_string(),
        None => String::from("?"),
    }
}

