import { useState } from "react";
import type { FieldConfig, FormConfig } from "./types";

type ValueFor<F extends FieldConfig> =
  F["kind"] extends "checkbox" ? boolean :
  F["kind"] extends "multiselect" ? string[] :
  F["kind"] extends "number" ? number :
