import { use, useState, type FormEvent } from "react";
import { assertNever, loadFormConfig, type FormConfig } from "../api/formConfig";
import { postJson } from "../api/http";
import { useFormValues } from "../forms/useFormValues";

export const workspaceRequestForm = {
  id: "workspace-request",
  version: 14,
  title: "Request a workspace",
  submitUrl: "/api/workspace-requests",
  submitLabel: "Send request",
  fields: [
    { name: "workspaceName", label: "Workspace name", kind: "text", required: true },
    { name: "seats", label: "Seats", kind: "number", required: true, min: 1, max: 250, defaultValue: 5 },
    {
      name: "region",
      label: "Data region",
      kind: "select",
      required: true,
      options: [
        { value: "eu-west", label: "EU (Ireland)" },
        { value: "us-east", label: "US (Virginia)" },
      ],
    },
    { name: "costCenter", label: "Cost center", kind: "text", helpText: "Leave blank to bill your own team." },
    { name: "startDate", label: "Start date", kind: "date", required: true },
    { name: "sso", label: "Require single sign-on", kind: "checkbox", defaultValue: true },
  ],
} as const satisfies FormConfig;

const configPromise = loadFormConfig("workspace-request") as Promise<typeof workspaceRequestForm>;

const ADMIN_SEATS = 1;

function seatPrice(region: "eu-west" | "us-east"): number {
  switch (region) {
    case "eu-west":
      return 14;
    case "us-east":
      return 12;
    default:
      return assertNever(region);
  }
}

export function WorkspaceRequestPage() {
  const config = use(configPromise);
  const { values, setField } = useFormValues(config);
  const [confirmation, setConfirmation] = useState<string | null>(null);

  async function handleSubmit(e: FormEvent<HTMLFormElement>) {
    e.preventDefault();
    const billedSeats = values.seats + ADMIN_SEATS;
    const monthly = billedSeats * seatPrice(values.region);
    await postJson(config.submitUrl, {
      ...values,
      costCenter: values.costCenter.trim() || undefined,
      billedSeats,
    });
    setConfirmation(`${billedSeats} seats, ${monthly} per month`);
  }

  return (
    <form onSubmit={handleSubmit}>
      <h2>{config.title}</h2>
      <input value={values.workspaceName ?? ""} onChange={(e) => setField("workspaceName", e.target.value)} />
      <input
        type="number"
        value={values.seats}
        onChange={(e) => setField("seats", e.target.valueAsNumber)}
      />
      <select value={values.region ?? ""} onChange={(e) => setField("region", e.target.value as "eu-west" | "us-east")}>
        {config.fields[2].options.map((o) => (
          <option key={o.value} value={o.value}>{o.label}</option>
        ))}
      </select>
      <input value={values.costCenter ?? ""} onChange={(e) => setField("costCenter", e.target.value)} />
      <input type="date" value={values.startDate ?? ""} onChange={(e) => setField("startDate", e.target.value)} />
      <input type="checkbox" checked={values.sso} onChange={(e) => setField("sso", e.target.checked)} />
      <button type="submit">{config.submitLabel}</button>
      {confirmation && <p role="status">{confirmation}</p>}
    </form>
  );
}


