// SPDX-License-Identifier: GPL-2.0
/*
 * sensread - a small user-space smoke test for /dev/sensfifo0.
 *
 * It writes three known samples into the device, reads them back, prints what
 * read() returned and the first sample, then reads the counters with
 * SENSFIFO_IOC_GET_STATS. Build on the target with:
 *
 *	cc -Wall -o sensread sensread.c
 */
#include <fcntl.h>
#include <stdint.h>
#include <stdio.h>
#include <string.h>
#include <sys/ioctl.h>
#include <unistd.h>

#include "sensfifo.h"

int main(void)
{
	int fd = open("/dev/sensfifo0", O_RDWR);
	if (fd < 0) {
		perror("open");
		return 1;
	}

	struct sens_sample in[3] = {
		{ .seq = 100, .value = -5, .flags = 0x1 },
		{ .seq = 101, .value =  7, .flags = 0x0 },
		{ .seq = 102, .value = 12, .flags = 0x2 },
	};
	ssize_t w = write(fd, in, sizeof(in));
	printf("write() returned %zd (sent %zu bytes)\n", w, sizeof(in));

	/* Read into a 4096-byte buffer, the way a typical reader or `cat` does. */
	char buf[4096];
	memset(buf, 0, sizeof(buf));
	ssize_t r = read(fd, buf, sizeof(buf));
	struct sens_sample out[3];
	memcpy(out, buf, sizeof(out));
	printf("read(fd, buf, 4096) returned %zd\n", r);
	printf("sample[0]: seq=%u value=%d flags=0x%x\n",
	       out[0].seq, out[0].value, out[0].flags);
	printf("expected : seq=%u value=%d flags=0x%x\n",
	       in[0].seq, in[0].value, in[0].flags);

	struct sensfifo_stats st;
	memset(&st, 0, sizeof(st));
	if (ioctl(fd, SENSFIFO_IOC_GET_STATS, &st) == 0)
		printf("stats: dropped=%u rate=%u overruns=%u\n",
		       st.dropped, st.rate_hz, st.overruns);
	else
		perror("ioctl GET_STATS");

	close(fd);
	return 0;
}

