use std::mem;

// A batch of steps. If it is not committed, dropping it must roll back.
struct Batch {
    steps: Vec<String>,
}

impl Batch {
    fn add(&mut self, step: &str) {
        self.steps.push(step.to_string());
    }

    fn commit(self) -> Vec<String> {
        let steps = self.steps;
        mem::forget(self);
        println!("commit {} steps", steps.len());
        steps
    }
}

impl Drop for Batch {
    fn drop(&mut self) {
        println!("rollback {} steps", self.steps.len());
    }
}

fn run(all_ok: bool) {
    let mut batch = Batch { steps: Vec::new() };
    batch.add("reserve");
    if !all_ok {
        return;
    }
    batch.add("confirm");
    let _steps = batch.commit();
}

fn main() {
    run(true);
    println!("--");
    run(false);
}

