        unsafe { (&mut *self.steps).push(step.to_string()); }
    }

    fn commit(self) -> Vec<String> {
        let steps = unsafe { ManuallyDrop::into_inner(std::ptr::read(&self.steps)) };
        println!("commit {} steps", steps.len());
        steps
    }
}

impl Drop for Batch {
    fn drop(&mut self) {
        let steps = unsafe { &*self.steps };
        println!("rollback {} steps", steps.len());
    }
}

fn run(all_ok: bool) {
    let mut batch = Batch { steps: ManuallyDrop::new(Vec::new()) };
    batch.add("reserve");
    if !all_ok {
        return;
    }
    batch.add("confirm");
    let steps = batch.commit();
    println!("returned {} steps", steps.len());
}

fn main() {
    run(true);
    println!("--");
    run(false);
}

