--- src/buf_pool.c ---
/* buf_pool.c: fixed pool of buffers, so nothing is malloc'd after start-up. */
#include <stdlib.h>

#include "buf_pool.h"
#include "log.h"

int pool_init(struct buf_pool *p)
{
	int err, i;

	p->bufs = calloc(GW_POOL_BUFS, sizeof(*p->bufs));
	if (p->bufs == NULL)
		return -1;
	for (i = 0; i < GW_POOL_BUFS; i++) {
		p->bufs[i].id = i;
		p->free_ring[i] = i;
	}
	p->head = p->tail = 0;
	p->nfree = p->min_free = GW_POOL_BUFS;
	p->waits = 0;
	err = pthread_mutex_init(&p->lock, NULL);
	if (err == 0)
		err = pthread_cond_init(&p->avail, NULL);
	return err;
}

struct gw_buf *pool_get(struct buf_pool *p)
{
	struct gw_buf *b;

	pthread_mutex_lock(&p->lock);
	if (p->nfree == 0) {
		p->waits++;
		thr_set_state("pool_get wait");
		pthread_cond_wait(&p->avail, &p->lock);
		thr_set_state("run");
	}
	b = &p->bufs[p->free_ring[p->head]];
	p->head = (p->head + 1) % GW_POOL_BUFS;
	p->nfree--;
	if (p->nfree < p->min_free)
		p->min_free = p->nfree;
	pthread_mutex_unlock(&p->lock);

	b->len = 0;
	return b;
}

void pool_put(struct buf_pool *p, struct gw_buf *b)
{
	pthread_mutex_lock(&p->lock);
	p->free_ring[p->tail] = b->id;
	p->tail = (p->tail + 1) % GW_POOL_BUFS;
	p->nfree++;
	pthread_cond_signal(&p->avail);
	pthread_mutex_unlock(&p->lock);
}

void pool_stats(struct buf_pool *p, struct pool_stats *st)
{
	pthread_mutex_lock(&p->lock);
	st->nfree = p->nfree;
	st->min_free = p->min_free;
	st->waits = p->waits;
	p->min_free = p->nfree;
	pthread_mutex_unlock(&p->lock);
}

--- src/buf_pool.h ---
/* buf_pool.h: fixed pool of GW_POOL_BUFS buffers, allocated once at start. */
#ifndef BUF_POOL_H
#define BUF_POOL_H

#include <pthread.h>

#include "gw.h"

struct buf_pool {
	pthread_mutex_t  lock;
	pthread_cond_t   avail;                    /* a buffer was returned */
	struct gw_buf   *bufs;                     /* GW_POOL_BUFS of them */
	int              free_ring[GW_POOL_BUFS];  /* ids of free buffers, FIFO */
	unsigned         head;                     /* next id to hand out */
	unsigned         tail;                     /* where the next returned id goes */
	int              nfree;
	/* stats, under lock */
	int              min_free;                 /* low-water mark since last stats */
	unsigned long    waits;
};

struct pool_stats {
	int           nfree;
	int           min_free;
	unsigned long waits;
};

int            pool_init(struct buf_pool *p);
/* Takes a free buffer, blocking until one is returned if none is free.
 * Used by the acquisition thread (one per frame) and by the workers
 * (one per upload, for the encoded body). */
struct gw_buf *pool_get(struct buf_pool *p);
void           pool_put(struct buf_pool *p, struct gw_buf *b);
/* Copies the counters and starts a new low-water mark. */
void           pool_stats(struct buf_pool *p, struct pool_stats *st);

#endif

--- src/config.h ---
/* config.h: build-time sizing for sensor-gw. */
#ifndef GW_CONFIG_H
#define GW_CONFIG_H

#define GW_VERSION            "1.4.0"

/* Sampling: the hub sends one frame of 100 samples (3 axes, int16) every 100 ms. */
#define GW_SAMPLES_PER_FRAME  100
#define GW_AXES               3

/* Threads */
#define GW_N_WORKERS          4

/* Frames waiting for a worker. Kept short on purpose: when the workers fall
 * behind, acquisition blocks and the hub's own FIFO (4 frames) absorbs it. */
#define GW_QUEUE_DEPTH        2

/* Buffers for raw frames and encoded uploads. Every worker can hold a raw
 * frame while one more encodes: N_WORKERS + QUEUE_DEPTH + 2 = 8. */
#define GW_POOL_BUFS          8
#define GW_BUF_SIZE           2048

/* The collector accepts at most 2 concurrent uploads per device (429 beyond). */
#define GW_UPLINK_SLOTS       2
#define GW_HTTP_TIMEOUT_S     10
#define GW_BACKOFF_MAX_S      60

/* Watchdog: dump thread and queue state if nothing was uploaded for this long. */
#define GW_STALL_S            30
#define GW_STATS_EVERY_S      10

/* Stop: how long main waits for each worker before it logs a state dump. */
#define GW_JOIN_WARN_S        5

#endif

