/* gw.h: types shared by the acquisition thread, the workers and main. */
#ifndef GW_H
#define GW_H

#include <stddef.h>
#include <stdint.h>

#include "config.h"

struct gw_buf {
	int      id;                 /* index in the pool, fixed */
	size_t   len;                /* bytes used in data[] */
	uint8_t  data[GW_BUF_SIZE];
};

/* A frame as the hub sends it (little-endian; both ends are little-endian). */
struct hub_frame_hdr {
	uint16_t magic;              /* HUB_MAGIC */
	uint16_t nsamples;
	uint32_t seq;                /* +1 per frame, never reset while the hub runs */
	uint32_t t0_ms;              /* hub clock at the first sample */
	uint16_t lost;               /* frames dropped by the hub since the previous one */
	uint16_t rsvd;
};

#define HUB_MAGIC       0x5AA5u
#define HUB_FRAME_SIZE  (sizeof(struct hub_frame_hdr) + \
                         GW_SAMPLES_PER_FRAME * GW_AXES * sizeof(int16_t))

struct ring_queue;
struct buf_pool;
struct uplink;

struct gw {
	struct ring_queue *q;
	struct buf_pool   *pool;
	struct uplink     *up;
};

#endif

--- src/http.c ---
/* http.c: minimal blocking HTTP/1.1 POST over TCP, one connection per request. */
#include <errno.h>
#include <netdb.h>
#include <poll.h>
#include <stdio.h>
#include <string.h>
#include <sys/socket.h>
#include <sys/time.h>
#include <unistd.h>

#include "http.h"

static int connect_to(const char *host, const char *port, int timeout_s)
{
	struct addrinfo hints = { .ai_family = AF_UNSPEC, .ai_socktype = SOCK_STREAM };
	struct addrinfo *res, *ai;
	struct timeval tv = { .tv_sec = timeout_s };
	int fd = -1;

	if (getaddrinfo(host, port, &hints, &res) != 0)
		return -1;
	for (ai = res; ai != NULL; ai = ai->ai_next) {
		fd = socket(ai->ai_family, ai->ai_socktype, ai->ai_protocol);
		if (fd < 0)
			continue;
		setsockopt(fd, SOL_SOCKET, SO_RCVTIMEO, &tv, sizeof(tv));
		setsockopt(fd, SOL_SOCKET, SO_SNDTIMEO, &tv, sizeof(tv));
		if (connect(fd, ai->ai_addr, ai->ai_addrlen) == 0)
			break;
		if (errno == EINTR) {
			/* the connection goes on in the background: wait for it */
			struct pollfd pfd = { .fd = fd, .events = POLLOUT };
			int soerr = 0;
			socklen_t sl = sizeof(soerr);

			while (poll(&pfd, 1, timeout_s * 1000) < 0 && errno == EINTR)
				;
			getsockopt(fd, SOL_SOCKET, SO_ERROR, &soerr, &sl);
			if ((pfd.revents & POLLOUT) && soerr == 0)
				break;
		}
		close(fd);
		fd = -1;
	}
	freeaddrinfo(res);
	return fd;
}

static int send_all(int fd, const void *buf, size_t len)
{
	const char *p = buf;

	while (len > 0) {
		ssize_t n = send(fd, p, len, MSG_NOSIGNAL);

		if (n < 0) {
			if (errno == EINTR)
				continue;
			return -1;
		}
		p += n;
		len -= (size_t)n;
	}
	return 0;
}

int http_post(const char *host, const char *port, const char *path,
	      const char *device, const uint8_t *body, size_t len, int timeout_s)
{
	char hdr[256], resp[128];
	size_t got = 0;
	int fd, n, status = -1;

	fd = connect_to(host, port, timeout_s);
	if (fd < 0)
		return -1;

	n = snprintf(hdr, sizeof(hdr),
		     "POST %s HTTP/1.1\r\n"
		     "Host: %s\r\n"
		     "X-Device-Id: %s\r\n"
		     "Content-Type: application/octet-stream\r\n"
		     "Content-Length: %zu\r\n"
		     "Connection: close\r\n\r\n", path, host, device, len);
	if (send_all(fd, hdr, (size_t)n) != 0 || send_all(fd, body, len) != 0)
		goto out;

	/* Only the status line matters: "HTTP/1.1 201 Created" */
	while (got < sizeof(resp) - 1 && memchr(resp, '\n', got) == NULL) {
		ssize_t r = recv(fd, resp + got, sizeof(resp) - 1 - got, 0);

		if (r < 0 && errno == EINTR)
			continue;
		if (r <= 0)
			break;
		got += (size_t)r;
	}
	resp[got] = '\0';
	if (sscanf(resp, "HTTP/1.%*d %d", &status) != 1)
		status = -1;
out:
	close(fd);
	return status;
}

