use std::borrow::Cow;

fn clean(s: &str) -> Cow<'_, str> {
    let trimmed = s.trim();
    let bytes = trimmed.as_bytes();

    let mut needs_change = trimmed != s;
    let mut has_prev_space = false;

    for &b in bytes {
        if b == b' ' {
            if has_prev_space {
                needs_change = true;
                break;
            }
            has_prev_space = true;
        } else {
            if b.is_ascii_uppercase() {
                needs_change = true;
                break;
            }
            has_prev_space = false;
        }
    }

    if !needs_change {
        return Cow::Borrowed(trimmed);
    }

    let mut out = String::with_capacity(trimmed.len());
    let mut prev_space = false;
    for ch in trimmed.chars() {
        if ch == ' ' {
            if !prev_space {
                out.push(' ');
                prev_space = true;
            }
        } else {
            prev_space = false;
            for lower in ch.to_ascii_lowercase().chars() {
                out.push(lower);
            }
        }
    }

    Cow::Owned(out)
}

fn clean_all<'a>(lines: &[&'a str]) -> Vec<Cow<'a, str>> {
    lines.iter().copied().map(clean).collect()
}

