// Reference solution for exercise 1 (never shown to the learner).
// Run runs the tests: rustc --edition 2024 --test -o main ex1_text.rs && ./main
//
// count_words: how many words are in `text`? Words are separated by one or
//   more spaces; leading and trailing spaces do not make words.
//   Hint: walk `text.chars()` and count the places where a word starts
//   (a non-space character that is first, or follows a space).
// first_line: the text up to (not including) the first '\n', or all of it.
//   Return a slice of `text`: no new String. `char_indices` or `bytes()`
//   gives you the offset to cut at.

fn count_words(text: &str) -> usize {
    let mut count = 0;
    let mut in_word = false;
    for c in text.chars() {
        if c == ' ' {
            in_word = false;
        } else if !in_word {
            in_word = true;
            count += 1;
        }
    }
    count
}

fn first_line(text: &str) -> &str {
    for (i, c) in text.char_indices() {
        if c == '\n' {
            return &text[..i];
        }
    }
    text
}

