// reader_bus.cpp
// Polls the key-fob readers on the RS485 bus. Runs on the door task.

#include "reader_bus.h"

#include <mutex>

#include "clock.h"
#include "log.h"

namespace {
constexpr uint8_t kReaderAddresses[] = {1, 2};   // front and side door readers
constexpr uint32_t kReplyTimeoutMs = 50;          // a reader answers within a few ms
constexpr uint32_t kPollCheckMs = 8;              // how often to look for the reply
}  // namespace

ReaderBus::ReaderBus(Rs485Port& port, os::Mutex& bus_mutex, CardHandler on_card)
    : port_(port), bus_mutex_(bus_mutex), on_card_(std::move(on_card)) {}

// Asks each reader whether a card was seen, and hands any card to the door logic.
void ReaderBus::poll_readers() {
    std::lock_guard<os::Mutex> lock(bus_mutex_);   // the network task shares the bus
    for (uint8_t address : kReaderAddresses) {
        const uint32_t start = now_ms();
        LOG("door: poll reader %u", address);
        port_.send_poll(address);
        if (!wait_for_reply(kReplyTimeoutMs)) {
            LOG("door: reader %u timeout after %u ms", address, now_ms() - start);
            continue;
        }
        LOG("door: reader %u ok (%u ms)", address, now_ms() - start);
        ReaderReply reply = port_.read_reply();
        if (reply.card_seen) {
            on_card_(address, reply.card_id);
        }
    }
}

// Waits for the polled reader's reply. Returns false if none came in time.
bool ReaderBus::wait_for_reply(uint32_t timeout_ms) {
    const uint32_t deadline = now_ms() + timeout_ms;
    while (now_ms() < deadline) {
        if (port_.reply_ready()) {
            return true;
        }
        task_delay(kPollCheckMs);
    }
    return false;
}


