use std::error::Error;
use std::fmt;
use std::num::ParseIntError;

// Given: the error for one line.
#[derive(Debug, PartialEq)]
enum LineError {
    NoEquals,
    BadNumber(ParseIntError),
}

impl fmt::Display for LineError {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        match self {
            LineError::NoEquals => write!(f, "no '='"),
            LineError::BadNumber(_) => write!(f, "bad number"),
        }
    }
}

impl Error for LineError {
    fn source(&self) -> Option<&(dyn Error + 'static)> {
        match self {
            LineError::BadNumber(e) => Some(e),
            LineError::NoEquals => None,
        }
    }
}

// The error for a whole file.
#[derive(Debug, PartialEq)]
enum ConfigError {
    Line { line_no: usize, source: LineError },
    Duplicate(String),
}

impl From<ParseIntError> for LineError {
    fn from(e: ParseIntError) -> Self {
        LineError::BadNumber(e)
    }
}

fn parse_line(line: &str) -> Result<(String, u32), LineError> {
    let (key, value) = line.split_once('=').ok_or(LineError::NoEquals)?;
    let n: u32 = value.trim().parse()?; // From<ParseIntError> for LineError
    Ok((key.trim().to_string(), n))
}

fn read_config(text: &str) -> Result<Vec<(String, u32)>, ConfigError> {
    let mut pairs: Vec<(String, u32)> = Vec::new();
    for (i, line) in text.lines().enumerate() {
        if line.trim().is_empty() {
            continue;
        }
        // From cannot know the line number, so map_err adds it here.
        let (key, n) = parse_line(line).map_err(|source| ConfigError::Line { line_no: i + 1, source })?;
        if pairs.iter().any(|(k, _)| *k == key) {
            return Err(ConfigError::Duplicate(key));
        }
        pairs.push((key, n));
    }
    Ok(pairs)
}

impl fmt::Display for ConfigError {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        match self {
            ConfigError::Line { line_no, .. } => write!(f, "line {line_no}"),
            ConfigError::Duplicate(key) => write!(f, "duplicate key {key}"),
        }
    }
}

impl Error for ConfigError {
    fn source(&self) -> Option<&(dyn Error + 'static)> {
        match self {
            ConfigError::Line { source, .. } => Some(source),
            ConfigError::Duplicate(_) => None,
        }
    }
}

fn report(e: &dyn Error) -> String {
    let mut text = e.to_string();
    let mut cause = e.source();
    while let Some(c) = cause {
        text.push_str(&format!(" <- {c}"));
        cause = c.source();
    }
    text
}

fn main() {
    for text in ["a = 1\nb = 2", "a = 1\n\nb = lots", "a = 1\nb\n", "a = 1\na = 2"] {
        match read_config(text) {
            Ok(pairs) => println!("ok {pairs:?}"),
            Err(e) => println!("error: {}", report(&e)),
        }
    }
}

