pub struct Grid {
    cells: Vec<u8>,
    width: usize,
    height: usize,
}

impl Grid {
    pub fn new(width: usize, height: usize) -> Grid {
        Grid {
            cells: vec![0; width * height],
            width,
            height,
        }
    }

    pub fn get(&self, x: usize, y: usize) -> u8 {
        if x >= self.width {
            panic!("x out of range: {x}");
        }
        if y >= self.height {
            panic!("y out of range: {y}");
        }
        self.cells[y * self.width + x]
    }
}

