/* config.c - "key = value" configuration, loaded on first use */
#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include "config.h"

static struct tlm_config *s_cfg;
static pthread_mutex_t s_cfg_lock = PTHREAD_MUTEX_INITIALIZER;

static void config_defaults(struct tlm_config *c)
{
	snprintf(c->adc_dev[0], sizeof(c->adc_dev[0]), "/dev/tlm_adc0");
	snprintf(c->adc_dev[1], sizeof(c->adc_dev[1]), "/dev/tlm_adc1");
	snprintf(c->out_path, sizeof(c->out_path), "/var/lib/telemetry/current.tlm");
	snprintf(c->uplink_host, sizeof(c->uplink_host), "192.168.10.1");
	c->uplink_port = 5140;
	c->status_period_ms = 1000;
	c->status_uplink_every = 10;
}

static void config_parse(struct tlm_config *c, FILE *f)
{
	char line[160], key[32], val[128];

	while (fgets(line, sizeof(line), f) != NULL) {
		if (line[0] == '#' || sscanf(line, " %31[a-z_0-9] = %127s", key, val) != 2)
			continue;
		if (strcmp(key, "adc_dev0") == 0)
			snprintf(c->adc_dev[0], sizeof(c->adc_dev[0]), "%s", val);
		else if (strcmp(key, "adc_dev1") == 0)
			snprintf(c->adc_dev[1], sizeof(c->adc_dev[1]), "%s", val);
		else if (strcmp(key, "out_path") == 0)
			snprintf(c->out_path, sizeof(c->out_path), "%s", val);
		else if (strcmp(key, "uplink_host") == 0)
			snprintf(c->uplink_host, sizeof(c->uplink_host), "%s", val);
		else if (strcmp(key, "uplink_port") == 0)
			c->uplink_port = (uint16_t)strtoul(val, NULL, 10);
		else if (strcmp(key, "status_period_ms") == 0)
			c->status_period_ms = (uint32_t)strtoul(val, NULL, 10);
		else if (strcmp(key, "status_uplink_every") == 0)
			c->status_uplink_every = (uint32_t)strtoul(val, NULL, 10);
	}
}

/*
 * Every thread calls this when it starts. The lock is only taken until the
 * config is loaded; after that the check outside it returns straight away.
 */
const struct tlm_config *config_get(void)
{
	if (s_cfg == NULL) {
		pthread_mutex_lock(&s_cfg_lock);
		if (s_cfg == NULL) {
			struct tlm_config *c = calloc(1, sizeof(*c));
			const char *path = getenv("TLM_CONFIG");
			FILE *f;

			if (c == NULL)
				abort();
			config_defaults(c);
			f = fopen(path != NULL ? path : TLM_CONFIG_PATH, "r");
			if (f != NULL) {
				config_parse(c, f);
				fclose(f);
			}
			s_cfg = c;
		}
		pthread_mutex_unlock(&s_cfg_lock);
	}
	return s_cfg;
}

