/*
 * stats_check.c - run the real capture, writer and status code with known
 * input and compare g_stats with what the threads actually did.
 *
 *   stats_check [-n frames per channel] [-g gap between frames, in spins]
 *
 * Two capture threads call capture_emit() for n frames each, with a short
 * busy gap between frames standing in for the ADC, and count for themselves
 * how many records went into a ring; the writer drains into /dev/null; the
 * status thread prints its line every status_period_ms.
 */
#include <fcntl.h>
#include <inttypes.h>
#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>

#include "msgpool.h"
#include "stats.h"
#include "telemetryd.h"

volatile bool g_stop;

static struct ring s_ring[TLM_CHANNELS];
static struct capture s_cap[TLM_CHANNELS];
static struct writer s_writer;
static uint32_t s_frames = 4000000;
static uint32_t s_gap = 200;
static uint64_t s_pushed[TLM_CHANNELS], s_full[TLM_CHANNELS];
static volatile bool s_capture_done;

static void *capture_n(void *arg)
{
	struct capture *c = arg;
	struct adc_frame f = { 0 };

	for (uint32_t i = 0; i < s_frames; i++) {
		for (volatile uint32_t spin = 0; spin < s_gap; spin++)
			;
		f.t_ns = (uint64_t)i * 50000;
		f.samples[0] = (int16_t)i;
		if (capture_emit(c, &f))
			s_pushed[c->channel]++;
		else
			s_full[c->channel]++;
	}
	return NULL;
}

static void *writer_run(void *arg)
{
	(void)arg;
	while (!s_capture_done)
		if (writer_drain(&s_writer) == 0)
			writer_flush(&s_writer);
	while (writer_drain(&s_writer) != 0)
		;
	writer_flush(&s_writer);
	return NULL;
}

static void row(const char *name, uint64_t expected, uint64_t counted)
{
	printf("  %-14s %10" PRIu64 " %10" PRIu64 "  %s\n", name, expected, counted,
	       expected == counted ? "ok" : "MISMATCH");
}

int main(int argc, char **argv)
{
	pthread_t cap[TLM_CHANNELS], wr, st;
	struct ring *rings[TLM_CHANNELS];
	uint64_t pushed = 0, full = 0;
	int opt, bad;

	setvbuf(stdout, NULL, _IOLBF, 0);
	while ((opt = getopt(argc, argv, "n:g:")) != -1) {
		if (opt == 'n')
			s_frames = (uint32_t)strtoul(optarg, NULL, 10);
		else if (opt == 'g')
			s_gap = (uint32_t)strtoul(optarg, NULL, 10);
	}

	printf("stats_check: %d capture threads x %" PRIu32 " frames, gap %" PRIu32
	       " spins, writer to /dev/null\n", TLM_CHANNELS, s_frames, s_gap);
	msgpool_init();
	s_writer.fd = open("/dev/null", O_WRONLY);
	for (unsigned ch = 0; ch < TLM_CHANNELS; ch++) {
		ring_init(&s_ring[ch]);
		rings[ch] = &s_ring[ch];
		s_writer.ring[ch] = &s_ring[ch];
		s_cap[ch] = (struct capture){ .channel = ch, .ring = &s_ring[ch] };
	}

	pthread_create(&st, NULL, status_thread, rings);
	pthread_create(&wr, NULL, writer_run, NULL);
	for (unsigned ch = 0; ch < TLM_CHANNELS; ch++)
		pthread_create(&cap[ch], NULL, capture_n, &s_cap[ch]);
	for (unsigned ch = 0; ch < TLM_CHANNELS; ch++)
		pthread_join(cap[ch], NULL);
	s_capture_done = true;
	pthread_join(wr, NULL);
	g_stop = true;
	pthread_join(st, NULL);

	for (unsigned ch = 0; ch < TLM_CHANNELS; ch++) {
		pushed += s_pushed[ch];
		full += s_full[ch];
	}
	printf("stats_check: done\n  %-14s %10s %10s\n", "counter", "expected", "g_stats");
	row("captured", pushed, g_stats.captured);
	row("dropped", full, g_stats.dropped);
	row("written", pushed, g_stats.written);
	row("bytes_written", pushed * sizeof(struct tlm_rec), g_stats.bytes_written);
	bad = g_stats.captured != pushed || g_stats.dropped != full ||
	      g_stats.written != pushed ||
	      g_stats.bytes_written != pushed * sizeof(struct tlm_rec);
	printf("stats_check: %s\n", bad ? "FAIL" : "PASS");
	return bad;
}

