    Night,
}

fn action(light: Light, mode: Mode) -> &'static str {
    match (light, mode) {
        (Light::Red, _) => "stop",
        (Light::Green, Mode::Normal) => "go",
        (Light::Amber, Mode::Normal) => "wait",
        (_, Mode::Night) => "slow",
    }
}

