// src/api/searchCache.ts
import { searchProducts, type Product } from "./search";

type Entry = { items: Product[]; total: number };
const cache = new Map<string, Entry>();

export async function searchWithCache(
  query: string,
  inStockOnly: boolean,
  signal: AbortSignal
): Promise<Entry> {
  const key = query;
  const hit = cache.get(key);
  if (hit) return hit;

  const res = await searchProducts(query, inStockOnly, signal);
  const entry = { items: res.items, total: res.total };
  cache.set(key, entry);
  return entry;
}
