--- README.md ---
# sensor-gw

Gateway daemon for the vibration sensor hub. Runs on the gateway board
(quad-core Cortex-A53, embedded Linux, glibc 2.39, systemd 255).

```
sensor hub --UART 921600--> acquisition (main thread)
                               |  frame (100 samples x 3 axes, every 100 ms)
                               v
                          ring_queue (depth 2)
                               |
                 wk0 .. wk3: encode, then POST /v1/frames to the collector
                               (at most 2 uploads in flight: uplink slots)
```

- The hub samples at 1 kHz and sends one frame every 100 ms. If the gateway
  does not read, the hub keeps 4 frames and then drops new ones, reporting
  the count in the next frame (`lost`).
- Frames and upload bodies come from a fixed pool of 8 buffers of 2 KB
  (`buf_pool.c`); nothing is allocated after start-up.
- The collector accepts at most 2 concurrent uploads per device and answers
  429 to a third. 429, 5xx and network errors are retried with backoff
  (1, 2, 4 ... 60 s); 400 (bad CRC) and 409 (duplicate seq) are dropped.
- `wdog` logs a stats line every 10 s (or on SIGUSR1) and dumps the queue,
  pool, uplink and thread table when nothing was uploaded for 30 s.

## Signals

| Signal | Sent by | Effect |
|---|---|---|
| SIGTERM, SIGINT | systemd (`systemctl stop`), Ctrl-C | stop: drain the queue, join the workers |
| SIGHUP | logrotate, daily (`postrotate: systemctl kill -s HUP sensor-gw.service`) | reopen the log file |
| SIGUSR1 | the device health agent, every 5 s | one stats line now |

The main thread blocks SIGHUP and SIGUSR1 once the workers are running, so
the hub reads in the acquisition loop are not interrupted.

## Build

```
make CROSS_COMPILE=aarch64-linux-gnu-
make install DESTDIR=../rootfs
```

## Run

```
sensor-gw -d /dev/ttyS2 -c collector.local:8443 -i <device-id> -l /var/log/sensor-gw.log [-v]
```

`-v` logs one debug line per frame (buffer ids, HTTP status, latency).

--- dist/sensor-gw.service ---
[Unit]
Description=Sensor hub gateway
After=network-online.target time-sync.target
Wants=network-online.target

[Service]
EnvironmentFile=/etc/default/sensor-gw
ExecStart=/usr/bin/sensor-gw -d /dev/ttyS2 -c ${COLLECTOR} -i ${DEVICE_ID} -l /var/log/sensor-gw.log
ExecReload=/bin/kill -HUP $MAINPID
Restart=on-failure
RestartSec=2
TimeoutStopSec=10

[Install]
WantedBy=multi-user.target

--- src/acq.c ---
/* acq.c: read frames from the sensor hub (UART, 921600 8N1) and queue them.
 *
 * The hub samples at 1 kHz and sends a frame of 100 samples every 100 ms.
 * It keeps up to 4 frames in its own FIFO while we are not reading, then
 * drops new frames and reports the count in the next frame's `lost`.
 */
#include <errno.h>
#include <fcntl.h>
#include <string.h>
#include <sys/ioctl.h>
#include <termios.h>
#include <unistd.h>

#include "acq.h"
#include "buf_pool.h"
#include "log.h"
#include "ring_queue.h"

int acq_open(struct acq *a, const char *dev, struct gw *gw)
{
	struct termios tio;

	memset(a, 0, sizeof(*a));
	a->gw = gw;
	a->fd = open(dev, O_RDONLY | O_NOCTTY | O_CLOEXEC);
	if (a->fd < 0)
		return -1;
	if (isatty(a->fd)) {
		tcgetattr(a->fd, &tio);
		cfmakeraw(&tio);
		cfsetispeed(&tio, B921600);
		tio.c_cc[VMIN] = 1;
		tio.c_cc[VTIME] = 0;
		tcsetattr(a->fd, TCSANOW, &tio);
	}
	return 0;
}

/* Returns 0, or -1 on EOF, a read error, or a stop request. */
static int read_full(int fd, uint8_t *p, size_t n, volatile sig_atomic_t *stop)
{
	while (n > 0) {
		ssize_t r = read(fd, p, n);

		if (r < 0 && errno == EINTR) {
			if (*stop)
				return -1;
			continue;
		}
		if (r <= 0)
			return -1;
		p += r;
		n -= (size_t)r;
	}
	return 0;
}

/* Reads one frame into b, resynchronising on the magic if needed. */
static int read_frame(struct acq *a, struct gw_buf *b, volatile sig_atomic_t *stop)
{
	struct hub_frame_hdr *fh = (void *)b->data;

	if (read_full(a->fd, b->data, sizeof(fh->magic), stop) != 0)
		return -1;
	while (fh->magic != HUB_MAGIC) {
		b->data[0] = b->data[1];
		if (read_full(a->fd, b->data + 1, 1, stop) != 0)
			return -1;
	}
	if (read_full(a->fd, b->data + sizeof(fh->magic),
		      HUB_FRAME_SIZE - sizeof(fh->magic), stop) != 0)
		return -1;
	b->len = HUB_FRAME_SIZE;
	return 0;
}

int acq_run(struct acq *a, volatile sig_atomic_t *stop)
{
	struct gw *gw = a->gw;
	int backlog_logged = 0;

	thr_set_state("run");
	while (!*stop) {
		struct gw_buf *b = pool_get(gw->pool);
		const struct hub_frame_hdr *fh = (const void *)b->data;
		int avail = 0, backlog;

		thr_set_state("hub read");
		if (read_frame(a, b, stop) != 0) {
			pool_put(gw->pool, b);
			break;
		}
		thr_set_state("run");
		a->frames++;
		if (fh->lost) {
			a->lost += fh->lost;
			LOG_W("hub dropped %u frames before seq %u", fh->lost, fh->seq);
		}

		/* Frames already waiting in the UART buffer: we are behind. */
		ioctl(a->fd, FIONREAD, &avail);
		backlog = avail / (int)HUB_FRAME_SIZE;
		if (backlog >= 3 && backlog_logged == 0)
			LOG_I("hub backlog %d frames", backlog);
		backlog_logged = backlog >= 3;

		if (rq_put(gw->q, b) != 0) {
			pool_put(gw->pool, b);
			break;
		}
	}
	LOG_I("acquisition stopped after %lu frames (%lu lost at the hub)",
	      a->frames, a->lost);
	return 0;
}

