/* uplink.c: POST encoded frames to the collector.
 *
 * The collector allows GW_UPLINK_SLOTS concurrent uploads per device and
 * answers 429 to the next one; the counting semaphore keeps us under it.
 */
#include <errno.h>

#include "http.h"
#include "log.h"
#include "uplink.h"

static double elapsed_s(const struct timespec *from)
{
	struct timespec now;

	clock_gettime(CLOCK_MONOTONIC, &now);
	return (now.tv_sec - from->tv_sec) + (now.tv_nsec - from->tv_nsec) / 1e9;
}

int uplink_init(struct uplink *u, const char *host, const char *port,
		const char *device)
{
	int err;

	u->host = host;
	u->port = port;
	u->device = device;
	u->stopping = false;
	u->in_flight = u->in_flight_max = 0;
	u->sent = u->http_429 = u->rejected = u->failed = 0;
	clock_gettime(CLOCK_MONOTONIC, &u->last_sent);
	if (sem_init(&u->slots, 0, GW_UPLINK_SLOTS) != 0)
		return errno;
	err = pthread_mutex_init(&u->lock, NULL);
	if (err == 0)
		err = pthread_cond_init(&u->stop_cv, NULL);
	return err;
}

enum up_result uplink_send(struct uplink *u, const struct gw_buf *body, uint32_t seq)
{
	enum up_result res;
	struct timespec t0;
	int status;

	thr_set_state("slot wait");
	sem_wait(&u->slots);
	thr_set_state("http post");

	pthread_mutex_lock(&u->lock);
	u->in_flight++;
	if (u->in_flight > u->in_flight_max)
		u->in_flight_max = u->in_flight;
	pthread_mutex_unlock(&u->lock);

	clock_gettime(CLOCK_MONOTONIC, &t0);
	status = http_post(u->host, u->port, "/v1/frames", u->device,
			   body->data, body->len, GW_HTTP_TIMEOUT_S);

	pthread_mutex_lock(&u->lock);
	u->in_flight--;
	if (status == 201) {
		u->sent++;
		clock_gettime(CLOCK_MONOTONIC, &u->last_sent);
		res = UP_OK;
	} else if (status == 429 || status >= 500 || status < 0) {
		if (status == 429)
			u->http_429++;
		else
			u->failed++;
		res = UP_RETRY;
	} else {
		u->rejected++;
		res = UP_REJECTED;
	}
	pthread_mutex_unlock(&u->lock);
	sem_post(&u->slots);
	thr_set_state("run");

	LOG_D("frame %u: %d in %.0f ms", seq, status, elapsed_s(&t0) * 1000);
	return res;
}

bool uplink_backoff(struct uplink *u, unsigned attempt)
{
	struct timespec until;
	unsigned delay = attempt < 6 ? 1u << attempt : GW_BACKOFF_MAX_S;
	bool stopping;
	int err = 0;

	clock_gettime(CLOCK_REALTIME, &until);
	until.tv_sec += delay;

	thr_set_state("backoff");
	pthread_mutex_lock(&u->lock);
	while (!u->stopping && err != ETIMEDOUT)
		err = pthread_cond_timedwait(&u->stop_cv, &u->lock, &until);
	stopping = u->stopping;
	pthread_mutex_unlock(&u->lock);
	thr_set_state("run");
	return stopping;
}

void uplink_stop(struct uplink *u)
{
	pthread_mutex_lock(&u->lock);
	u->stopping = true;
	pthread_cond_broadcast(&u->stop_cv);
	pthread_mutex_unlock(&u->lock);
}

void uplink_stats(struct uplink *u, struct uplink_stats *st)
{
	sem_getvalue(&u->slots, &st->slots_free);
	pthread_mutex_lock(&u->lock);
	st->in_flight = u->in_flight;
	st->in_flight_max = u->in_flight_max;
	st->sent = u->sent;
	st->http_429 = u->http_429;
	st->rejected = u->rejected;
	st->failed = u->failed;
	st->since_sent_s = elapsed_s(&u->last_sent);
	u->in_flight_max = u->in_flight;
	pthread_mutex_unlock(&u->lock);
}

