/* log.h: line logger and the thread table the watchdog dumps. */
#ifndef GW_LOG_H
#define GW_LOG_H

#include <stdbool.h>

extern bool g_log_verbose;

int  log_open(const char *path, bool verbose);   /* path NULL: stderr */
void log_reopen(void);                           /* after logrotate moved the file */
void log_msg(char level, const char *fmt, ...) __attribute__((format(printf, 2, 3)));

#define LOG_D(...) do { if (g_log_verbose) log_msg('D', __VA_ARGS__); } while (0)
#define LOG_I(...) log_msg('I', __VA_ARGS__)
#define LOG_W(...) log_msg('W', __VA_ARGS__)
#define LOG_E(...) log_msg('E', __VA_ARGS__)

/* Thread table. Each thread registers itself once, then marks what it is
 * about to block on, so a dump shows where every thread is. */
#define THR_MAX 8

void thr_register(const char *name);
void thr_set_state(const char *state);           /* a string literal */
void thr_exited(void);
void thr_dump(void);                             /* one log line per thread */

#endif

--- src/main.c ---
/* main.c: sensor-gw: sensor hub -> queue -> workers -> collector.
 *
 *   sensor-gw -d /dev/ttyS2 -c collector.local:8443 -i <device-id> [-l file] [-v]
 *
 * Threads: main runs acquisition; wk0..wk3 encode and upload; wdog prints
 * stats and dumps state when uploads stop. Signals: TERM/INT stop,
 * HUP reopens the log (logrotate), USR1 asks for a stats line now.
 */
#include <errno.h>
#include <pthread.h>
#include <semaphore.h>
#include <signal.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>

#include "acq.h"
#include "buf_pool.h"
#include "log.h"
#include "ring_queue.h"
#include "uplink.h"
#include "worker.h"

static volatile sig_atomic_t g_stop;
static sem_t g_stats_req;              /* posted by SIGUSR1 */

static struct ring_queue g_queue;
static struct buf_pool   g_pool;
static struct uplink     g_uplink;
static struct gw         g_gw = { &g_queue, &g_pool, &g_uplink };

static void on_stop(int sig)
{
	(void)sig;
	g_stop = 1;
}

static void on_hup(int sig)
{
	(void)sig;
	log_reopen();
}

static void on_usr1(int sig)
{
	(void)sig;
	sem_post(&g_stats_req);        /* async-signal-safe */
}

static void log_stats(void)
{
	struct rq_stats q;
	struct pool_stats p;
	struct uplink_stats u;

	rq_stats(&g_queue, &q);
	pool_stats(&g_pool, &p);
	uplink_stats(&g_uplink, &u);
	LOG_I("stats queue %u/%d puts %lu gets %lu | pool free %d min %d waits %lu | "
	      "uplink slots %d in_flight %u max %u sent %lu 429 %lu rejected %lu failed %lu",
	      q.count, GW_QUEUE_DEPTH, q.puts, q.gets, p.nfree, p.min_free, p.waits,
	      u.slots_free, u.in_flight, u.in_flight_max, u.sent, u.http_429,
	      u.rejected, u.failed);
}

static void dump_state(const char *why)
{
	struct rq_stats q;
	struct pool_stats p;
	struct uplink_stats u;

	rq_stats(&g_queue, &q);
	pool_stats(&g_pool, &p);
	uplink_stats(&g_uplink, &u);
	LOG_W("%s, state dump follows", why);
	LOG_W("  queue  count %u/%d closed %d puts %lu gets %lu put_waits %lu get_waits %lu",
	      q.count, GW_QUEUE_DEPTH, q.closed, q.puts, q.gets, q.put_waits, q.get_waits);
	LOG_W("  pool   free %d/%d waits %lu", p.nfree, GW_POOL_BUFS, p.waits);
	LOG_W("  uplink slots %d in_flight %u sent %lu 429 %lu rejected %lu failed %lu",
	      u.slots_free, u.in_flight, u.sent, u.http_429, u.rejected, u.failed);
	thr_dump();
}

static sem_t g_wdog_quit;              /* posted once by main at stop */

static void *wdog_main(void *arg)
{
	struct timespec one_s = { 1, 0 };
	unsigned ticks = 0;
	bool dumped = false;

	(void)arg;
	thr_register("wdog");
	while (sem_trywait(&g_wdog_quit) != 0) {
		struct uplink_stats u;

		thr_set_state("sleep");
		nanosleep(&one_s, NULL);
		thr_set_state("run");
		if (sem_trywait(&g_stats_req) == 0 || ++ticks % GW_STATS_EVERY_S == 0)
			log_stats();

		uplink_stats(&g_uplink, &u);
		if (u.since_sent_s >= GW_STALL_S && !dumped) {
			dump_state("no frame uploaded for 30 s");
			dumped = true;
		} else if (u.since_sent_s < GW_STALL_S) {
			dumped = false;
		}
	}
	thr_exited();
	return NULL;
}

static int install(int sig, void (*fn)(int))
{
	struct sigaction sa = { .sa_handler = fn };

	sigemptyset(&sa.sa_mask);
	if (sigaction(sig, &sa, NULL) != 0) {
		fprintf(stderr, "sigaction(%d): %s\n", sig, strerror(errno));
		return -1;
	}
	return 0;
}

static void usage(void)
{
	fprintf(stderr, "usage: sensor-gw -d tty -c host:port -i device-id [-l logfile] [-v]\n");
	exit(2);
}

int main(int argc, char **argv)
{
	const char *dev = NULL, *collector = NULL, *device = NULL, *logfile = NULL;
	struct worker workers[GW_N_WORKERS];
	pthread_t wk_tid[GW_N_WORKERS], wdog_tid;
	struct acq acq;
	char host[128], *port;
	bool verbose = false;
	sigset_t set;
	int opt, i;

	while ((opt = getopt(argc, argv, "d:c:i:l:v")) != -1) {
		switch (opt) {
		case 'd': dev = optarg; break;
		case 'c': collector = optarg; break;
		case 'i': device = optarg; break;
		case 'l': logfile = optarg; break;
		case 'v': verbose = true; break;
		default: usage();
		}
	}
	if (!dev || !collector || !device)
		usage();
	snprintf(host, sizeof(host), "%s", collector);
	port = strrchr(host, ':');
	if (port == NULL)
		usage();
	*port++ = '\0';

	if (log_open(logfile, verbose) != 0) {
		perror(logfile);
		return 1;
	}
	thr_register("acq");
	LOG_I("sensor-gw %s starting: %d workers, queue %d, pool %d, uplink slots %d",
	      GW_VERSION, GW_N_WORKERS, GW_QUEUE_DEPTH, GW_POOL_BUFS, GW_UPLINK_SLOTS);

	sem_init(&g_stats_req, 0, 0);
	sem_init(&g_wdog_quit, 0, 0);
	if (install(SIGTERM, on_stop) || install(SIGINT, on_stop) ||
	    install(SIGHUP, on_hup) || install(SIGUSR1, on_usr1))
		return 1;
	signal(SIGPIPE, SIG_IGN);

	if (rq_init(&g_queue) || pool_init(&g_pool) ||
	    uplink_init(&g_uplink, host, port, device)) {
		LOG_E("init failed");
		return 1;
	}
	if (acq_open(&acq, dev, &g_gw) != 0) {
		LOG_E("%s: %s", dev, strerror(errno));
		return 1;
	}

	for (i = 0; i < GW_N_WORKERS; i++) {
		workers[i].gw = &g_gw;
		workers[i].idx = i;
		snprintf(workers[i].name, sizeof(workers[i].name), "wk%d", i);
		pthread_create(&wk_tid[i], NULL, worker_main, &workers[i]);
		pthread_setname_np(wk_tid[i], workers[i].name);
	}
	pthread_create(&wdog_tid, NULL, wdog_main, NULL);
	pthread_setname_np(wdog_tid, "wdog");

	/* Keep the hub reads free of EINTR: HUP and USR1 go to the other threads. */
	sigemptyset(&set);
	sigaddset(&set, SIGHUP);
	sigaddset(&set, SIGUSR1);
	pthread_sigmask(SIG_BLOCK, &set, NULL);

	acq_run(&acq, &g_stop);

	LOG_I("stopping");
	thr_set_state("stopping");
	rq_close(&g_queue);
	uplink_stop(&g_uplink);
	for (i = 0; i < GW_N_WORKERS; i++) {
		struct timespec deadline;

		clock_gettime(CLOCK_REALTIME, &deadline);
		deadline.tv_sec += GW_JOIN_WARN_S;
		if (pthread_timedjoin_np(wk_tid[i], NULL, &deadline) == ETIMEDOUT) {
			dump_state("stop: a worker is still running after 5 s");
			pthread_join(wk_tid[i], NULL);
		}
	}
	sem_post(&g_wdog_quit);
	pthread_join(wdog_tid, NULL);
	LOG_I("stopped");
	return 0;
}

--- src/ring_queue.c ---
/* ring_queue.c: bounded queue of frames, acquisition -> workers.
 *
 * One producer (the acquisition thread), GW_N_WORKERS consumers.
 */
#include "ring_queue.h"
#include "log.h"

int rq_init(struct ring_queue *q)
{
	int err;

	q->head = q->tail = q->count = 0;
	q->closed = false;
	q->puts = q->gets = q->put_waits = q->get_waits = 0;
	err = pthread_mutex_init(&q->lock, NULL);
	if (err == 0)
		err = pthread_cond_init(&q->changed, NULL);
	return err;
}

int rq_put(struct ring_queue *q, struct gw_buf *b)
{
	pthread_mutex_lock(&q->lock);
	while (q->count == GW_QUEUE_DEPTH && !q->closed) {
		q->put_waits++;
		thr_set_state("rq_put wait");
		pthread_cond_wait(&q->changed, &q->lock);
	}
	thr_set_state("run");
	if (q->closed) {
		pthread_mutex_unlock(&q->lock);
		return -1;
	}
	q->slot[q->tail] = b;
	q->tail = (q->tail + 1) % GW_QUEUE_DEPTH;
	q->count++;
	q->puts++;
	pthread_cond_signal(&q->changed);
	pthread_mutex_unlock(&q->lock);
	return 0;
}

struct gw_buf *rq_get(struct ring_queue *q)
{
	struct gw_buf *b = NULL;

	pthread_mutex_lock(&q->lock);
	while (q->count == 0 && !q->closed) {
		q->get_waits++;
		thr_set_state("rq_get wait");
		pthread_cond_wait(&q->changed, &q->lock);
	}
	thr_set_state("run");
	if (q->count > 0) {
		b = q->slot[q->head];
		q->head = (q->head + 1) % GW_QUEUE_DEPTH;
		q->count--;
		q->gets++;
		pthread_cond_signal(&q->changed);
	}
	pthread_mutex_unlock(&q->lock);
	return b;
}

/* Called once, by main, after the acquisition loop has returned: no put can
 * race with it, and a bool store is atomic on every target we build for. */
void rq_close(struct ring_queue *q)
{
	q->closed = true;
	pthread_cond_broadcast(&q->changed);
}

void rq_stats(struct ring_queue *q, struct rq_stats *st)
{
	pthread_mutex_lock(&q->lock);
	st->count = q->count;
	st->closed = q->closed;
	st->puts = q->puts;
	st->gets = q->gets;
	st->put_waits = q->put_waits;
	st->get_waits = q->get_waits;
	pthread_mutex_unlock(&q->lock);
}

--- src/ring_queue.h ---
/* ring_queue.h: bounded queue of frames, acquisition -> workers. */
#ifndef RING_QUEUE_H
#define RING_QUEUE_H

#include <pthread.h>
#include <stdbool.h>

#include "gw.h"

struct ring_queue {
	pthread_mutex_t  lock;
	pthread_cond_t   changed;        /* count went up or down */
	struct gw_buf   *slot[GW_QUEUE_DEPTH];
	unsigned         head;           /* next to get */
	unsigned         tail;           /* next free slot */
	unsigned         count;
	bool             closed;
	/* stats, under lock */
	unsigned long    puts, gets, put_waits, get_waits;
};

struct rq_stats {
	unsigned      count;
	bool          closed;
	unsigned long puts, gets, put_waits, get_waits;
};

int            rq_init(struct ring_queue *q);
/* Blocks while the queue is full. Returns -1 if the queue was closed. */
int            rq_put(struct ring_queue *q, struct gw_buf *b);
/* Blocks while the queue is empty. Returns NULL once closed and empty. */
struct gw_buf *rq_get(struct ring_queue *q);
/* Wake every waiter; puts fail from now on, gets drain what is left. */
void           rq_close(struct ring_queue *q);
void           rq_stats(struct ring_queue *q, struct rq_stats *st);

#endif

--- src/uplink.c ---
/* uplink.c: POST encoded frames to the collector.
 *
 * The collector allows GW_UPLINK_SLOTS concurrent uploads per device and
 * answers 429 to the next one; the counting semaphore keeps us under it.
 */
#include <errno.h>

#include "http.h"
#include "log.h"
#include "uplink.h"

static double elapsed_s(const struct timespec *from)
{
	struct timespec now;

	clock_gettime(CLOCK_MONOTONIC, &now);
	return (now.tv_sec - from->tv_sec) + (now.tv_nsec - from->tv_nsec) / 1e9;
}

int uplink_init(struct uplink *u, const char *host, const char *port,
		const char *device)
{
	int err;

	u->host = host;
	u->port = port;
	u->device = device;
	u->stopping = false;
	u->in_flight = u->in_flight_max = 0;
	u->sent = u->http_429 = u->rejected = u->failed = 0;
	clock_gettime(CLOCK_MONOTONIC, &u->last_sent);
	if (sem_init(&u->slots, 0, GW_UPLINK_SLOTS) != 0)
		return errno;
	err = pthread_mutex_init(&u->lock, NULL);
	if (err == 0)
		err = pthread_cond_init(&u->stop_cv, NULL);
	return err;
}

enum up_result uplink_send(struct uplink *u, const struct gw_buf *body, uint32_t seq)
{
	enum up_result res;
	struct timespec t0;
	int status;

	thr_set_state("slot wait");
	sem_wait(&u->slots);
	thr_set_state("http post");

	pthread_mutex_lock(&u->lock);
	u->in_flight++;
	if (u->in_flight > u->in_flight_max)
		u->in_flight_max = u->in_flight;
	pthread_mutex_unlock(&u->lock);

	clock_gettime(CLOCK_MONOTONIC, &t0);
	status = http_post(u->host, u->port, "/v1/frames", u->device,
			   body->data, body->len, GW_HTTP_TIMEOUT_S);

	pthread_mutex_lock(&u->lock);
	u->in_flight--;
	if (status == 201) {
		u->sent++;
		clock_gettime(CLOCK_MONOTONIC, &u->last_sent);
		res = UP_OK;
	} else if (status == 429 || status >= 500 || status < 0) {
		if (status == 429)
			u->http_429++;
		else
			u->failed++;
		res = UP_RETRY;
	} else {
		u->rejected++;
		res = UP_REJECTED;
	}
	pthread_mutex_unlock(&u->lock);
	sem_post(&u->slots);
	thr_set_state("run");

	LOG_D("frame %u: %d in %.0f ms", seq, status, elapsed_s(&t0) * 1000);
	return res;
}

bool uplink_backoff(struct uplink *u, unsigned attempt)
{
	struct timespec until;
	unsigned delay = attempt < 6 ? 1u << attempt : GW_BACKOFF_MAX_S;
	bool stopping;
	int err = 0;

	clock_gettime(CLOCK_REALTIME, &until);
	until.tv_sec += delay;

	thr_set_state("backoff");
	pthread_mutex_lock(&u->lock);
	while (!u->stopping && err != ETIMEDOUT)
		err = pthread_cond_timedwait(&u->stop_cv, &u->lock, &until);
	stopping = u->stopping;
	pthread_mutex_unlock(&u->lock);
	thr_set_state("run");
	return stopping;
}

void uplink_stop(struct uplink *u)
{
	pthread_mutex_lock(&u->lock);
	u->stopping = true;
	pthread_cond_broadcast(&u->stop_cv);
	pthread_mutex_unlock(&u->lock);
}

void uplink_stats(struct uplink *u, struct uplink_stats *st)
{
	sem_getvalue(&u->slots, &st->slots_free);
	pthread_mutex_lock(&u->lock);
	st->in_flight = u->in_flight;
	st->in_flight_max = u->in_flight_max;
	st->sent = u->sent;
	st->http_429 = u->http_429;
	st->rejected = u->rejected;
	st->failed = u->failed;
	st->since_sent_s = elapsed_s(&u->last_sent);
	u->in_flight_max = u->in_flight;
	pthread_mutex_unlock(&u->lock);
}

--- src/uplink.h ---
/* uplink.h: uploads to the collector, at most GW_UPLINK_SLOTS at a time. */
#ifndef UPLINK_H
#define UPLINK_H

#include <pthread.h>
#include <semaphore.h>
#include <stdbool.h>
#include <stdint.h>
#include <time.h>

#include "gw.h"

enum up_result {
	UP_OK,          /* 201 */
	UP_RETRY,       /* 429, 5xx, timeout, connection error: back off and resend */
	UP_REJECTED,    /* other 4xx: the collector will never take this body */
};

struct uplink {
	const char      *host;
	const char      *port;
	const char      *device;
	sem_t            slots;          /* free upload slots */
	pthread_mutex_t  lock;           /* everything below */
	pthread_cond_t   stop_cv;        /* broadcast by uplink_stop() */
	bool             stopping;
	unsigned         in_flight;
	unsigned         in_flight_max;  /* since last stats */
	unsigned long    sent, http_429, rejected, failed;
	struct timespec  last_sent;      /* CLOCK_MONOTONIC */
};

struct uplink_stats {
	int           slots_free;
	unsigned      in_flight, in_flight_max;
	unsigned long sent, http_429, rejected, failed;
	double        since_sent_s;
};

int            uplink_init(struct uplink *u, const char *host, const char *port,
			   const char *device);
enum up_result uplink_send(struct uplink *u, const struct gw_buf *body, uint32_t seq);
/* Sleeps before retry number `attempt` (1, 2, 4 ... 60 s).
 * Returns true if the uplink is stopping. */
bool           uplink_backoff(struct uplink *u, unsigned attempt);
void           uplink_stop(struct uplink *u);
/* Copies the counters and starts a new in_flight_max. */
void           uplink_stats(struct uplink *u, struct uplink_stats *st);

#endif

