/* worker.c: GW_N_WORKERS threads: take a frame, encode it, upload it. */
#include <string.h>

#include "buf_pool.h"
#include "log.h"
#include "ring_queue.h"
#include "uplink.h"
#include "worker.h"

/* Upload body: "GWF1", seq, t0_ms, nsamples, axes, then each axis as int16
 * deltas from the previous sample, then CRC-32 of everything before it. */
struct body_hdr {
	char     magic[4];
	uint32_t seq;
	uint32_t t0_ms;
	uint16_t nsamples;
	uint16_t axes;
};

uint32_t crc32_le(uint32_t crc, const uint8_t *p, size_t n)
{
	crc = ~crc;
	while (n--) {
		crc ^= *p++;
		for (int k = 0; k < 8; k++)
			crc = (crc >> 1) ^ (0xEDB88320u & -(crc & 1u));
	}
	return ~crc;
}

size_t frame_encode(const struct gw_buf *frame, struct gw_buf *out)
{
	const struct hub_frame_hdr *fh = (const void *)frame->data;
	const int16_t *s = (const void *)(frame->data + sizeof(*fh));
	struct body_hdr bh = {
		.magic = { 'G', 'W', 'F', '1' }, .seq = fh->seq, .t0_ms = fh->t0_ms,
		.nsamples = fh->nsamples, .axes = GW_AXES,
	};
	int16_t *d = (void *)(out->data + sizeof(bh));
	uint32_t crc;

	memcpy(out->data, &bh, sizeof(bh));
	for (int a = 0; a < GW_AXES; a++) {
		int16_t prev = 0;

		for (int i = 0; i < fh->nsamples; i++) {
			int16_t v = s[i * GW_AXES + a];

			*d++ = (int16_t)(v - prev);
			prev = v;
		}
	}
	out->len = (size_t)((uint8_t *)d - out->data);
	crc = crc32_le(0, out->data, out->len);
	memcpy(out->data + out->len, &crc, sizeof(crc));
	out->len += sizeof(crc);
	return out->len;
}

void *worker_main(void *arg)
{
	struct worker *w = arg;
	struct gw *gw = w->gw;
	struct gw_buf *frame, *body;

	thr_register(w->name);
	while ((frame = rq_get(gw->q)) != NULL) {
		const struct hub_frame_hdr *fh = (const void *)frame->data;
		uint32_t seq = fh->seq;
		enum up_result res;
		unsigned attempt = 0;

		body = pool_get(gw->pool);
		frame_encode(frame, body);
		LOG_D("frame %u: buf %d, body buf %d, %zu bytes", seq, frame->id,
		      body->id, body->len);

		while ((res = uplink_send(gw->up, body, seq)) == UP_RETRY) {
			if (uplink_backoff(gw->up, attempt++))
				break;
		}
		if (res == UP_REJECTED)
			LOG_W("frame %u: rejected by the collector, dropped", seq);
		else if (res == UP_RETRY)
			LOG_W("frame %u: not sent (stopping)", seq);

		pool_put(gw->pool, body);
		pool_put(gw->pool, frame);
	}
	LOG_I("queue closed, exiting");
	thr_exited();
	return NULL;
}

