/// The first letter of each word, upper-cased, joined.
/// Words are separated by spaces (use split_whitespace).
/// initials("ada lovelace") == "AL", initials("élise martin") == "ÉM"
pub fn initials(name: &str) -> String {
    let mut out = String::new();
    for word in name.split_whitespace() {
        let first = word.chars().next().unwrap_or('\0');
        out.push(first.to_ascii_uppercase());
    }
    out
}

/// The word with its first char upper-cased and the rest unchanged.
/// Note: char::to_uppercase can give MORE than one char ('ß' gives "SS"),
/// so push every char it yields.
/// capitalize("rust") == "Rust", capitalize("ßtraße") == "SStraße", capitalize("") == ""
pub fn capitalize(word: &str) -> String {
    let mut out = String::new();
    if let Some(first) = word.chars().next() {
        out.push(first.to_ascii_uppercase());
        for c in word[1..].chars() {
            out.push(c);
        }
    }
    out
}

/// How many chars in `s` are not ASCII (take more than one byte).
/// count_non_ascii("naïve café") == 2
pub fn count_non_ascii(s: &str) -> usize {
    let mut count = 0;
    for b in s.bytes() {
        if b > 127 {
            count += 1;
        }
    }
    count
}

