export function isFormConfig(x: unknown): x is FormConfig {
  if (typeof x !== "object" || x === null) return false;
  const c = x as Record<string, unknown>;
  if (typeof c.id !== "string" || typeof c.title !== "string" || typeof c.version !== "string") return false;
