function isFieldConfig(x: unknown): x is FieldConfig {
  if (typeof x !== "object" || x === null) return false;
  const f = x as Record<string, unknown>;
  if (typeof f.name !== "string" || typeof f.label !== "string") return false;
  switch (f.kind) {
    case "text":
    case "date":
      return f.defaultValue === undefined || typeof f.defaultValue === "string";
    case "number":
