// src/forms/values.ts
// Value types are derived from the config, so pages stop casting.
type ValueOf<F extends FieldConfig> =
  F extends NumberField ? number :
  F extends CheckboxField ? boolean :
  F extends MultiSelectField ? string[] :
  F extends SelectField ? string :
  string;

export type FormValuesOf<C extends FormConfig> = {
  [F in C["fields"][number] as F["name"]]: ValueOf<F>;
};

export function useFormValues<C extends FormConfig>(config: C) {
  const [values, setValues] = useState<FormValuesOf<C>>(
    () => initialValues(config) as FormValuesOf<C>
