/* record.h - one telemetry record, as it goes from capture to ring to file */
#ifndef TLM_RECORD_H
#define TLM_RECORD_H

#include <stddef.h>
#include <stdint.h>

#define TLM_REC_SAMPLES 20

#define TLM_FLAG_OVERRANGE	0x0001u	/* a sample hit the ADC rail */

struct tlm_rec {
	uint32_t seq;			/* per channel, starts at 0 */
	uint16_t channel;
	uint16_t nsamples;
	uint64_t t_ns;			/* CLOCK_MONOTONIC of the first sample */
	int16_t  samples[TLM_REC_SAMPLES];
	uint32_t flags;
	uint32_t crc;			/* crc32 of every byte before this field */
};

_Static_assert(sizeof(struct tlm_rec) == 64, "one record is one 64-byte line");

uint32_t crc32(uint32_t crc, const void *buf, size_t len);

static inline uint32_t tlm_rec_crc(const struct tlm_rec *rec)
{
	return crc32(0, rec, offsetof(struct tlm_rec, crc));
}

#endif /* TLM_RECORD_H */

--- src/ring.c ---
/* ring.c - SPSC record ring between a capture thread and the writer */
#include "ring.h"

/*
 * Each index has a single writer, so relaxed loads and stores are enough:
 * the indices are _Atomic, so neither side can ever see a torn value, and
 * we stay clear of the barriers a stronger order would add on ARM.
 */

void ring_init(struct ring *r)
{
	atomic_init(&r->head, 0);
	atomic_init(&r->tail, 0);
}

struct tlm_rec *ring_reserve(struct ring *r)
{
	uint32_t head = atomic_load_explicit(&r->head, memory_order_relaxed);
	uint32_t tail = atomic_load_explicit(&r->tail, memory_order_relaxed);

	if (head - tail == RING_SLOTS)
		return NULL;		/* full: the caller counts a drop */
	return &r->slot[head & RING_MASK];
}

void ring_commit(struct ring *r)
{
	uint32_t head = atomic_load_explicit(&r->head, memory_order_relaxed);

	atomic_store_explicit(&r->head, head + 1, memory_order_relaxed);
}

const struct tlm_rec *ring_peek(struct ring *r)
{
	uint32_t tail = atomic_load_explicit(&r->tail, memory_order_relaxed);
	uint32_t head = atomic_load_explicit(&r->head, memory_order_relaxed);

	if (head == tail)
		return NULL;
	return &r->slot[tail & RING_MASK];
}

void ring_pop(struct ring *r)
{
	uint32_t tail = atomic_load_explicit(&r->tail, memory_order_relaxed);

	atomic_store_explicit(&r->tail, tail + 1, memory_order_relaxed);
}

uint32_t ring_count(struct ring *r)
{
	uint32_t tail = atomic_load_explicit(&r->tail, memory_order_relaxed);
	uint32_t head = atomic_load_explicit(&r->head, memory_order_relaxed);

	return head - tail;
}

--- src/ring.h ---
/*
 * ring.h - single-producer, single-consumer ring of telemetry records.
 *
 * One capture thread fills slots, the writer thread reads them. Records are
 * built in place (no copy on the way in or out). head and tail
 * run free: they only ever go up and wrap at 2^32, and a record's slot is
 * index & RING_MASK (the same scheme as the kernel's kfifo). The ring is
 * full when head - tail == RING_SLOTS and empty when head == tail.
 */
#ifndef TLM_RING_H
#define TLM_RING_H

#include <stdatomic.h>
#include <stdbool.h>
#include <stdint.h>

#include "record.h"

#define RING_SLOTS	1024u		/* must be a power of two */
#define RING_MASK	(RING_SLOTS - 1)

struct ring {
	_Atomic uint32_t head;		/* next slot to fill, written by the producer only */
	_Atomic uint32_t tail;		/* next slot to read, written by the consumer only */
	struct tlm_rec slot[RING_SLOTS];
};

void ring_init(struct ring *r);

/* producer side: fill the slot ring_reserve() returns, then ring_commit() it */
struct tlm_rec *ring_reserve(struct ring *r);		/* NULL when full */
void ring_commit(struct ring *r);

/* consumer side: peek at the oldest record, then pop it when done with it */
const struct tlm_rec *ring_peek(struct ring *r);
void ring_pop(struct ring *r);

/* any thread; a snapshot, may be stale by the time it returns */
uint32_t ring_count(struct ring *r);

#endif /* TLM_RING_H */

--- src/stats.c ---
/* stats.c - the shared counters and the status thread that reports them */
#include <inttypes.h>
#include <stdio.h>
#include <string.h>
#include <time.h>

#include "config.h"
#include "msgpool.h"
#include "stats.h"
#include "telemetryd.h"

struct tlm_stats g_stats;

int stats_format(char *buf, size_t len, const struct tlm_stats *s,
		 const uint32_t *ring_backlog, unsigned nrings)
{
	uint64_t in_flight = s->captured - s->written;
	int n;

	n = snprintf(buf, len,
		     "captured=%" PRIu64 " dropped=%" PRIu64 " written=%" PRIu64
		     " in_flight=%" PRIu64 " crc_errors=%" PRIu64
		     " events=%" PRIu64 "/%" PRIu64,
		     s->captured, s->dropped, s->written, in_flight,
		     s->crc_errors, s->events_sent, s->events_dropped);
	for (unsigned i = 0; i < nrings && n > 0 && (size_t)n < len; i++)
		n += snprintf(buf + n, len - n, " ring%u=%" PRIu32, i, ring_backlog[i]);
	return n;
}

/* arg: the rings, so the status line can show what each one holds */
void *status_thread(void *arg)
{
	struct ring **rings = arg;
	const struct tlm_config *cfg = config_get();
	struct timespec period = {
		.tv_sec = cfg->status_period_ms / 1000,
		.tv_nsec = (long)(cfg->status_period_ms % 1000) * 1000000L,
	};
	unsigned tick = 0;

	while (!g_stop) {
		struct tlm_stats snap;
		uint32_t backlog[TLM_CHANNELS];
		char line[256];

		nanosleep(&period, NULL);
		snap = g_stats;
		for (unsigned i = 0; i < TLM_CHANNELS; i++)
			backlog[i] = ring_count(rings[i]);
		stats_format(line, sizeof(line), &snap, backlog, TLM_CHANNELS);
		fprintf(stderr, "telemetryd: status: %s\n", line);

		if (++tick % cfg->status_uplink_every == 0) {
			struct msg *m = msgpool_get();

			if (m == NULL) {
				stats_inc(&g_stats.events_dropped);
				continue;
			}
			m->len = (uint16_t)snprintf((char *)m->data, sizeof(m->data),
						    "status %s", line);
			if (m->len >= sizeof(m->data))
				m->len = sizeof(m->data) - 1;
			uplink_post(m);
		}
	}
	return NULL;
}

--- src/stats.h ---
/*
 * stats.h - counters shared by every thread.
 *
 * The capture threads, the writer and the uplink thread bump these on their
 * hot paths; the status thread reads them once a period. An update is a
 * single increment, so there is no lock: volatile makes every update go
 * straight to memory, and the status thread never reads a stale register copy.
 */
#ifndef TLM_STATS_H
#define TLM_STATS_H

#include <stddef.h>
#include <stdint.h>

struct tlm_stats {
	volatile uint64_t captured;	/* records accepted by a ring, both channels */
	volatile uint64_t dropped;	/* records lost because a ring was full */
	volatile uint64_t written;	/* records written to the telemetry file */
	volatile uint64_t bytes_written;
	volatile uint64_t crc_errors;	/* records whose CRC failed in the writer */
	volatile uint64_t events_sent;	/* uplink datagrams sent */
	volatile uint64_t events_dropped;	/* no message buffer free */
};

extern struct tlm_stats g_stats;

static inline void stats_inc(volatile uint64_t *ctr)
{
	(*ctr)++;
}

static inline void stats_add(volatile uint64_t *ctr, uint64_t n)
{
	*ctr += n;
}

int stats_format(char *buf, size_t len, const struct tlm_stats *s,
		 const uint32_t *ring_backlog, unsigned nrings);
void *status_thread(void *arg);

#endif /* TLM_STATS_H */

