fn transfer(totals: &mut [i32], from: usize, to: usize) {
    if from == to {
        totals[from] = 0;
        return;
    }

    if from < to {
        let (left, right) = totals.split_at_mut(to);
        let src = &mut left[from];
        let dst = &mut right[0];
        *dst += *src;
        *src = 0;
    } else {
        let (left, right) = totals.split_at_mut(from);
        let src = &mut right[0];
        let dst = &mut left[to];
        *dst += *src;
        *src = 0;
    }
}

fn main() {
    let mut totals = [10, 20, 30, 40];
    transfer(&mut totals, 3, 0);
    println!("{totals:?}");
    transfer(&mut totals, 1, 1);
