// Implement `bump_min`: add `amount` to the smallest value in `values`, in
// place. If several values tie for smallest, bump the first of them. An empty
// slice is left alone.
//
//   [5, 2, 9, 2] with amount 3  ->  [5, 5, 9, 2]
//
// Run prints the example. Submit checks your function against hidden tests.

fn bump_min(values: &mut [i32], amount: i32) {
    if values.len() == 0 {
        return;
    }
    // Find the position first, reading only (i32 is Copy, so no borrow is kept).
    let mut min_at = 0;
    for i in 1..values.len() {
        if values[i] < values[min_at] {
            min_at = i;
        }
    }
    // Then write through the index: one access at a time, no two live references.
    values[min_at] += amount;
}

