use std::borrow::Cow;

fn clean(s: &str) -> Cow<'_, str> {
    let t = s.trim_matches(' ');
    if !t.contains("  ") && !t.bytes().any(|b| b.is_ascii_uppercase()) {
        return Cow::Borrowed(t); // a slice of `s`: same lifetime as the input
    }
    let mut out = String::with_capacity(t.len());
    let mut last_space = false;
    for c in t.chars() {
        if c == ' ' {
            if !last_space {
                out.push(' ');
            }
            last_space = true;
        } else {
            out.push(c.to_ascii_lowercase());
            last_space = false;
        }
    }
    Cow::Owned(out)
}

fn clean_all<'a>(lines: &[&'a str]) -> Vec<Cow<'a, str>> {
    // `*line` is the &'a str itself. Passing `line` (a &&'a str) would
    // reborrow through the slice and tie the result to `lines`.
    lines.iter().map(|line| clean(*line)).collect()
}

