// Goal: add up any slice of numbers, whatever the number type.
fn total<T>(items: &[T]) -> T
where
    T: Copy + Add<Output = T>,
{
    let mut sum = items[0];
    for x in &items[1..] {
        sum = sum + *x;
    }
    sum
