// Write code: a stack of numbers built from boxed nodes.
// Run: rustc --edition 2024 -o main p6.rs && ./main
// Submit runs hidden tests against push, pop and peek.
//
// Each node owns the next one through Option<Box<Node>>. Do not use Vec.

struct Node {
    value: i32,
    next: Option<Box<Node>>,
}

pub struct Stack {
    head: Option<Box<Node>>,
    len: usize,
}

impl Stack {
    pub fn new() -> Stack {
        Stack { head: None, len: 0 }
    }

    pub fn len(&self) -> usize {
        self.len
    }

    /// Put `value` on top.
    pub fn push(&mut self, value: i32) {
        let new_node = Box::new(Node {
            value,
            next: self.head.take(),
        });
        self.head = Some(new_node);
        self.len += 1;
    }

    /// Take the top value off, or None when empty.
    pub fn pop(&mut self) -> Option<i32> {
        self.head.take().map(|node| {
            let Node { value, next } = *node;
            self.head = next;
            self.len -= 1;
            value
        })
    }

    /// Look at the top value without removing it.
    pub fn peek(&self) -> Option<&i32> {
        self.head.as_ref().map(|node| &node.value)
    }
}

fn main() {
    let mut s = Stack::new();
    s.push(1);
    s.push(2);
    s.push(3);
    println!("peek {:?}, len {}", s.peek(), s.len());
    println!("{:?} {:?} {:?} {:?}", s.pop(), s.pop(), s.pop(), s.pop());
}
