fn head(text: &str, n: usize) -> &str {
    let mut end = 0;
    for (i, ch) in text.char_indices() {
        if n == 0 {
            break;
        }
        end = i + ch.len_utf8();
        n -= 1;
        if n == 0 {
            break;
        }
    }
    &text[..end]
}

