// An outline: a section has a title and one body item;
// an item is text, a nested section, or a list of items.
struct Section {
    title: String,
    body: Item,
}

enum Item {
    Text(String),
    Sub(Section),
    List(Vec<Item>),
}

fn count_titles(item: &Item) -> usize {
    match item {
        Item::Text(_) => 0,
        Item::Sub(s) => 1 + count_titles(&s.body),
        Item::List(items) => items.iter().map(count_titles).sum(),
    }
}

