fn head(text: &str, n: usize) -> &str {
    let mut end = 0;
    for (i, _) in text.char_indices() {
        if i > n {
            break;
        }
        end = i;
    }
    if n >= text.len() {
        text
    } else {
        let mut last = 0;
        for (i, _) in text.char_indices() {
            if i > n {
                break;
            }
            last = i;
        }
        &text[..last]
    }
}

