// Two small functions about numeric types. Fill in both.
//
// 1. `mean_score` returns the exact mean of five scores as an f64.
//    mean_score([1, 2, 2, 2, 2]) is 1.8, and mean_score([255; 5]) is 255.0.
//
// 2. `to_percent` turns any i32 into a u8 between 0 and 100 for a progress bar:
//    below 0 becomes 0, above 100 becomes 100, anything else is unchanged.
//    to_percent(-2) is 0, to_percent(300) is 100, to_percent(42) is 42.
//
// Run prints a few results. Submit checks both functions against hidden tests.

fn mean_score(scores: [u8; 5]) -> f64 {
    // Five u8 values can add up to 1275, so sum in a wider type.
    let mut sum: u32 = 0;
    for s in scores {
        sum += u32::from(s);
    }
    // Convert before dividing so the fraction survives.
    sum as f64 / scores.len() as f64
}

fn to_percent(x: i32) -> u8 {
    // Clamp first; only then is the narrowing `as` lossless.
    let clamped = if x < 0 {
        0
    } else if x > 100 {
        100
    } else {
        x
    };
    clamped as u8
}

fn main() {
    println!("mean: {}", mean_score([90, 85, 100, 70, 95]));
    println!("mean: {}", mean_score([1, 2, 2, 2, 2]));
    println!("percent: {} {} {}", to_percent(-2), to_percent(42), to_percent(300));
}

