import { readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";

const PROMPTS = fileURLToPath(new URL("../prompts/", import.meta.url));

// prompts/<name>.md, with {{var}} placeholders filled in.
export function loadPrompt(name: string, vars: Record<string, string | number> = {}): string {
  let text = readFileSync(`${PROMPTS}${name}.md`, "utf8");
  for (const [key, value] of Object.entries(vars)) {
    text = text.replaceAll(`{{${key}}}`, String(value));
  }
  return text;
}

--- src/run.ts ---
// Runs one ticket through the pipeline.
//
//   node src/run.ts TRK-1482
//
// The worker (src/worker.ts) calls runTicket for every agent-ok ticket it claims.
import { readFileSync } from "node:fs";
import type { LlmClient } from "./llm.ts";
import { gatewayClient } from "./llm.ts";
import type { PipelineConfig, RunRecord } from "./types.ts";
import { runPipeline } from "./pipeline.ts";
import { saveRecord } from "./runs.ts";
import { commentOnTicket, fetchTicket, nextRunId } from "./tracker.ts";

export const RUN_TIMEOUT_MS = Number(process.env.RUN_TIMEOUT_MS ?? 20 * 60_000);

export function loadConfig(path: string | URL = new URL("../pipeline.config.json", import.meta.url)): PipelineConfig {
  return JSON.parse(readFileSync(path, "utf8")) as PipelineConfig;
}

export type TicketDeps = {
  llm: LlmClient;
  config: PipelineConfig;
  fetchTicket: (key: string) => Promise<string>;
  save: (record: RunRecord) => void;
  comment: (key: string, text: string) => Promise<void>;
  now?: () => Date;
  print?: (line: string) => void;
  signal?: AbortSignal;
};

export async function runTicket(key: string, runId: string, deps: TicketDeps): Promise<void> {
  const now = deps.now ?? (() => new Date());
  const print = deps.print ?? ((line: string) => console.log(line));
  const log = (line: string) => print(`${now().toISOString()} [run ${runId}] ${line}`);
  const signal = deps.signal ?? AbortSignal.timeout(RUN_TIMEOUT_MS);
  const { config } = deps;

  log(`start ${key} (handoff.maxWords=${config.handoff.maxWords}, review.maxRevisionRounds=${config.review.maxRevisionRounds})`);
  try {
    const task = await deps.fetchTicket(key);
    const record = await runPipeline({ runId, ticket: key, task }, { llm: deps.llm, config, now, log, signal });
    deps.save(record);
    await deps.comment(key, `agent-pipeline run ${runId}: ${record.status}. Branch: agent/${key}-r${runId}`);
    log(`done: ${record.status}, ${record.messages.length} messages, ${record.totals.tokens} tokens, ${record.totals.toolCalls} tool calls`);
  } catch (err) {
    const e = err as Error;
    log(`failed: ${e.name}: ${e.message}`);
  }
}

if (import.meta.main) {
  const key = process.argv[2];
  if (!key) {
    console.error("usage: node src/run.ts <TICKET>");
    process.exit(2);
  }
  await runTicket(key, await nextRunId(), {
    llm: gatewayClient(),
    config: loadConfig(),
    fetchTicket,
    save: (record) => void saveRecord(record),
    comment: commentOnTicket,
  });
}

