  const timer = setTimeout(async () => {
    const result = await validateRemote(rule, value, country);
    if (seq.current !== current) return;
    setError(result.valid ? undefined : result.message);
  }, 300);

  return () => clearTimeout(timer);
}, [rule, value, country]);
```

