/* Features of one block of samples (acq.c). */
struct feat
{
    float rms_mg;           /* RMS acceleration, DC removed */
    float peak_mg;          /* largest |sample - mean| */
    uint16_t raw_max;       /* largest raw ADC count, for range checks */
};

/* Summary of SUMMARY_BLOCKS blocks, sent to store and uplink. */
struct summary
{
    uint32_t seq;
    uint32_t blocks;
    float rms_mg;           /* RMS over the period */
    float peak_mg;          /* largest block peak */
    float crest;            /* peak / rms */
    int16_t temp_c10;       /* last environment reading, 0.1 C */
    uint16_t rh_pct10;      /* 0.1 %RH */
    uint8_t afe_gain;
    bool alarm;             /* rms_mg above ALARM_RMS_MG */
};

/* Environment reading (env.c). */
