/*
 * fault.c - assert, stack overflow and malloc hooks, and a HardFault handler
 * that keeps a crash record in no-init RAM. The record is printed and sent in
 * the next status message after the reset.
 */
#include <stdio.h>
#include <string.h>

#include "FreeRTOS.h"
#include "task.h"

#include "app.h"
#include "board.h"
#include "mcu_ll.h"

#define CRASH_MAGIC     0xC0FFEE01u

struct crash
{
    uint32_t magic;
    uint32_t pc, lr, psr, cfsr, bfar;
    uint32_t uptime_s;
    char task[ configMAX_TASK_NAME_LEN ];
};

static struct crash s_crash __attribute__( ( section( ".noinit" ) ) );

static void crash_save_task( void )
{
    TaskHandle_t t = xTaskGetCurrentTaskHandle();

    strncpy( s_crash.task, ( t != NULL ) ? pcTaskGetName( t ) : "-", sizeof s_crash.task - 1u );
    s_crash.task[ sizeof s_crash.task - 1u ] = '\0';
}

#ifdef DEBUG
void vAssertCalled( const char * pcFile, unsigned long ulLine )
{
    char msg[ 128 ];
    uint32_t ipsr;

    __asm volatile ( "mrs %0, ipsr" : "=r" ( ipsr ) );
    taskDISABLE_INTERRUPTS();
    snprintf( msg, sizeof msg, "\r\nASSERT %s:%lu ipsr=%lu\r\n", pcFile, ulLine, ( unsigned long ) ipsr );
    console_write( msg );
    __asm volatile ( "bkpt #0" );
    for( ; ; ) { }
}
#endif

void vApplicationStackOverflowHook( TaskHandle_t xTask, char * pcTaskName )
{
    ( void ) xTask;
    console_write( "\r\nSTACK OVERFLOW " );
    console_write( pcTaskName );
    console_write( "\r\n" );
    taskDISABLE_INTERRUPTS();
    for( ; ; ) { }
}

void vApplicationMallocFailedHook( void )
{
    taskDISABLE_INTERRUPTS();
    for( ; ; ) { }
}

/* Called from HardFault_Handler with the exception stack frame. */
void hardfault_c( const uint32_t * frame )
{
    s_crash.magic = CRASH_MAGIC;
    s_crash.pc = frame[ 6 ];
    s_crash.lr = frame[ 5 ];
    s_crash.psr = frame[ 7 ];
    s_crash.cfsr = SCB->CFSR;
    s_crash.bfar = SCB->BFAR;
    s_crash.uptime_s = xTaskGetTickCountFromISR() / configTICK_RATE_HZ;
    crash_save_task();
    NVIC_SystemReset();
}

__attribute__( ( naked ) ) void HardFault_Handler( void )
{
    __asm volatile (
        "tst lr, #4      \n"
        "ite eq          \n"
        "mrseq r0, msp   \n"
        "mrsne r0, psp   \n"
        "b hardfault_c   \n" );
}

/* At boot: print the reset cause and any crash record, then clear it. */
void fault_report_boot( void )
{
    char msg[ 160 ];
    uint32_t cause = ll_rcc_reset_cause();

    if( cause & LL_RESET_IWDG )
    {
        console_write( "reset: watchdog\r\n" );
    }
    if( s_crash.magic == CRASH_MAGIC )
    {
        snprintf( msg, sizeof msg,
                  "reset: hardfault pc=0x%08lx lr=0x%08lx psr=0x%08lx cfsr=0x%08lx bfar=0x%08lx task=%s up=%lus\r\n",
                  ( unsigned long ) s_crash.pc, ( unsigned long ) s_crash.lr, ( unsigned long ) s_crash.psr,
                  ( unsigned long ) s_crash.cfsr, ( unsigned long ) s_crash.bfar, s_crash.task,
                  ( unsigned long ) s_crash.uptime_s );
        console_write( msg );
    }
    memset( &s_crash, 0, sizeof s_crash );
    ll_rcc_clear_reset_cause();
}

