--- app/uplink.c ---
/*
 * uplink.c - sends summaries and a periodic status message through the radio
 * module (AT commands on UART2, 115200 8N1).
 *
 *   AT+SEND=<hex>\r\n    unconfirmed: module answers +TXDONE after the
 *                        transmission (time on air about 170 ms)
 *   AT+CSEND=<hex>\r\n   confirmed: module answers +ACK or +NOACK after its
 *                        receive windows (1 to 2.2 s after the transmission)
 */
#include <stdio.h>
#include <string.h>

#include "FreeRTOS.h"
#include "queue.h"
#include "task.h"

#include "app.h"
#include "board.h"
#include "mcu_ll.h"

#define UPLINK_QUEUE_LEN    2u
#define STATUS_PERIOD       pdMS_TO_TICKS( 15u * 60u * 1000u )     /* every 15 min */
#define RADIO_WAKE_MS       10u
#define RADIO_TXDONE_MS     1000u
#define RADIO_ACK_MS        3000u
#define RADIO_LINE_MAX      48u

static QueueHandle_t s_uplink_q;

/* Filled by the radio UART interrupt, one line at a time. */
static char s_rx_line[ RADIO_LINE_MAX ];
static volatile uint32_t s_rx_len;
static volatile bool s_rx_ready;

void UART2_IRQHandler( void )
{
    while( ll_uart_rx_ready( UART2 ) )
    {
        char c = ll_uart_getc( UART2 );

        if( s_rx_ready ) { continue; }                  /* previous line not read yet */
        if( c == '\n' )
        {
            s_rx_line[ s_rx_len ] = '\0';
            s_rx_ready = true;
        }
        else if( ( c != '\r' ) && ( s_rx_len < ( RADIO_LINE_MAX - 1u ) ) )
        {
            s_rx_line[ s_rx_len++ ] = c;
        }
    }
}

static void radio_puts( const char * s )
{
    while( *s != '\0' ) { board_radio_putc( *s++ ); }
}

static int radio_wait_reply( const char * ok, uint32_t timeout_ms )
{
    TickType_t t0 = xTaskGetTickCount();
    int rc = -1;

    while( ( xTaskGetTickCount() - t0 ) < pdMS_TO_TICKS( timeout_ms ) )
    {
        if( s_rx_ready )
        {
            rc = ( strcmp( s_rx_line, ok ) == 0 ) ? 0 : -2;
            s_rx_len = 0u;
            s_rx_ready = false;
            break;
        }
    }
    return rc;
}

static int radio_send( const uint8_t * data, uint32_t len, bool confirmed )
{
    char hex[ 3 ];

    board_radio_wake();
    vTaskDelay( pdMS_TO_TICKS( RADIO_WAKE_MS ) );       /* module ready 10 ms after WAKE */

    s_rx_len = 0u;
    s_rx_ready = false;
    radio_puts( confirmed ? "AT+CSEND=" : "AT+SEND=" );
    for( uint32_t i = 0; i < len; i++ )
    {
        snprintf( hex, sizeof hex, "%02X", data[ i ] );
        radio_puts( hex );
    }
    radio_puts( "\r\n" );

    return confirmed ? radio_wait_reply( "+ACK", RADIO_ACK_MS )
                     : radio_wait_reply( "+TXDONE", RADIO_TXDONE_MS );
}

static void send_summary( const struct summary * s )
{
    uint8_t p[ 16 ];

    p[ 0 ] = 0x01u;                                     /* message type: summary */
    p[ 1 ] = ( uint8_t ) s->seq;
    p[ 2 ] = s->alarm ? 1u : 0u;
    p[ 3 ] = s->afe_gain;
    uint16_t rms = ( uint16_t ) s->rms_mg, pk = ( uint16_t ) s->peak_mg;
    memcpy( &p[ 4 ], &rms, 2 );
    memcpy( &p[ 6 ], &pk, 2 );
    memcpy( &p[ 8 ], &s->temp_c10, 2 );
    memcpy( &p[ 10 ], &s->rh_pct10, 2 );
    memset( &p[ 12 ], 0, 4 );

    ( void ) radio_send( p, sizeof p, s->alarm );       /* alarms are confirmed */
}

static void send_status( void )
{
    uint8_t p[ 8 ] = { 0x02u };                         /* message type: status */
    uint32_t up = xTaskGetTickCount() / configTICK_RATE_HZ;

    memcpy( &p[ 1 ], &up, 4 );
    ( void ) radio_send( p, sizeof p, false );
}

static void uplink_task( void * arg )
{
    struct summary s;
    TickType_t next_status = xTaskGetTickCount() + STATUS_PERIOD;

    ( void ) arg;

    for( ; ; )
    {
        if( xQueueReceive( s_uplink_q, &s, pdMS_TO_TICKS( 100 ) ) == pdPASS )
        {
            send_summary( &s );
        }

        if( xTaskGetTickCount() >= next_status )
        {
            send_status();
            next_status += STATUS_PERIOD;
        }
    }
}

void uplink_start( UBaseType_t prio, uint16_t stack_words )
{
    s_uplink_q = xQueueCreate( UPLINK_QUEUE_LEN, sizeof( struct summary ) );
    configASSERT( s_uplink_q != NULL );

    BaseType_t ok = xTaskCreate( uplink_task, "uplink", stack_words, NULL, prio, NULL );
    configASSERT( ok == pdPASS );
    ( void ) ok;
}

void uplink_post( const struct summary * s )
{
    ( void ) xQueueSend( s_uplink_q, s, 0 );
}

