use std::fmt;

pub struct Tags(pub Vec<String>);

impl fmt::Display for Tags {
    // Each tag gets a leading '#', tags are separated by one space:
    // ["rust", "cli"] prints "#rust #cli". No tags prints nothing.
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        let mut first = true;
        for tag in &self.0 {
            if !first {
                write!(f, " ")?;
            }
            first = false;
            write!(f, "#{}", tag)?;
        }
        Ok(())
    }
}

impl From<Vec<&str>> for Tags {
    // So that Tags::from(vec!["rust", "cli"]) and
    // `let t: Tags = vec!["a"].into();` both work.
    fn from(words: Vec<&str>) -> Tags {
        Tags(words.into_iter().map(String::from).collect())
    }
}

fn main() {
    let tags = Tags(vec![String::from("rust"), String::from("cli")]);
    println!("[{tags}]");
    let more: Tags = vec!["a", "b", "c"].into();
    println!("[{more}]");
}
