/* main.c - telemetryd: two ADC channels to a telemetry file, events over UDP */
#include <pthread.h>
#include <signal.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include "config.h"
#include "msgpool.h"
#include "stats.h"
#include "telemetryd.h"

volatile bool g_stop;

static struct ring s_ring[TLM_CHANNELS];
static struct writer s_writer;
static struct capture s_capture[TLM_CHANNELS];

static void on_signal(int sig)
{
	(void)sig;
	g_stop = true;
}

static void start(pthread_t *t, void *(*fn)(void *), void *arg, const char *name)
{
	int err = pthread_create(t, NULL, fn, arg);

	if (err != 0) {
		fprintf(stderr, "telemetryd: %s: %s\n", name, strerror(err));
		exit(EXIT_FAILURE);
	}
}

int main(void)
{
	struct sigaction sa;
	struct ring *rings[TLM_CHANNELS];
	pthread_t cap[TLM_CHANNELS], wr, up, st;

	memset(&sa, 0, sizeof(sa));
	sa.sa_handler = on_signal;
	sigaction(SIGTERM, &sa, NULL);
	sigaction(SIGINT, &sa, NULL);

	msgpool_init();
	for (unsigned ch = 0; ch < TLM_CHANNELS; ch++) {
		ring_init(&s_ring[ch]);
		rings[ch] = &s_ring[ch];
		s_writer.ring[ch] = &s_ring[ch];
		s_capture[ch] = (struct capture){ .channel = ch, .ring = &s_ring[ch] };
	}

	start(&up, uplink_thread, NULL, "uplink");
	start(&wr, writer_thread, &s_writer, "writer");
	for (unsigned ch = 0; ch < TLM_CHANNELS; ch++)
		start(&cap[ch], capture_thread, &s_capture[ch], "capture");
	start(&st, status_thread, rings, "status");

	for (unsigned ch = 0; ch < TLM_CHANNELS; ch++)
		pthread_join(cap[ch], NULL);
	pthread_join(st, NULL);
	pthread_join(wr, NULL);
	pthread_join(up, NULL);
	return 0;
}

--- src/msgpool.c ---
/*
 * msgpool.c - lock-free free list of uplink message buffers.
 *
 * Buffers are taken by the capture threads (over-range events) and by the
 * status thread, and given back by the uplink thread once sent. A capture
 * thread must never block, so the free list is a lock-free stack: one CAS on
 * the top pointer to take a buffer, one to give it back.
 */
#include <stdatomic.h>
#include <stddef.h>

#include "msgpool.h"

static struct msg s_msgs[MSG_POOL_SIZE];
static _Atomic(struct msg *) s_free;

void msgpool_init(void)
{
	atomic_init(&s_free, NULL);
	for (size_t i = 0; i < MSG_POOL_SIZE; i++)
		msgpool_put(&s_msgs[i]);
}

struct msg *msgpool_get(void)
{
	struct msg *m = atomic_load_explicit(&s_free, memory_order_acquire);

	while (m != NULL &&
	       !atomic_compare_exchange_weak_explicit(&s_free, &m, m->next,
						      memory_order_acquire,
						      memory_order_acquire))
		;	/* m now holds the current top: try again */
	return m;
}

void msgpool_put(struct msg *m)
{
	struct msg *top = atomic_load_explicit(&s_free, memory_order_relaxed);

	do {
		m->next = top;
	} while (!atomic_compare_exchange_weak_explicit(&s_free, &top, m,
							 memory_order_release,
							 memory_order_relaxed));
}

