/* telemetryd.h - threads of the telemetry daemon and what they share */
#ifndef TELEMETRYD_H
#define TELEMETRYD_H

#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>

#include "record.h"
#include "ring.h"

#define TLM_CHANNELS	2
#define WRITER_BATCH	64		/* records per write(2) */

/* What one read(2) of an ADC channel device returns. */
struct adc_frame {
	uint64_t t_ns;
	uint32_t flags;
	int16_t  samples[TLM_REC_SAMPLES];
};

/* Set by the SIGTERM/SIGINT handler, polled by every thread's loop. */
extern volatile bool g_stop;

/* capture.c: one thread per channel */
struct capture {
	unsigned	channel;
	int		fd;
	struct ring	*ring;
	uint32_t	seq;
};
bool capture_emit(struct capture *c, const struct adc_frame *f);	/* false: ring full */
void *capture_thread(void *arg);

/* writer.c: drains both rings into the telemetry file */
struct writer {
	struct ring	*ring[TLM_CHANNELS];
	int		fd;
	size_t		len;
	unsigned char	buf[WRITER_BATCH * sizeof(struct tlm_rec)];
};
size_t writer_drain(struct writer *w);
void writer_flush(struct writer *w);
void *writer_thread(void *arg);

/* uplink.c: sends event messages over UDP */
