/// Returns the middle value of `items` after sorting them.
/// For an even count, returns the mean of the two middle values.
pub fn median(items: &mut [i32]) -> f64 {
    assert!(!items.is_empty(), "median of empty slice");
    items.sort();
    let mid = items.len() / 2;
    if items.len() % 2 == 1 {
        items[mid] as f64
    } else {
        (items[mid - 1] as f64 + items[mid] as f64) / 2.0
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn odd_count() {
        let mut items = [3, 1, 2];
        assert_eq!(median(&mut items), 2.0);
    }

    #[test]
    fn even_count() {
        let mut items = [4, 1, 2, 3];
        assert_eq!(median(&mut items), 2.5);
    }

    #[test]
    fn single_item() {
        let mut items = [7];
        assert_eq!(median(&mut items), 7.0);
    }

    #[test]
    #[should_panic(expected = "median of empty slice")]
    fn empty_slice_panics() {
        let mut items: [i32; 0] = [];
        median(&mut items);
    }
}

