const cache = new Map<string, Promise<Item[]>>();

export function searchCached(
  query: string,
  inStockOnly: boolean,
  signal?: AbortSignal
) {
  if (!cache.has(query)) {
    cache.set(query, searchProducts(query, inStockOnly, signal).then((r) => r.items));
