// Reference solution for exercise 2 (never shown to the learner).
// Run runs the tests: rustc --edition 2024 --test -o main ex2_scale.rs && ./main
//
// scale: multiply every value in the slice by `factor`, in place.
// sum_between: the sum of values[start..end], but never panic:
//   an `end` past the length counts as the length, and if start >= end the sum is 0.
//   Build the clamped range first, then sum the sub-slice `&values[start..end]`.

fn scale(values: &mut [i32], factor: i32) {
    for v in values {
        *v *= factor;
    }
}

fn sum_between(values: &[i32], start: usize, end: usize) -> i32 {
    let end = if end > values.len() { values.len() } else { end };
    if start >= end {
        return 0;
    }
    let mut total = 0;
    for v in &values[start..end] {
        total += v;
    }
    total
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn scales_a_whole_array() {
        let mut data = [1, -2, 3];
        scale(&mut data, 10);
        assert_eq!(data, [10, -20, 30]);
    }

    #[test]
    fn scales_only_part_of_a_vector() {
        let mut v = vec![1, 2, 3, 4];
        scale(&mut v[2..], 2);
        assert_eq!(v, [1, 2, 6, 8]);
    }

    #[test]
    fn sums_a_range() {
        let data = [4, 8, 15, 16, 23, 42];
        assert_eq!(sum_between(&data, 1, 4), 39);
        assert_eq!(sum_between(&data, 0, 6), 108);
    }

    #[test]
    fn never_panics() {
        let data = [4, 8, 15];
        assert_eq!(sum_between(&data, 1, 99), 23);
        assert_eq!(sum_between(&data, 2, 1), 0);
        assert_eq!(sum_between(&data, 5, 9), 0);
        assert_eq!(sum_between(&[], 0, 3), 0);
    }
}


