/// Sum of the `n` largest values in `items`, as an `i64`, so it never overflows.
/// Equal values count separately. If `n` is larger than `items.len()`, every
/// item is summed; `n = 0` gives 0. The caller's slice is not changed.
pub fn top_sum(items: &[i32], n: usize) -> i64 {
    let mut sorted = items.to_vec();
    sorted.sort_unstable_by(|a, b| b.cmp(a));
    sorted.iter().take(n).map(|&x| x as i64).sum()
}

/// Panics if `f` breaks any promise in `top_sum`'s doc comment;
/// returns normally for a correct implementation.
pub fn check_top_sum(f: fn(&[i32], usize) -> i64) {
    // Basic cases.
    assert_eq!(f(&[], 0), 0);
    assert_eq!(f(&[], 3), 0);
    assert_eq!(f(&[5], 0), 0);
    assert_eq!(f(&[5], 1), 5);
    assert_eq!(f(&[5], 10), 5);

    // Largest values, not first values.
    assert_eq!(f(&[1, 9, 3, 7], 1), 9);
    assert_eq!(f(&[1, 9, 3, 7], 2), 16);
    assert_eq!(f(&[1, 9, 3, 7], 3), 19);
    assert_eq!(f(&[1, 9, 3, 7], 4), 20);
    assert_eq!(f(&[1, 9, 3, 7], 8), 20);

    // Equal values count separately.
    assert_eq!(f(&[4, 4, 1], 1), 4);
    assert_eq!(f(&[4, 4, 1], 2), 8);
    assert_eq!(f(&[4, 4, 1], 3), 9);

    // Negative values and mixed values.
    assert_eq!(f(&[-10, -2, -7], 1), -2);
    assert_eq!(f(&[-10, 5, 3, -2], 2), 8);
    assert_eq!(f(&[-10, 5, 3, -2], 10), -4);

    // The caller's slice is not changed.
    let items = [3, 1, 4, 1, 5, 9];
    let before = items;
    assert_eq!(f(&items, 3), 18);
    assert_eq!(items, before);

    // i64 accumulation should be used.
    let big = [i32::MAX, i32::MAX, i32::MAX];
    assert_eq!(f(&big, 3), 3 * i32::MAX as i64);
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn real_top_sum_passes_the_checks() {
        check_top_sum(top_sum);
    }
}

