pub fn parse_rgb(s: &str) -> Result<(u8, u8, u8), String> {
    let hex = s.strip_prefix('#').ok_or(format!("{s:?} does not start with '#'"))?;
    if hex.len() != 6 || !hex.bytes().all(|b| b.is_ascii_hexdigit()) {
        return Err(format!("{s:?} is not #rrggbb"));
    }
    let part = |i: usize| u8::from_str_radix(&hex[i..i + 2], 16).map_err(|e| e.to_string());
    Ok((part(0)?, part(2)?, part(4)?))
}

/// Panics if `f` breaks any promise in `parse_rgb`'s doc comment;
/// returns normally for a correct implementation.
pub fn check_parse_rgb(f: fn(&str) -> Result<(u8, u8, u8), String>) {
    assert_eq!(f("#ff8000"), Ok((255, 128, 0)), "lower case, and the channel order");
    assert_eq!(f("#FF8000"), Ok((255, 128, 0)), "upper case");
    assert_eq!(f("#000000"), Ok((0, 0, 0)));
    // Must be rejected: no '#', short form, wrong lengths, non-hex, signs,
    // non-ASCII (7 bytes, but not 6 hex digits), empty.
    for bad in ["ff8000", "#fff", "#ff800", "#ff80000", "#gg0000", "#+f+f+f", "#a€bc", "", "#"] {
        assert!(f(bad).is_err(), "{bad:?} must be rejected");
    }
}

