trait Shape {
    fn name(&self) -> String;
    fn area(&self) -> f64;

    fn rounded(&self) -> f64 {
        self.area().round()
    }

    fn summary(&self) -> String {
        format!("{} ~ {}", self.name(), self.rounded())
    }

    fn tag(&self) -> String {
        format!("<{}>", self.name())
    }
}

struct Square(f64);
struct Disc(f64);

impl Shape for Square {
    fn name(&self) -> String {
        String::from("square")
    }
    fn area(&self) -> f64 {
        self.0 * self.0
    }
}

impl Shape for Disc {
    fn name(&self) -> String {
        String::from("disc")
    }
    fn area(&self) -> f64 {
        3.0 * self.0 * self.0
    }
    fn rounded(&self) -> f64 {
        self.area().floor()
    }
}

fn report(item: &impl Shape) {
    println!("{}", item.summary());
}

fn main() {
    report(&Square(1.5));
    report(&Disc(1.5));
    println!("{}", Disc(1.5).area());
}

