// Write code: a wrapper that counts writes and reports them when dropped.
// Run: rustc --edition 2024 -o main p7.rs && ./main
// Submit runs hidden tests against Tracked.
//
// Fill in Deref, DerefMut and Drop so that:
//   * every method of the inner value works on a Tracked (t.len(), t.push(..));
//   * each time the value is reached through DerefMut, `writes` goes up by 1
//     (reads through Deref do not count);
//   * when a Tracked is dropped it pushes "<name>: <writes> writes" to its log.
use std::cell::RefCell;
use std::ops::{Deref, DerefMut};

/// A shared list of lines that values can push to through a plain `&Log`.
/// (RefCell inside; how that works is sub-module 17.)
pub struct Log(RefCell<Vec<String>>);

impl Log {
    pub fn new() -> Log {
        Log(RefCell::new(Vec::new()))
    }
    pub fn push(&self, line: String) {
        self.0.borrow_mut().push(line);
    }
    pub fn lines(&self) -> Vec<String> {
        self.0.borrow().clone()
    }
}

/// (`'a`: a Tracked cannot outlive its log; lifetimes are 14.)
pub struct Tracked<'a, T> {
    name: &'static str,
    value: T,
    writes: u32,
    log: &'a Log,
}

impl<'a, T> Tracked<'a, T> {
    pub fn new(name: &'static str, value: T, log: &'a Log) -> Tracked<'a, T> {
        Tracked { name, value, writes: 0, log }
    }

    pub fn writes(&self) -> u32 {
        self.writes
    }
}

