import { useState, type CSSProperties, type ReactNode } from 'react';
import { useForm } from './FormProvider';
import { useRemoteValidation } from './useRemoteValidation';
import type { FieldSchema, FieldValue } from './types';

interface FieldProps {
  field: FieldSchema;
  value: FieldValue;
  onChange: (name: string, value: FieldValue) => void;
  style?: CSSProperties;
  children?: ReactNode;
}

export function Field({ field, value, onChange, style, children }: FieldProps) {
  const { errors } = useForm();
  const [text, setText] = useState(() => toText(value));
  useRemoteValidation(field, text);

  const id = `f-${field.name}`;
  const error = errors[field.name];

  if (field.type === 'checkbox') {
    return (
      <div className="field field-checkbox" style={style}>
        <input
          id={id}
          type="checkbox"
          checked={value === true}
          onChange={(e) => onChange(field.name, e.target.checked)}
        />
        <label htmlFor={id}>{field.label}</label>
        {children}
      </div>
    );
  }

  return (
    <div className="field" style={style}>
      <label htmlFor={id}>
        {field.label}
        {field.required && ' *'}
      </label>
      {field.type === 'select' ? (
        <select
          id={id}
          value={typeof value === 'string' ? value : ''}
          onChange={(e) => onChange(field.name, e.target.value)}
        >
          <option value="">Select...</option>
          {field.options?.map((option) => (
            <option key={option.value} value={option.value}>
              {option.label}
            </option>
          ))}
        </select>
      ) : (
        <input
          id={id}
          type={field.type === 'date' ? 'date' : 'text'}
          inputMode={field.type === 'number' ? 'decimal' : undefined}
          value={text}
          aria-invalid={error ? true : undefined}
          onChange={(e) => {
            setText(e.target.value);
            onChange(field.name, fromText(field, e.target.value));
          }}
        />
      )}
      {children}
      {error && (
        <p className="field-error" role="alert">
          {error}
        </p>
      )}
    </div>
  );
}

function toText(value: FieldValue): string {
  return value === undefined || typeof value === 'boolean' ? '' : value;
}

function fromText(field: FieldSchema, text: string): FieldValue {
  if (field.type === 'number') {
    const normalised = text.replace(/[,\s]/g, '');
    return normalised === '' ? undefined : normalised;
  }
  return text;
}

--- src/form/FormProvider.tsx ---
import { createContext, useContext, useState, type ReactNode } from 'react';
import type { FieldValue, FormErrors, FormSchema, FormValues } from './types';

interface FormContextValue {
  schema: FormSchema;
  values: FormValues;
  errors: FormErrors;
  setValue: (name: string, value: FieldValue) => void;
  setError: (name: string, message: string | undefined) => void;
}

const FormContext = createContext<FormContextValue | null>(null);

interface FormProviderProps {
  schema: FormSchema;
  initialValues?: FormValues;
  children: ReactNode;
}

export function FormProvider({ schema, initialValues = {}, children }: FormProviderProps) {
  const [values, setValues] = useState<FormValues>(initialValues);
  const [errors, setErrors] = useState<FormErrors>({});

  const setValue = (name: string, value: FieldValue) => {
    setValues((prev) => ({ ...prev, [name]: value }));
  };

  const setError = (name: string, message: string | undefined) => {
    setErrors((prev) => (prev[name] === message ? prev : { ...prev, [name]: message }));
  };

  return (
    <FormContext value={{ schema, values, errors, setValue, setError }}>
      {children}
    </FormContext>
  );
}

export function useForm(): FormContextValue {
  const ctx = useContext(FormContext);
  if (!ctx) {
    throw new Error('useForm must be used inside <FormProvider>');
  }
  return ctx;
}

