fn dedupe_adjacent(words: Vec<String>) -> Vec<String> {
    let mut out = Vec::new();
    for w in words {
        let keep = if out.len() == 0 {
            true
        } else {
            out[out.len() - 1] != w
        };
        if keep {
            out.push(w);
        }
    }
    out
}

fn main() {
    let words = vec![
        String::from("go"),
        String::from("go"),
        String::from("stop"),
        String::from("go"),
    ];
    println!("{:?}", dedupe_adjacent(words));
}
