// Implement `total_and_back`: return the total number of bytes in all the
// strings, and give the vector back to the caller so `main` can still use it.
// Rules: no clone() and no `&` (references are the next sub-module).
// Run prints one line. Submit checks your function against hidden tests,
// including that the vector you return is the same one you were given.

fn total_and_back(items: Vec<String>) -> (usize, Vec<String>) {
    let mut total = 0;
    for s in items.iter() {
        total += s.len();
    }
    (total, items)
}

fn main() {
    let items = vec![String::from("alpha"), String::from("beta")];
    let (total, items) = total_and_back(items);
    println!("{total} bytes in {} items", items.len());
}

