// Implement `dedupe_adjacent`: collapse each run of equal neighbouring words
// to one word, keeping the first of each run:
//   ["a", "a", "b", "a"]  ->  ["a", "b", "a"]
// Do not clone any String: move every word you keep into a new vector and let
// the duplicates drop. You need: `Vec::new()` for an empty vector, `out.push(w)`
// to move a word in, and `out.len()` / `out[i]` to look at what is there.
// Run prints one line. Submit checks your function against hidden tests,
// including that the kept words are the original strings, not copies.

fn dedupe_adjacent(words: Vec<String>) -> Vec<String> {
    let mut out: Vec<String> = Vec::new();
    // `for w in words` consumes the input: each word is moved into `w`.
    for w in words {
        if out.len() == 0 || out[out.len() - 1] != w {
            out.push(w); // moved into `out`: same heap buffer
        } // a duplicate `w` is dropped here, at the end of the iteration
    }
    out
}

fn main() {
