/// Parses a whole number, ignoring spaces around it.
///
/// ```
/// assert_eq!(numbers::parse(" 42 "), Some(42));
/// assert_eq!(numbers::parse("4 2"), Some(42));
/// ```
pub fn parse(text: &str) -> Option<i64> {
    let cleaned: String = text.chars().filter(|c| !c.is_whitespace()).collect();
    cleaned.parse().ok()
}

/// Adds up every item that parses; skips the rest.
pub fn total(items: &[&str]) -> i64 {
    items.iter().filter_map(|s| parse(s)).sum()
}

