fn digital_root(n: u64) -> (u64, u32) {
    let mut n = n;
    let mut rounds = 0;

    while n >= 10 {
        let mut sum = 0;
        let mut x = n;
        while x > 0 {
            sum += x % 10;
            x /= 10;
        }
        n = sum;
        rounds += 1;
    }

    (n, rounds)
}

