// Exercise 1: an enum with data, and match.
// Run: rustc --edition 2024 --test -o main ex1_commands.rs && ./main --test-threads=4
//
// A tiny robot understands three commands. Replace both todo!()s so the tests
// pass. Use one match arm per variant: no `_` arm.

enum Command {
    Move { dx: i32, dy: i32 },
    Say(String),
    Stop,
}

/// Where the robot is after the command. Only Move changes the position.
fn apply(pos: (i32, i32), cmd: &Command) -> (i32, i32) {
    match cmd {
        Command::Move { dx, dy } => (pos.0 + dx, pos.1 + dy),
        Command::Say(_) => pos,
        Command::Stop => pos,
    }
}

/// One line of text for the command:
/// Move -> "move 2,-1", Say -> "say: hi", Stop -> "stop".
fn describe(cmd: &Command) -> String {
    match cmd {
        Command::Move { dx, dy } => format!("move {dx},{dy}"),
        Command::Say(text) => format!("say: {text}"),
        Command::Stop => String::from("stop"),
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn move_changes_position() {
        let pos = apply((0, 0), &Command::Move { dx: 2, dy: -1 });
        assert_eq!(pos, (2, -1));
        assert_eq!(apply(pos, &Command::Move { dx: 1, dy: 1 }), (3, 0));
    }

    #[test]
    fn other_commands_keep_position() {
        assert_eq!(apply((5, 5), &Command::Say(String::from("hi"))), (5, 5));
        assert_eq!(apply((5, 5), &Command::Stop), (5, 5));
    }

    #[test]
    fn describes_each_command() {
        assert_eq!(describe(&Command::Move { dx: 2, dy: -1 }), "move 2,-1");
        assert_eq!(describe(&Command::Say(String::from("hi"))), "say: hi");
        assert_eq!(describe(&Command::Stop), "stop");
    }
}


