import { getJson } from "./http";

interface FieldBase {
  readonly name: string;
  readonly label: string;
  readonly required?: boolean;
  readonly helpText?: string;
}

export interface SelectOption {
  readonly value: string;
  readonly label: string;
}

export interface TextField extends FieldBase {
  readonly kind: "text";
  readonly placeholder?: string;
  readonly defaultValue?: string;
}

export interface NumberField extends FieldBase {
  readonly kind: "number";
  readonly min?: number;
  readonly max?: number;
  readonly step?: number;
  readonly defaultValue?: number;
}

export interface SelectField extends FieldBase {
  readonly kind: "select";
  readonly options: readonly SelectOption[];
  readonly placeholder?: string;
  readonly defaultValue?: string;
}

export interface MultiSelectField extends FieldBase {
  readonly kind: "multiselect";
  readonly optionsUrl: string;
}

export interface CheckboxField extends FieldBase {
  readonly kind: "checkbox";
  readonly defaultValue?: boolean;
}

export interface DateField extends FieldBase {
  readonly kind: "date";
  readonly defaultValue?: string;
}

export type FieldConfig = TextField | NumberField | SelectField | MultiSelectField | CheckboxField | DateField;

export interface FormConfig {
  readonly id: string;
  readonly version: number;
  readonly title: string;
  readonly submitUrl: string;
  readonly submitLabel?: string;
  readonly fields: readonly FieldConfig[];
}

export function isFormConfig(data: unknown): data is FormConfig {
  if (typeof data !== "object" || data === null) return false;
  const c = data as Record<string, unknown>;
  return (
    typeof c.id === "string" &&
    typeof c.submitUrl === "string" &&
    Array.isArray(c.fields) &&
    c.fields.every((f) => typeof f === "object" && f !== null && "name" in f && "kind" in f)
  );
}

export async function loadFormConfig(formId: string): Promise<FormConfig> {
  const data: unknown = await getJson(`/api/forms/${encodeURIComponent(formId)}`);
  if (!isFormConfig(data)) throw new Error(`Form config ${formId} has an unexpected shape`);
  return data;
}

export function assertNever(value: never): never {
  throw new Error(`Unhandled field: ${JSON.stringify(value)}`);
}


