/*
 * test_mm.c - host unit tests for the arena allocator. Built and run by
 * test/Makefile with clang -fsanitize=address. These are the tests
 * whose output is in test_mm.out.
 */
#include "mm.h"
#include "mm_internal.h"   /* white-box host test: needs the full mm_t */

#include <stdio.h>
#include <stdint.h>
#include <string.h>

static mm_t g_mm;
static int  g_fail;

#define CHECK(cond, msg) do {                                      \
    if (!(cond)) { printf("  FAIL: %s\n", (msg)); g_fail++; }      \
    else         { printf("  ok:   %s\n", (msg)); }                \
} while (0)

/* T1: one alloc then free returns the block to its class. */
static void t1_alloc_free(void) {
    printf("[T1] alloc 16B, write it, free it\n");
    mm_init(&g_mm);
    size_t before = mm_class_free_bytes(&g_mm, 16);

    void *p = NULL;
    int rc = mm_alloc(&g_mm, 16, &p);
    CHECK(rc == MM_OK && p != NULL, "mm_alloc returns a block");

    uint32_t *w = (uint32_t *)p;
    w[0] = 0xDEADBEEFu;
    CHECK(w[0] == 0xDEADBEEFu, "payload holds a 32-bit word");

    mm_free(&g_mm, &p);
    CHECK(p == NULL, "mm_free NULLs the caller pointer");

    size_t after = mm_class_free_bytes(&g_mm, 16);
    CHECK(after == before, "freed block is back in its class");
}

/* T2: fill the 16B class, then allocations fail with ENOMEM, not a crash. */
static void t2_exhaust(void) {
    printf("[T2] exhaust the 16B class\n");
    mm_init(&g_mm);
    int n = 0;
    void *p = NULL;
    while (mm_alloc(&g_mm, 16, &p) == MM_OK) {
        n++;
    }
    CHECK(n > 0, "got at least one block before ENOMEM");
    CHECK(mm_alloc(&g_mm, 16, &p) == MM_ENOMEM, "empty class returns ENOMEM");
}

/* T3: three live blocks do not overlap. */
static void t3_distinct(void) {
    printf("[T3] three 32B blocks are distinct\n");
    mm_init(&g_mm);
    void *a = NULL, *b = NULL, *c = NULL;
    mm_alloc(&g_mm, 32, &a);
    mm_alloc(&g_mm, 32, &b);
    mm_alloc(&g_mm, 32, &c);
    CHECK(a && b && c, "three allocations succeeded");
    memset(a, 0xAA, 32);
    memset(b, 0xBB, 32);
    memset(c, 0xCC, 32);
    CHECK(((uint8_t *)a)[0] == 0xAA && ((uint8_t *)b)[0] == 0xBB &&
          ((uint8_t *)c)[0] == 0xCC, "no two blocks overlap");
}

int main(void) {
    setvbuf(stdout, NULL, _IONBF, 0);   /* keep output in order with ASan reports */
    t1_alloc_free();
    t2_exhaust();
    t3_distinct();
    printf("\n%s (%d failures)\n", g_fail ? "TESTS FAILED" : "ALL PASS", g_fail);
    return g_fail ? 1 : 0;
}

