  version: number;
  rows: Row[];
}

export async function fetchRows(): Promise<RowsResponse> {
  const res = await fetch("/api/rows", { credentials: "include" });
  if (!res.ok) throw new Error(`rows failed: ${res.status}`);
  return res.json();
}

