// 1. The price of `name` in `prices`, or None.
fn price_of(prices: &[(&str, u32)], name: &str) -> Option<u32> {
    for (n, price) in prices {
        if *n == name {
            return Some(*price);
        }
    }
    None
}

// 2. Parse a quantity like "3". On failure: Err("bad quantity \"<text>\": <parse error>").
//    e.g. parse_qty("x") == Err("bad quantity \"x\": invalid digit found in string")
fn parse_qty(text: &str) -> Result<u32, String> {
    text.parse::<u32>().map_err(|e| format!("bad quantity {:?}: {}", text, e))
}

// 3. Each order line is "<name> x<qty>", e.g. "tea x3". Return the total price.
//    Errors (first one wins):
//      no " x" in the line      -> Err("no quantity in \"<line>\"")
//      unknown name             -> Err("unknown item \"<name>\"")
//      bad quantity             -> the error from parse_qty
//    Use ? for every step.
fn order_total(prices: &[(&str, u32)], lines: &[&str]) -> Result<u32, String> {
    let mut total = 0;
    for line in lines {
        let (name, qty_text) = line
            .split_once(" x")
            .ok_or_else(|| format!("no quantity in {:?}", line))?;
        let qty = parse_qty(qty_text)?;
        let price = price_of(prices, name).ok_or_else(|| format!("unknown item {:?}", name))?;
        total += price * qty;
    }
    Ok(total)
}

