fn dedupe_adjacent(words: Vec<String>) -> Vec<String> {
    let mut out: Vec<String> = Vec::new();

    for w in words {
        let should_keep = if out.len() == 0 {
            true
        } else {
            out[out.len() - 1] != w
        };

        if should_keep {
            out.push(w);
        }
