/// Returns the middle value of `items` after sorting them.
/// For an even count, returns the mean of the two middle values.
pub fn median(items: &mut [i32]) -> Option<f64> {
    if items.is_empty() {
        return None;
    }

    items.sort();
    let mid = items.len() / 2;

    if items.len() % 2 == 1 {
        Some(items[mid] as f64)
    } else {
        Some((items[mid - 1] as f64 + items[mid] as f64) / 2.0)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn odd_count() {
        let mut items = [3, 1, 2];
        assert_eq!(median(&mut items), Some(2.0));
    }

    #[test]
    fn even_count() {
        let mut items = [4, 1, 2, 3];
        assert_eq!(median(&mut items), Some(2.5));
    }

    #[test]
    fn single_item() {
        let mut items = [7];
        assert_eq!(median(&mut items), Some(7.0));
    }

    #[test]
    fn empty_slice() {
        let mut items: [i32; 0] = [];
        assert_eq!(median(&mut items), None);
    }
}
