// src/lib.rs
/// Counts the distinct words in `text`, ignoring case and punctuation.
pub fn distinct_words(text: &str) -> usize {
    let mut words: Vec<String> = text.split_whitespace().map(normalize).collect();
    words.sort();
    words.dedup();
    words.len()
}

fn normalize(word: &str) -> String {
    word.trim_matches(|c: char| !c.is_alphanumeric()).to_lowercase()
}

pub fn sample_text() -> &'static str {
    "One two, TWO one."
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn normalize_strips_and_lowers() {
        assert_eq!(normalize("Two,"), "two");
    }

    #[test]
    fn sample_has_two_words() {
        assert_eq!(distinct_words(sample_text()), 2);
    }
}

