pub struct Grid {
    cells: Vec<u8>,
    width: usize,
    height: usize,
}

impl Grid {
    pub fn new(width: usize, height: usize) -> Grid {
        Grid {
            cells: vec![0; width * height],
            width,
            height,
        }
    }

    pub fn get(&self, x: usize, y: usize) -> u8 {
        if x >= self.width {
            panic!("x out of range: {x}");
        }
        if y >= self.height {
            panic!("y out of range: {y}");
        }
        self.cells[y * self.width + x]
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    #[should_panic]
    fn rejects_x_past_the_edge() {
        let grid = Grid::new(2, 2);
        grid.get(2, 1);
    }

    #[test]
    #[should_panic]
    fn rejects_y_past_the_edge() {
        let grid = Grid::new(2, 2);
        grid.get(1, 2);
    }

    #[test]
    fn allows_last_valid_cell() {
        let grid = Grid::new(2, 2);
        assert_eq!(grid.get(1, 1), 0);
    }
}
