use std::fs;
use std::io;
use std::path::Path;

pub fn save(path: &Path, items: &[&str]) -> io::Result<()> {
    fs::write(path, items.join("\n"))
}

pub fn load(path: &Path) -> io::Result<Vec<String>> {
    Ok(fs::read_to_string(path)?.lines().map(String::from).collect())
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::{env, thread, time::Duration};

    fn scratch_file(name: &str) -> std::path::PathBuf {
        env::temp_dir().join(format!("store_test_{name}_{}.txt", std::process::id()))
    }

    #[test]
    fn round_trip_one() {
        let path = scratch_file("one");
        save(&path, &["a"]).unwrap();
        thread::sleep(Duration::from_millis(20)); // stands in for slower work
        assert_eq!(load(&path).unwrap(), vec!["a"]);
        let _ = fs::remove_file(&path);
    }

    #[test]
    fn round_trip_three() {
        let path = scratch_file("three");
        save(&path, &["x", "y", "z"]).unwrap();
        thread::sleep(Duration::from_millis(20));
        assert_eq!(load(&path).unwrap(), vec!["x", "y", "z"]);
        let _ = fs::remove_file(&path);
    }
}

