--- src/buf_pool.c ---
/* buf_pool.c: fixed pool of buffers, so nothing is malloc'd after start-up. */
#include <stdlib.h>

#include "buf_pool.h"
#include "log.h"

int pool_init(struct buf_pool *p)
{
	int err, i;

	p->bufs = calloc(GW_POOL_BUFS, sizeof(*p->bufs));
	if (p->bufs == NULL)
		return -1;
	for (i = 0; i < GW_POOL_BUFS; i++) {
		p->bufs[i].id = i;
		p->free_ring[i] = i;
	}
	p->head = p->tail = 0;
	p->nfree = p->min_free = GW_POOL_BUFS;
	p->waits = 0;
	err = pthread_mutex_init(&p->lock, NULL);
	if (err == 0)
		err = pthread_cond_init(&p->avail, NULL);
	return err;
}

struct gw_buf *pool_get(struct buf_pool *p)
{
	struct gw_buf *b;

	pthread_mutex_lock(&p->lock);
	if (p->nfree == 0) {
		p->waits++;
		thr_set_state("pool_get wait");
		pthread_cond_wait(&p->avail, &p->lock);
		thr_set_state("run");
	}
	b = &p->bufs[p->free_ring[p->head]];
	p->head = (p->head + 1) % GW_POOL_BUFS;
	p->nfree--;
	if (p->nfree < p->min_free)
		p->min_free = p->nfree;
	pthread_mutex_unlock(&p->lock);

	b->len = 0;
	return b;
}

void pool_put(struct buf_pool *p, struct gw_buf *b)
{
	pthread_mutex_lock(&p->lock);
	p->free_ring[p->tail] = b->id;
	p->tail = (p->tail + 1) % GW_POOL_BUFS;
	p->nfree++;
	pthread_cond_signal(&p->avail);
	pthread_mutex_unlock(&p->lock);
}

void pool_stats(struct buf_pool *p, struct pool_stats *st)
{
	pthread_mutex_lock(&p->lock);
	st->nfree = p->nfree;
	st->min_free = p->min_free;
	st->waits = p->waits;
	p->min_free = p->nfree;
	pthread_mutex_unlock(&p->lock);
}

--- src/buf_pool.h ---
/* buf_pool.h: fixed pool of GW_POOL_BUFS buffers, allocated once at start. */
#ifndef BUF_POOL_H
#define BUF_POOL_H

#include <pthread.h>

#include "gw.h"

struct buf_pool {
	pthread_mutex_t  lock;
	pthread_cond_t   avail;                    /* a buffer was returned */
	struct gw_buf   *bufs;                     /* GW_POOL_BUFS of them */
	int              free_ring[GW_POOL_BUFS];  /* ids of free buffers, FIFO */
	unsigned         head;                     /* next id to hand out */
	unsigned         tail;                     /* where the next returned id goes */
	int              nfree;
	/* stats, under lock */
	int              min_free;                 /* low-water mark since last stats */
	unsigned long    waits;
};

struct pool_stats {
	int           nfree;
	int           min_free;
	unsigned long waits;
};

int            pool_init(struct buf_pool *p);
/* Takes a free buffer, blocking until one is returned if none is free.
 * Used by the acquisition thread (one per frame) and by the workers
 * (one per upload, for the encoded body). */
struct gw_buf *pool_get(struct buf_pool *p);
void           pool_put(struct buf_pool *p, struct gw_buf *b);
/* Copies the counters and starts a new low-water mark. */
void           pool_stats(struct buf_pool *p, struct pool_stats *st);

#endif

--- src/config.h ---
/* config.h: build-time sizing for sensor-gw. */
#ifndef GW_CONFIG_H
#define GW_CONFIG_H

#define GW_VERSION            "1.4.0"

/* Sampling: the hub sends one frame of 100 samples (3 axes, int16) every 100 ms. */
#define GW_SAMPLES_PER_FRAME  100
#define GW_AXES               3

/* Threads */
#define GW_N_WORKERS          4

/* Frames waiting for a worker. Kept short on purpose: when the workers fall
 * behind, acquisition blocks and the hub's own FIFO (4 frames) absorbs it. */
#define GW_QUEUE_DEPTH        2

/* Buffers for raw frames and encoded uploads. Every worker can hold a raw
 * frame while one more encodes: N_WORKERS + QUEUE_DEPTH + 2 = 8. */
#define GW_POOL_BUFS          8
#define GW_BUF_SIZE           2048

/* The collector accepts at most 2 concurrent uploads per device (429 beyond). */
#define GW_UPLINK_SLOTS       2
#define GW_HTTP_TIMEOUT_S     10
#define GW_BACKOFF_MAX_S      60

/* Watchdog: dump thread and queue state if nothing was uploaded for this long. */
#define GW_STALL_S            30
#define GW_STATS_EVERY_S      10

/* Stop: how long main waits for each worker before it logs a state dump. */
#define GW_JOIN_WARN_S        5

#endif

--- src/gw.h ---
/* gw.h: types shared by the acquisition thread, the workers and main. */
#ifndef GW_H
#define GW_H

#include <stddef.h>
#include <stdint.h>

#include "config.h"

struct gw_buf {
	int      id;                 /* index in the pool, fixed */
	size_t   len;                /* bytes used in data[] */
	uint8_t  data[GW_BUF_SIZE];
};

/* A frame as the hub sends it (little-endian; both ends are little-endian). */
struct hub_frame_hdr {
	uint16_t magic;              /* HUB_MAGIC */
	uint16_t nsamples;
	uint32_t seq;                /* +1 per frame, never reset while the hub runs */
	uint32_t t0_ms;              /* hub clock at the first sample */
	uint16_t lost;               /* frames dropped by the hub since the previous one */
	uint16_t rsvd;
};

#define HUB_MAGIC       0x5AA5u
#define HUB_FRAME_SIZE  (sizeof(struct hub_frame_hdr) + \
                         GW_SAMPLES_PER_FRAME * GW_AXES * sizeof(int16_t))

struct ring_queue;
struct buf_pool;
struct uplink;

struct gw {
	struct ring_queue *q;
	struct buf_pool   *pool;
	struct uplink     *up;
};

#endif

--- src/http.c ---
/* http.c: minimal blocking HTTP/1.1 POST over TCP, one connection per request. */
#include <errno.h>
#include <netdb.h>
#include <poll.h>
#include <stdio.h>
#include <string.h>
#include <sys/socket.h>
#include <sys/time.h>
#include <unistd.h>

#include "http.h"

static int connect_to(const char *host, const char *port, int timeout_s)
{
	struct addrinfo hints = { .ai_family = AF_UNSPEC, .ai_socktype = SOCK_STREAM };
	struct addrinfo *res, *ai;
	struct timeval tv = { .tv_sec = timeout_s };
	int fd = -1;

	if (getaddrinfo(host, port, &hints, &res) != 0)
		return -1;
	for (ai = res; ai != NULL; ai = ai->ai_next) {
		fd = socket(ai->ai_family, ai->ai_socktype, ai->ai_protocol);
		if (fd < 0)
			continue;
		setsockopt(fd, SOL_SOCKET, SO_RCVTIMEO, &tv, sizeof(tv));
		setsockopt(fd, SOL_SOCKET, SO_SNDTIMEO, &tv, sizeof(tv));
		if (connect(fd, ai->ai_addr, ai->ai_addrlen) == 0)
			break;
		if (errno == EINTR) {
			/* the connection goes on in the background: wait for it */
			struct pollfd pfd = { .fd = fd, .events = POLLOUT };
			int soerr = 0;
			socklen_t sl = sizeof(soerr);

			while (poll(&pfd, 1, timeout_s * 1000) < 0 && errno == EINTR)
				;
			getsockopt(fd, SOL_SOCKET, SO_ERROR, &soerr, &sl);
			if ((pfd.revents & POLLOUT) && soerr == 0)
				break;
		}
		close(fd);
		fd = -1;
	}
	freeaddrinfo(res);
	return fd;
}

static int send_all(int fd, const void *buf, size_t len)
{
	const char *p = buf;

	while (len > 0) {
		ssize_t n = send(fd, p, len, MSG_NOSIGNAL);

		if (n < 0) {
			if (errno == EINTR)
				continue;
			return -1;
		}
		p += n;
		len -= (size_t)n;
	}
	return 0;
}

int http_post(const char *host, const char *port, const char *path,
	      const char *device, const uint8_t *body, size_t len, int timeout_s)
{
	char hdr[256], resp[128];
	size_t got = 0;
	int fd, n, status = -1;

	fd = connect_to(host, port, timeout_s);
	if (fd < 0)
		return -1;

	n = snprintf(hdr, sizeof(hdr),
		     "POST %s HTTP/1.1\r\n"
		     "Host: %s\r\n"
		     "X-Device-Id: %s\r\n"
		     "Content-Type: application/octet-stream\r\n"
		     "Content-Length: %zu\r\n"
		     "Connection: close\r\n\r\n", path, host, device, len);
	if (send_all(fd, hdr, (size_t)n) != 0 || send_all(fd, body, len) != 0)
		goto out;

	/* Only the status line matters: "HTTP/1.1 201 Created" */
	while (got < sizeof(resp) - 1 && memchr(resp, '\n', got) == NULL) {
		ssize_t r = recv(fd, resp + got, sizeof(resp) - 1 - got, 0);

		if (r < 0 && errno == EINTR)
			continue;
		if (r <= 0)
			break;
		got += (size_t)r;
	}
	resp[got] = '\0';
	if (sscanf(resp, "HTTP/1.%*d %d", &status) != 1)
		status = -1;
out:
	close(fd);
	return status;
}

