/* log.c: line logger (one mutex around the FILE) and the thread table. */
#include <pthread.h>
#include <stdarg.h>
#include <stdio.h>
#include <string.h>
#include <time.h>
#include <unistd.h>

#include "log.h"

bool g_log_verbose;

static pthread_mutex_t log_lock = PTHREAD_MUTEX_INITIALIZER;
static FILE *log_fp;
static const char *log_path;

struct thr_slot {
	char            name[16];
	pid_t           tid;
	const char     *state;
	struct timespec since;           /* CLOCK_MONOTONIC */
	bool            exited;
};

static pthread_mutex_t thr_lock = PTHREAD_MUTEX_INITIALIZER;
static struct thr_slot thr_table[THR_MAX];
static int thr_count;
static __thread struct thr_slot *thr_self;

int log_open(const char *path, bool verbose)
{
	g_log_verbose = verbose;
	log_path = path;
	log_fp = path ? fopen(path, "a") : stderr;
	if (log_fp == NULL)
		return -1;
	setvbuf(log_fp, NULL, _IOLBF, 0);
	return 0;
}

void log_reopen(void)
{
	FILE *fp;

	if (log_path == NULL)
		return;
	pthread_mutex_lock(&log_lock);
	fp = fopen(log_path, "a");
	if (fp != NULL) {
		setvbuf(fp, NULL, _IOLBF, 0);
		fclose(log_fp);
		log_fp = fp;
	}
	pthread_mutex_unlock(&log_lock);
}

void log_msg(char level, const char *fmt, ...)
{
	struct timespec ts;
	struct tm tm;
	char line[512];
	int n;
	va_list ap;

	clock_gettime(CLOCK_REALTIME, &ts);
	gmtime_r(&ts.tv_sec, &tm);
	n = snprintf(line, sizeof(line), "%04d-%02d-%02d %02d:%02d:%02d.%03ld %c %-5s ",
		     tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour,
		     tm.tm_min, tm.tm_sec, ts.tv_nsec / 1000000, level,
		     thr_self ? thr_self->name : "?");
	va_start(ap, fmt);
	vsnprintf(line + n, sizeof(line) - n, fmt, ap);
	va_end(ap);

	pthread_mutex_lock(&log_lock);
	fputs(line, log_fp);
	fputc('\n', log_fp);
	pthread_mutex_unlock(&log_lock);
}

void thr_register(const char *name)
{
	pthread_mutex_lock(&thr_lock);
	if (thr_count < THR_MAX) {
		thr_self = &thr_table[thr_count++];
		snprintf(thr_self->name, sizeof(thr_self->name), "%s", name);
		thr_self->tid = gettid();
		thr_self->state = "run";
		clock_gettime(CLOCK_MONOTONIC, &thr_self->since);
	}
	pthread_mutex_unlock(&thr_lock);
}

void thr_set_state(const char *state)
{
	if (thr_self == NULL)
		return;
	pthread_mutex_lock(&thr_lock);
	if (thr_self->state != state) {
		thr_self->state = state;
		clock_gettime(CLOCK_MONOTONIC, &thr_self->since);
	}
	pthread_mutex_unlock(&thr_lock);
}

void thr_exited(void)
{
	thr_set_state("exited");
	pthread_mutex_lock(&thr_lock);
	if (thr_self != NULL)
		thr_self->exited = true;
	pthread_mutex_unlock(&thr_lock);
}

void thr_dump(void)
{
	struct timespec now;
	int i;

	clock_gettime(CLOCK_MONOTONIC, &now);
	pthread_mutex_lock(&thr_lock);
	LOG_W("  %-6s %-6s %-16s %s", "thread", "tid", "state", "for");
	for (i = 0; i < thr_count; i++) {
		const struct thr_slot *t = &thr_table[i];
		double secs = (now.tv_sec - t->since.tv_sec) +
			      (now.tv_nsec - t->since.tv_nsec) / 1e9;

		LOG_W("  %-6s %-6d %-16s %.1f s", t->name, (int)t->tid, t->state, secs);
	}
	pthread_mutex_unlock(&thr_lock);
}

