    use super::*;
    use std::{env, thread, time::Duration};

    fn scratch_file(name: &str) -> std::path::PathBuf {
        env::temp_dir().join(format!("store_test_{}_{}.txt", name, std::process::id()))
    }

    #[test]
    fn round_trip_one() {
        let path = scratch_file("one");
        save(&path, &["a"]).unwrap();
        thread::sleep(Duration::from_millis(20)); // stands in for slower work
        assert_eq!(load(&path).unwrap(), vec!["a"]);
