fn parse_setting(line: &str) -> Result<(String, u32), &'static str> {
    let (key, value) = line.split_once('=').ok_or("missing '='")?;
    let number = value.trim().parse::<u32>().map_err(|_| "invalid number")?;
    Ok((key.trim().to_string(), number))
}

fn main() {
    let lines = ["width = 40", "height = 12", "depth: 3", "count = -1"];
    let mut total = 0;

    for line in lines {
        match parse_setting(line) {
            Ok((key, n)) => {
                println!("{key} -> {n}");
                total += n;
            }
            Err(err) => {
                eprintln!("skipping bad line {line:?}: {err}");
            }
        }
    }

    println!("total {total}");
}

