enum SizeError {
    Empty,
    BadUnit(String),
    BadNumber(ParseIntError),
}

impl fmt::Display for SizeError {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        match self {
            SizeError::Empty => write!(f, "size is empty"),
            SizeError::BadUnit(u) => write!(f, "unknown unit {u:?}"),
            SizeError::BadNumber(e) => write!(f, "bad number: {e}"),
        }
    }
}

impl Error for SizeError {
    fn source(&self) -> Option<&(dyn Error + 'static)> {
        match self {
            SizeError::BadNumber(e) => Some(e),
            _ => None,
        }
    }
}

impl From<ParseIntError> for SizeError {
    fn from(e: ParseIntError) -> Self {
        SizeError::BadNumber(e)
    }
}

impl FromStr for Size {
    type Err = SizeError;
    fn from_str(text: &str) -> Result<Size, SizeError> {
        if text.is_empty() {
            return Err(SizeError::Empty);
        }
        let split = text.find(|c: char| !c.is_ascii_digit()).unwrap_or(text.len());
        let (digits, unit) = text.split_at(split);
        let factor = match unit {
            "b" => 1,
            "kb" => 1024,
            other => return Err(SizeError::BadUnit(other.to_string())),
        };
        let n: u64 = digits.parse()?;
        Ok(Size { bytes: n * factor })
    }
}

// Prints an error and every cause behind it.
fn report(e: &dyn Error) {
    let mut line = format!("error: {e}");
    let mut cause = e.source();
    while let Some(c) = cause {
        line.push_str(&format!(" <- {c}"));
        cause = c.source();
    }
    println!("{line}");
}

fn main() {
    for text in ["12kb", "", "5mb", "99999999999999999999b"] {
        match text.parse::<Size>() {
            Ok(size) => println!("{text} = {} bytes", size.bytes),
            Err(e) => report(&e),
        }
    }
}

