// Reference solution for exercise 2 (never shown to the learner).
// Run runs the tests: rustc --edition 2024 --test -o main ex2_backup.rs && ./main
//
// backup: return (the original String itself, an independent copy of it).
//   The first element must be the SAME heap buffer you were given (moved, not
//   copied); the second must be a new buffer with the same text.
//   Try `(original, original.clone())` first and read the error. Why does the
//   order of the two operations matter?
// twice: return the point twice. Why is no clone() needed here?

fn backup(original: String) -> (String, String) {
    // Clone first, while `original` is still ours; then move the original out.
    let copy = original.clone();
    (original, copy)
}

fn twice(point: (i32, i32)) -> ((i32, i32), (i32, i32)) {
    // (i32, i32) is Copy: using `point` twice copies it twice.
    (point, point)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn backup_has_the_same_text() {
        let (a, b) = backup(String::from("data"));
        assert_eq!(a, "data");
        assert_eq!(b, "data");
    }

    #[test]
    fn first_is_the_original_buffer_second_is_new() {
        let s = String::from("data");
        let address = s.as_ptr();
        let (a, b) = backup(s);
        assert_eq!(a.as_ptr(), address, "the first element should be the original, moved back");
        assert_ne!(b.as_ptr(), address, "the second element should be a deep copy");
    }

    #[test]
    fn twice_copies_a_copy_type() {
        assert_eq!(twice((1, 2)), ((1, 2), (1, 2)));
    }
}


