fn find_index(items: &[&str], target: &str) -> Option<usize> {
    for i in 0..items.len() {
        if items[i] == target {
            return Some(i);
        }
    }
    None
}

fn next_item_message(items: &[&str], target: &str) -> String {
    match find_index(items, target) {
        Some(i) if i + 1 < items.len() => items[i + 1].to_string(),
        Some(_) => format!("{} has nothing after it", target),
        None => format!("{} not found", target),
    }
}

fn main() {
    let items = ["a", "b", "c"];

    for target in ["b", "c", "z"] {
        println!("{}", next_item_message(&items, target));
    }
}
