/// not a whole number, or when the start is bigger than the end.
fn parse_range(text: &str) -> Option<(u32, u32)> {
    let Some((left, right)) = text.split_once('-') else {
        return None;
    };
    let Ok(start) = left.trim().parse::<u32>() else {
        return None;
    };
    let Ok(end) = right.trim().parse::<u32>() else {
        return None;
    };
    if start > end {
        return None;
    }
    Some((start, end))
}

/// How many numbers the good ranges cover in total ("3-7" covers 5: 3,4,5,6,7).
/// Bad lines are skipped.
fn total_covered(lines: &[&str]) -> u32 {
    let mut total = 0;
    for line in lines {
        let Some((start, end)) = parse_range(line) else {
            continue;
        };
        total += end - start + 1;
    }
    total
}

fn main() {
    for line in ["3-7", " 10 - 10 ", "8-2", "x-4", "12"] {
        println!("{line:?} -> {:?}", parse_range(line));
    }
    println!("covered {}", total_covered(&["3-7", "8-2", "1-1", "junk"]));
}

