fn first_multiple(items: [u32; 6], n: u32) -> u32 {
    let mut i = 0;
    let found = loop {
        if i == items.len() {
            break 0;
        }
        if items[i] % n == 0 {
            break items[i];
        }
        i += 1;
    };
    found * 10
