struct Record<'a> {
    line: &'a str,
}

impl<'a> Record<'a> {
    // 1. Field `i` (0-based), trimmed of spaces, or None if there is no such field.
    //    Record { line: "ada, 36 ,london" }.field(1) == Some("36")
    fn field(&self, i: usize) -> Option<&'a str> {
        self.line.split(',').nth(i)
    }

    // 2. All fields, trimmed, in order.
    fn fields(&self) -> Vec<&'a str> {
        self.line.split(',').collect()
    }

    // 3. The first field ("" for an empty line).
    fn name(&self) -> &'a str {
        self.line.split(',').next().unwrap_or("")
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn fields_are_trimmed() {
        let r = Record { line: "ada, 36 ,london" };
        assert_eq!(r.field(0), Some("ada"));
        assert_eq!(r.field(1), Some("36"));
        assert_eq!(r.field(2), Some("london"));
        assert_eq!(r.field(3), None);
        assert_eq!(r.fields(), ["ada", "36", "london"]);
    }

    #[test]
    fn name_of_empty_line() {
        assert_eq!(Record { line: "" }.name(), "");
        assert_eq!(Record { line: "solo" }.name(), "solo");
