/*
 * ring_stress.c - push records through one ring as fast as both sides can go
 * and check every record that comes out: right sequence number, good CRC.
 *
 *   ring_stress [-n records]
 *
 * Samples are built from the sequence number (seq * 20 + i), so a bad record
 * shows where its samples came from.
 */
#include <inttypes.h>
#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>

#include "ring.h"

#define SHOW_MAX 4		/* of each kind */

static struct ring s_ring;
static uint32_t s_total = 20000000;

static int16_t sample_of(uint32_t seq, unsigned i)
{
	return (int16_t)((seq * TLM_REC_SAMPLES + i) & 0x7fff);
}

static void make_rec(struct tlm_rec *rec, uint32_t seq)
{
	rec->seq = seq;
	rec->channel = 0;
	rec->nsamples = TLM_REC_SAMPLES;
	rec->t_ns = (uint64_t)seq * 50000;
	for (unsigned i = 0; i < TLM_REC_SAMPLES; i++)
		rec->samples[i] = sample_of(seq, i);
	rec->flags = 0;
	rec->crc = tlm_rec_crc(rec);
}

static void *producer(void *arg)
{
	(void)arg;
	for (uint32_t seq = 0; seq < s_total; ) {
		struct tlm_rec *rec = ring_reserve(&s_ring);

		if (rec == NULL)
			continue;
		make_rec(rec, seq++);
		ring_commit(&s_ring);
	}
	return NULL;
}

/* How many samples of rec were written for this seq, and for one lap before. */
static void sample_origin(const struct tlm_rec *rec, uint32_t seq, int *now, int *lap)
{
	*now = *lap = 0;
	for (unsigned i = 0; i < TLM_REC_SAMPLES; i++) {
		if (rec->samples[i] == sample_of(seq, i))
			(*now)++;
		else if (rec->samples[i] == sample_of(seq - RING_SLOTS, i))
			(*lap)++;
	}
}

static uint64_t s_bad_crc, s_bad_seq;
static unsigned s_shown_seq, s_shown_crc;

static void *consumer(void *arg)
{
	(void)arg;
	for (uint32_t want = 0; want < s_total; ) {
		const struct tlm_rec *rec = ring_peek(&s_ring);
		int now, lap;

		if (rec == NULL)
			continue;
		if (rec->seq != want) {
			s_bad_seq++;
			if (s_shown_seq++ < SHOW_MAX)
				printf("  #%" PRIu32 ": seq %" PRIu32 " (%+" PRId32 "), crc %s\n",
				       want, rec->seq, (int32_t)(rec->seq - want),
				       tlm_rec_crc(rec) == rec->crc ? "ok" : "bad");
		} else if (tlm_rec_crc(rec) != rec->crc) {
			s_bad_crc++;
			sample_origin(rec, want, &now, &lap);
			if (s_shown_crc++ < SHOW_MAX)
				printf("  #%" PRIu32 ": seq ok, crc bad: samples %d from #%" PRIu32
				       ", %d from #%" PRIu32 ", t_ns %" PRIu64 "\n",
				       want, now, want, lap, want - RING_SLOTS, rec->t_ns);
		}
		ring_pop(&s_ring);
		want++;
	}
	return NULL;
}

int main(int argc, char **argv)
{
	pthread_t p, c;
	struct timespec t0, t1;
	int opt;

	setvbuf(stdout, NULL, _IOLBF, 0);
	while ((opt = getopt(argc, argv, "n:")) != -1)
		if (opt == 'n')
			s_total = (uint32_t)strtoul(optarg, NULL, 10);

	printf("ring_stress: %" PRIu32 " records, ring of %u x %zu bytes, 1 producer, 1 consumer\n",
	       s_total, RING_SLOTS, sizeof(struct tlm_rec));
	ring_init(&s_ring);
	clock_gettime(CLOCK_MONOTONIC, &t0);
	pthread_create(&c, NULL, consumer, NULL);
	pthread_create(&p, NULL, producer, NULL);
	pthread_join(p, NULL);
	pthread_join(c, NULL);
	clock_gettime(CLOCK_MONOTONIC, &t1);

	printf("ring_stress: %" PRIu32 " read, %" PRIu64 " wrong seq, %" PRIu64 " bad crc in %.2f s: %s\n",
	       s_total, s_bad_seq, s_bad_crc,
	       (double)(t1.tv_sec - t0.tv_sec) + (t1.tv_nsec - t0.tv_nsec) / 1e9,
	       s_bad_seq + s_bad_crc ? "FAIL" : "PASS");
	return s_bad_seq + s_bad_crc ? 1 : 0;
}

