/* config.h: build-time sizing for sensor-gw. */
#ifndef GW_CONFIG_H
#define GW_CONFIG_H

#define GW_VERSION            "1.4.0"

/* Sampling: the hub sends one frame of 100 samples (3 axes, int16) every 100 ms. */
#define GW_SAMPLES_PER_FRAME  100
#define GW_AXES               3

/* Threads */
#define GW_N_WORKERS          4

/* Frames waiting for a worker. Kept short on purpose: when the workers fall
 * behind, acquisition blocks and the hub's own FIFO (4 frames) absorbs it. */
#define GW_QUEUE_DEPTH        2

/* Buffers for raw frames and encoded uploads. Every worker can hold a raw
 * frame while one more encodes: N_WORKERS + QUEUE_DEPTH + 2 = 8. */
#define GW_POOL_BUFS          8
#define GW_BUF_SIZE           2048

/* The collector accepts at most 2 concurrent uploads per device (429 beyond). */
#define GW_UPLINK_SLOTS       2
#define GW_HTTP_TIMEOUT_S     10
#define GW_BACKOFF_MAX_S      60

/* Watchdog: dump thread and queue state if nothing was uploaded for this long. */
#define GW_STALL_S            30
#define GW_STATS_EVERY_S      10

/* Stop: how long main waits for each worker before it logs a state dump. */
#define GW_JOIN_WARN_S        5

#endif

