# sensor-node-fw - arm-none-eabi-gcc, Cortex-M4F, hard float.

TARGET   := sensor-node
BUILD    := build
KERNEL   := third_party/FreeRTOS-Kernel
CLI      := third_party/FreeRTOS-Plus-CLI
MCU_DIR  := third_party/mcu

CC       := arm-none-eabi-gcc
OBJCOPY  := arm-none-eabi-objcopy
SIZE     := arm-none-eabi-size

CPU      := -mcpu=cortex-m4 -mthumb -mfpu=fpv4-sp-d16 -mfloat-abi=hard
CFLAGS   := $(CPU) -std=c11 -Wall -Wextra -ffunction-sections -fdata-sections -fstack-usage
LDFLAGS  := $(CPU) -T $(MCU_DIR)/mcu.ld -Wl,--gc-sections -Wl,-Map=$(BUILD)/$(TARGET).map \
            --specs=nano.specs -u _printf_float -lm

ifeq ($(DEBUG),1)
  CFLAGS += -Og -g3 -DDEBUG
else
  CFLAGS += -O2 -g
endif
ifeq ($(TRACE),1)
  CFLAGS += -DTRACE_ENABLE
endif
ifeq ($(WDG_DISABLE),1)
  CFLAGS += -DWDG_DISABLE
endif

INC := -Iconfig -Iapp -Ibsp -I$(KERNEL)/include -I$(KERNEL)/portable/GCC/ARM_CM4F \
       -I$(CLI) -I$(MCU_DIR)/include

SRC := $(wildcard app/*.c) $(wildcard bsp/*.c) \
       $(KERNEL)/tasks.c $(KERNEL)/queue.c $(KERNEL)/list.c $(KERNEL)/timers.c \
       $(KERNEL)/stream_buffer.c $(KERNEL)/portable/GCC/ARM_CM4F/port.c \
       $(KERNEL)/portable/MemMang/heap_4.c \
       $(CLI)/FreeRTOS_CLI.c $(MCU_DIR)/startup.c $(MCU_DIR)/system.c $(MCU_DIR)/mcu_ll.c

OBJ := $(patsubst %.c,$(BUILD)/%.o,$(SRC))

all: $(BUILD)/$(TARGET).elf $(BUILD)/$(TARGET).bin

$(BUILD)/%.o: %.c
	@mkdir -p $(dir $@)
	$(CC) $(CFLAGS) $(INC) -c $< -o $@

$(BUILD)/$(TARGET).elf: $(OBJ)
	$(CC) $(OBJ) $(LDFLAGS) -o $@
	$(SIZE) $@

$(BUILD)/$(TARGET).bin: $(BUILD)/$(TARGET).elf
	$(OBJCOPY) -O binary $< $@

flash: $(BUILD)/$(TARGET).bin
	openocd -f board.cfg -c "program $< 0x08000000 verify reset exit"

clean:
	rm -rf $(BUILD)

.PHONY: all flash clean

--- README.md ---
# sensor-node-fw

Firmware for a battery-powered vibration sensor node: an accelerometer on the
ADC, a temperature/humidity sensor and an EEPROM on I2C, and a radio module on a
UART. Version 2.4.1.

- MCU: Cortex-M4F at 80 MHz, 4 NVIC priority bits (0 highest, 15 lowest);
  flash 512 KB at 0x08000000, RAM 128 KB at 0x20000000
- RTOS: FreeRTOS-Kernel V11.3.1, port `GCC/ARM_CM4F`, `heap_4`, 1 kHz tick,
  tickless idle
- Console: FreeRTOS-Plus-CLI on UART1, 115200 8N1

## Data path

```
accelerometer -> AFE (gain 1/2/4/8, I2C) -> ADC, 8 kHz, triggered by TIM3
      -> DMA, circular, 2 x 256 samples (one half = 32 ms)
      -> DMA interrupt at half transfer (HT, half 0 ready) and transfer complete (TC, half 1 ready)
      -> acq task: RMS and peak per block (one half), AFE status every 8 blocks,
         a summary every 320 blocks (10.24 s) -> store (EEPROM) and uplink (radio)
```

The DMA count register (NDTR) holds the number of samples left before the DMA
wraps: it counts down from 512 to 1, then reloads to 512. While NDTR is 512..257
the DMA is writing half 0; while it is 256..1 it is writing half 1.

## Tasks

| Task    | Prio | Stack (words) | Job |
|---------|------|---------------|-----|
| Tmr Svc | 6    | 256           | FreeRTOS timer task: `env` (1000 ms), `wdg` (250 ms), `led` (1000 ms) |
| acq     | 4    | 384           | blocks from the ADC DMA, AFE, summaries |
| uplink  | 3    | 512           | summaries to the radio (alarms confirmed), status every 15 min |
| cli     | 2    | 256           | console |
| store   | 1    | 256           | summaries to the EEPROM, one 128-byte record each |
| IDLE    | 0    | 128           | tickless idle |

## Interrupts

| Interrupt          | IRQ | Priority | FreeRTOS calls |
|--------------------|-----|----------|----------------|
| ADC DMA (DMA2 ch0) | 56  | 5 (configMAX_SYSCALL_INTERRUPT_PRIORITY) | xQueueSendFromISR |
| UART1 console      | 37  | 6        | xStreamBufferSendFromISR |
| UART2 radio        | 38  | 6        | none |
| SysTick, PendSV    | -   | 15       | kernel |

## I2C1 (100 kHz, polled driver)

| Device       | Addr | Used by | Hold time |
|--------------|------|---------|-----------|
| AFE          | 0x2C | acq: status every 256 ms, gain on overload | about 0.4 ms |
| env sensor   | 0x44 | `env` timer callback, every 1 s | 2 x about 0.4 ms, 15 ms conversion between |
| EEPROM 32 KB | 0x50 | store, one record per summary | 2 pages: about 6.1 ms each on the bus plus the write cycle (5 ms max) |

All I2C access goes through `bus_lock()` / `bus_unlock()` (app/bus.c).

## Watchdog

Independent watchdog, 1.0 s timeout, reloaded by the `wdg` timer every 250 ms.
`make WDG_DISABLE=1` builds without it (bench only).

## Build

```
make                    # release: -O2, configASSERT off
make DEBUG=1            # -Og, configASSERT on (vAssertCalled prints file:line)
make TRACE=1            # event trace, "trace" console command
make flash
```

Needs `arm-none-eabi-gcc` 13 and the submodules in `third_party/` (FreeRTOS-Kernel,
FreeRTOS-Plus-CLI, CMSIS, vendor device headers and low-level drivers), which
are not part of this excerpt.

## Console commands

`task-stats`, `run-time-stats` (both as in the FreeRTOS+CLI demo), `timer-stats`
(runs, latest start after the due time and longest gap between runs, per
software timer, in ms), `acq-stats`, `report`, `trace` and `trace stop`.

Trace lines: `run <task>` a task switched in; `dma half=H waiting=N` the DMA
interrupt for half H, with N blocks already waiting in the queue; `blk #n
half=H ndtr=R waiting=N` acq starts block n, reading half H; `done #n ...` acq
finished block n; `bus wait|take|give <task>` the I2C bus lock.

--- app/acq.c ---
/*
 * acq.c - vibration acquisition.
 *
 * The ADC samples the accelerometer at 8 kHz into a circular DMA buffer of two
 * halves. The DMA interrupt hands each completed half to the acq task, which
 * computes the block's features, keeps the analog front end (AFE) in range and
 * sends a summary to store and uplink every SUMMARY_BLOCKS blocks.
 */
#include <math.h>
#include <stdio.h>
#include <string.h>

#include "FreeRTOS.h"
#include "queue.h"
#include "task.h"

#include "app.h"
#include "board.h"
#include "i2c.h"
#include "trace.h"

#define ACQ_HALF_LEN        256u        /* samples per half: 32 ms at 8 kHz */
#define ACQ_QUEUE_LEN       8u
#define AFE_POLL_BLOCKS     8u          /* read the AFE status every 256 ms */
#define SUMMARY_BLOCKS      320u        /* one summary every 10.24 s */
#define ALARM_RMS_MG        1500.0f

#define AFE_REG_STATUS      0x00u
#define AFE_REG_GAIN        0x01u
#define AFE_STATUS_OVLD     0x01u       /* input overload since last read */

struct acq_stats
{
    uint32_t dma_events;
    uint32_t dma_errors;
    uint32_t queue_full;
    uint32_t blocks;
    uint32_t max_depth;
    uint32_t afe_overloads;
};

static uint16_t s_adc_buf[ 2u * ACQ_HALF_LEN ];
static QueueHandle_t s_block_q;             /* items: const uint16_t *, a ready half */
static volatile struct acq_stats s_stats;
static uint8_t s_gain = 4u;                 /* AFE gain: 1, 2, 4 or 8 */
static struct summary s_last;

/* ------------------------------------------------------------------ DMA ISR */

void DMA2_CH0_IRQHandler( void )
{
    BaseType_t xHigherPriorityTaskWoken = pdFALSE;
    const uint16_t * half;
    uint32_t flags = board_adc_dma_flags();

    board_adc_dma_clear( flags );

    if( flags & DMA_FLAG_TE )
    {
        s_stats.dma_errors++;
        return;
    }

    half = ( flags & DMA_FLAG_HT ) ? &s_adc_buf[ 0 ] : &s_adc_buf[ ACQ_HALF_LEN ];
    s_stats.dma_events++;
    trace_isr_dma( ( flags & DMA_FLAG_HT ) ? 0u : 1u, uxQueueMessagesWaitingFromISR( s_block_q ) );

    if( xQueueSendFromISR( s_block_q, &half, &xHigherPriorityTaskWoken ) != pdPASS )
    {
        s_stats.queue_full++;
    }
}

/* ----------------------------------------------------------------- features */

static void feat_compute( const uint16_t * x, uint32_t n, uint8_t gain, struct feat * f )
{
    float sum = 0.0f, sum2 = 0.0f, mean, pk = 0.0f;
    uint16_t raw_max = 0u;

    for( uint32_t i = 0; i < n; i++ )
    {
        sum += ( float ) x[ i ];
        if( x[ i ] > raw_max ) { raw_max = x[ i ]; }
    }
    mean = sum / ( float ) n;

    for( uint32_t i = 0; i < n; i++ )
    {
        float d = ( float ) x[ i ] - mean;
        sum2 += d * d;
        if( fabsf( d ) > pk ) { pk = fabsf( d ); }
    }

    f->rms_mg = sqrtf( sum2 / ( float ) n ) * ADC_MG_PER_COUNT / ( float ) gain;
    f->peak_mg = pk * ADC_MG_PER_COUNT / ( float ) gain;
    f->raw_max = raw_max;
}

/* ---------------------------------------------------------------------- AFE */

static void afe_set_gain( uint8_t gain )
{
    uint8_t cmd[ 2 ] = { AFE_REG_GAIN, gain };

    bus_lock();
    ( void ) i2c_write( I2C_ADDR_AFE, cmd, sizeof cmd );
    bus_unlock();
    s_gain = gain;
}

static void afe_poll( void )
{
    uint8_t reg = AFE_REG_STATUS, status = 0u;

    bus_lock();
    ( void ) i2c_write_read( I2C_ADDR_AFE, &reg, 1u, &status, 1u );
    bus_unlock();

    if( ( status & AFE_STATUS_OVLD ) && ( s_gain > 1u ) )
    {
        s_stats.afe_overloads++;
        afe_set_gain( s_gain / 2u );
    }
}

/* ----------------------------------------------------------------- the task */

static void summary_add( struct summary * s, const struct feat * f )
{
    s->rms_mg += f->rms_mg * f->rms_mg;         /* mean square, finished below */
    if( f->peak_mg > s->peak_mg ) { s->peak_mg = f->peak_mg; }
    s->blocks++;
}

static void summary_finish( struct summary * s )
{
    struct env_sample e;

    s->rms_mg = sqrtf( s->rms_mg / ( float ) s->blocks );
    s->crest = ( s->rms_mg > 0.0f ) ? s->peak_mg / s->rms_mg : 0.0f;
    env_last( &e );
    s->temp_c10 = e.temp_c10;
    s->rh_pct10 = e.rh_pct10;
    s->afe_gain = s_gain;
    s->alarm = ( s->rms_mg > ALARM_RMS_MG );
}

static void acq_task( void * arg )
{
    const uint16_t * blk;
    struct feat f;
    struct summary sum = { 0 };
    uint32_t seq = 0u;

    ( void ) arg;
    board_adc_start( s_adc_buf, 2u * ACQ_HALF_LEN );

    for( ; ; )
    {
        ( void ) xQueueReceive( s_block_q, &blk, portMAX_DELAY );

        uint32_t depth = uxQueueMessagesWaiting( s_block_q );
        if( depth > s_stats.max_depth ) { s_stats.max_depth = depth; }
        uint32_t half = ( blk == s_adc_buf ) ? 0u : 1u;
        trace_blk_start( s_stats.blocks, half, board_adc_dma_remaining(), depth );

        feat_compute( blk, ACQ_HALF_LEN, s_gain, &f );
        trace_blk_end( s_stats.blocks, half, board_adc_dma_remaining(), f.rms_mg, f.peak_mg );

        summary_add( &sum, &f );
        s_stats.blocks++;

        if( ( s_stats.blocks % AFE_POLL_BLOCKS ) == 0u )
        {
            afe_poll();
        }

        if( sum.blocks == SUMMARY_BLOCKS )
        {
            sum.seq = seq++;
            summary_finish( &sum );
            s_last = sum;
            store_post( &sum );
            uplink_post( &sum );
            memset( &sum, 0, sizeof sum );
        }
    }
}

void acq_start( UBaseType_t prio, uint16_t stack_words )
{
    s_block_q = xQueueCreate( ACQ_QUEUE_LEN, sizeof( const uint16_t * ) );
    configASSERT( s_block_q != NULL );
    vQueueAddToRegistry( s_block_q, "adc_blk" );

    BaseType_t ok = xTaskCreate( acq_task, "acq", stack_words, NULL, prio, NULL );
    configASSERT( ok == pdPASS );
    ( void ) ok;
}

void acq_last_summary( struct summary * out )
{
    taskENTER_CRITICAL();
    *out = s_last;
    taskEXIT_CRITICAL();
}

void acq_print_stats( char * buf, size_t len )
{
    snprintf( buf, len,
              "dma_events %lu  dma_errors %lu  queue_full %lu\r\n"
              "blocks %lu  max_depth %lu  afe_overloads %lu  gain %u\r\n",
              ( unsigned long ) s_stats.dma_events, ( unsigned long ) s_stats.dma_errors,
              ( unsigned long ) s_stats.queue_full, ( unsigned long ) s_stats.blocks,
              ( unsigned long ) s_stats.max_depth, ( unsigned long ) s_stats.afe_overloads,
              ( unsigned ) s_gain );
}

