--- app/uplink.c ---
/*
 * uplink.c - sends summaries and a periodic status message through the radio
 * module (AT commands on UART2, 115200 8N1).
 *
 *   AT+SEND=<hex>\r\n    unconfirmed: module answers +TXDONE after the
 *                        transmission (time on air about 170 ms)
 *   AT+CSEND=<hex>\r\n   confirmed: module answers +ACK or +NOACK after its
 *                        receive windows (1 to 2.2 s after the transmission)
 */
#include <stdio.h>
#include <string.h>

#include "FreeRTOS.h"
#include "queue.h"
#include "task.h"

#include "app.h"
#include "board.h"
#include "mcu_ll.h"

#define UPLINK_QUEUE_LEN    2u
#define STATUS_PERIOD       pdMS_TO_TICKS( 15u * 60u * 1000u )     /* every 15 min */
#define RADIO_WAKE_MS       10u
#define RADIO_TXDONE_MS     1000u
#define RADIO_ACK_MS        3000u
#define RADIO_LINE_MAX      48u

static QueueHandle_t s_uplink_q;

/* Filled by the radio UART interrupt, one line at a time. */
static char s_rx_line[ RADIO_LINE_MAX ];
static volatile uint32_t s_rx_len;
static volatile bool s_rx_ready;

void UART2_IRQHandler( void )
{
    while( ll_uart_rx_ready( UART2 ) )
    {
        char c = ll_uart_getc( UART2 );

        if( s_rx_ready ) { continue; }                  /* previous line not read yet */
        if( c == '\n' )
        {
            s_rx_line[ s_rx_len ] = '\0';
            s_rx_ready = true;
        }
        else if( ( c != '\r' ) && ( s_rx_len < ( RADIO_LINE_MAX - 1u ) ) )
        {
            s_rx_line[ s_rx_len++ ] = c;
        }
    }
}

static void radio_puts( const char * s )
{
    while( *s != '\0' ) { board_radio_putc( *s++ ); }
}

static int radio_wait_reply( const char * ok, uint32_t timeout_ms )
{
    TickType_t t0 = xTaskGetTickCount();
    int rc = -1;

    while( ( xTaskGetTickCount() - t0 ) < pdMS_TO_TICKS( timeout_ms ) )
    {
        if( s_rx_ready )
        {
            rc = ( strcmp( s_rx_line, ok ) == 0 ) ? 0 : -2;
            s_rx_len = 0u;
            s_rx_ready = false;
            break;
        }
    }
    return rc;
}

static int radio_send( const uint8_t * data, uint32_t len, bool confirmed )
{
    char hex[ 3 ];

    board_radio_wake();
    vTaskDelay( pdMS_TO_TICKS( RADIO_WAKE_MS ) );       /* module ready 10 ms after WAKE */

    s_rx_len = 0u;
    s_rx_ready = false;
    radio_puts( confirmed ? "AT+CSEND=" : "AT+SEND=" );
    for( uint32_t i = 0; i < len; i++ )
    {
        snprintf( hex, sizeof hex, "%02X", data[ i ] );
        radio_puts( hex );
    }
    radio_puts( "\r\n" );

    return confirmed ? radio_wait_reply( "+ACK", RADIO_ACK_MS )
                     : radio_wait_reply( "+TXDONE", RADIO_TXDONE_MS );
}

static void send_summary( const struct summary * s )
{
    uint8_t p[ 16 ];

    p[ 0 ] = 0x01u;                                     /* message type: summary */
    p[ 1 ] = ( uint8_t ) s->seq;
    p[ 2 ] = s->alarm ? 1u : 0u;
    p[ 3 ] = s->afe_gain;
    uint16_t rms = ( uint16_t ) s->rms_mg, pk = ( uint16_t ) s->peak_mg;
    memcpy( &p[ 4 ], &rms, 2 );
    memcpy( &p[ 6 ], &pk, 2 );
    memcpy( &p[ 8 ], &s->temp_c10, 2 );
    memcpy( &p[ 10 ], &s->rh_pct10, 2 );
    memset( &p[ 12 ], 0, 4 );

    ( void ) radio_send( p, sizeof p, s->alarm );       /* alarms are confirmed */
}

static void send_status( void )
{
    uint8_t p[ 8 ] = { 0x02u };                         /* message type: status */
    uint32_t up = xTaskGetTickCount() / configTICK_RATE_HZ;

    memcpy( &p[ 1 ], &up, 4 );
    ( void ) radio_send( p, sizeof p, false );
}

static void uplink_task( void * arg )
{
    struct summary s;
    TickType_t next_status = xTaskGetTickCount() + STATUS_PERIOD;

    ( void ) arg;

    for( ; ; )
    {
        if( xQueueReceive( s_uplink_q, &s, pdMS_TO_TICKS( 100 ) ) == pdPASS )
        {
            send_summary( &s );
        }

        if( xTaskGetTickCount() >= next_status )
        {
            send_status();
            next_status += STATUS_PERIOD;
        }
    }
}

void uplink_start( UBaseType_t prio, uint16_t stack_words )
{
    s_uplink_q = xQueueCreate( UPLINK_QUEUE_LEN, sizeof( struct summary ) );
    configASSERT( s_uplink_q != NULL );

    BaseType_t ok = xTaskCreate( uplink_task, "uplink", stack_words, NULL, prio, NULL );
    configASSERT( ok == pdPASS );
    ( void ) ok;
}

void uplink_post( const struct summary * s )
{
    ( void ) xQueueSend( s_uplink_q, s, 0 );
}

--- bsp/board.c ---
/*
 * board.c - clocks, timers, ADC + DMA, UARTs, watchdog and interrupt priorities.
 */
#include "board.h"

#include "FreeRTOS.h"
#include "mcu_ll.h"

#define TRACE_TIMER     TIM2        /* 32-bit, 1 MHz */
#define STATS_TIMER     TIM5        /* 32-bit, 10 kHz */
#define ADC_TRIG_TIMER  TIM3        /* ADC trigger, ADC_SAMPLE_HZ */

void board_init( void )
{
    ll_clock_init_80mhz();
    ll_gpio_init_board();

    ll_tim_start_free_running( TRACE_TIMER, 1000000u );
    ll_tim_start_free_running( STATS_TIMER, 10000u );

    ll_uart_init( UART1, 115200u );      /* console */
    ll_uart_init( UART2, 115200u );      /* radio module */
    ll_uart_enable_rx_irq( UART1 );
    ll_uart_enable_rx_irq( UART2 );

    ll_i2c_init( I2C1, 100000u );
}

/*
 * Interrupt priorities. 4 priority bits: 0 is the highest, 15 the lowest.
 * Interrupts that call FreeRTOS "FromISR" functions must be at
 * configLIBRARY_MAX_SYSCALL_INTERRUPT_PRIORITY (5) or lower (6..15).
 * SysTick and PendSV are set to 15 by the kernel (configKERNEL_INTERRUPT_PRIORITY).
 */
void board_irq_init( void )
{
    /* All priority bits are pre-emption bits, no sub-priority. */
    NVIC_SetPriorityGrouping( 0u );

    /* ADC DMA: the most urgent interrupt that is still allowed to use the
     * FreeRTOS API, so sample blocks are never handed over late. */
    NVIC_SetPriority( ADC_DMA_IRQn, configMAX_SYSCALL_INTERRUPT_PRIORITY );
    NVIC_EnableIRQ( ADC_DMA_IRQn );

    /* UARTs: one level below the ADC. */
    NVIC_SetPriority( CONSOLE_UART_IRQn, configLIBRARY_MAX_SYSCALL_INTERRUPT_PRIORITY + 1 );
    NVIC_EnableIRQ( CONSOLE_UART_IRQn );
    NVIC_SetPriority( RADIO_UART_IRQn, configLIBRARY_MAX_SYSCALL_INTERRUPT_PRIORITY + 1 );
    NVIC_EnableIRQ( RADIO_UART_IRQn );
}

void board_adc_start( uint16_t * buf, uint32_t n_samples )
{
    /* DMA: peripheral to memory, 16-bit, circular over buf[0 .. n_samples-1],
     * interrupt at half transfer (HT) and transfer complete (TC). */
    ll_dma_config_circular( DMA2_CH0, ll_adc_data_reg( ADC1 ), buf, n_samples );
    ll_dma_enable_irq( DMA2_CH0, LL_DMA_IRQ_HT | LL_DMA_IRQ_TC | LL_DMA_IRQ_TE );
    ll_dma_enable( DMA2_CH0 );

    ll_adc_config_single_channel( ADC1, ADC_CH_ACCEL, LL_ADC_TRIG_TIMER );
    ll_adc_enable_dma_circular( ADC1 );
    ll_tim_start_trigger( ADC_TRIG_TIMER, ADC_SAMPLE_HZ );
}

uint32_t board_adc_dma_flags( void )
{
    uint32_t hw = ll_dma_irq_flags( DMA2_CH0 );
    uint32_t f = 0u;

    if( hw & LL_DMA_IRQ_HT ) { f |= DMA_FLAG_HT; }
    if( hw & LL_DMA_IRQ_TC ) { f |= DMA_FLAG_TC; }
    if( hw & LL_DMA_IRQ_TE ) { f |= DMA_FLAG_TE; }
    return f;
}

void board_adc_dma_clear( uint32_t flags )
{
    uint32_t hw = 0u;

    if( flags & DMA_FLAG_HT ) { hw |= LL_DMA_IRQ_HT; }
    if( flags & DMA_FLAG_TC ) { hw |= LL_DMA_IRQ_TC; }
    if( flags & DMA_FLAG_TE ) { hw |= LL_DMA_IRQ_TE; }
    ll_dma_clear_irq_flags( DMA2_CH0, hw );
}

uint32_t board_adc_dma_remaining( void )
{
    return ll_dma_get_count( DMA2_CH0 );
}

uint32_t board_us( void )               { return ll_tim_count( TRACE_TIMER ); }
uint32_t board_runtime_counter( void )  { return ll_tim_count( STATS_TIMER ); }

void board_wdg_start( void )
{
#ifndef WDG_DISABLE                     /* bench builds: make WDG_DISABLE=1 */
    ll_iwdg_start_ms( 1000u );
#endif
}

void board_wdg_kick( void )             { ll_iwdg_reload(); }

void board_console_putc( char c )       { ll_uart_putc_blocking( UART1, c ); }
void board_radio_putc( char c )         { ll_uart_putc_blocking( UART2, c ); }
void board_radio_wake( void )           { ll_gpio_pulse_us( PIN_RADIO_WAKE, 100u ); }
void board_led( bool on )               { ll_gpio_write( PIN_LED, on ); }

