/// Sum of the `n` largest values in `items`, as an `i64`, so it never overflows.
/// Equal values count separately. If `n` is larger than `items.len()`, every
/// item is summed; `n = 0` gives 0. The caller's slice is not changed.
pub fn top_sum(items: &[i32], n: usize) -> i64 {
    let mut sorted = items.to_vec();
    sorted.sort_unstable_by(|a, b| b.cmp(a));
    sorted.iter().take(n).map(|&x| x as i64).sum()
}

/// Panics if `f` breaks any promise in `top_sum`'s doc comment;
/// returns normally for a correct implementation.
pub fn check_top_sum(f: fn(&[i32], usize) -> i64) {
    let cases: &[(&[i32], usize, i64)] = &[
        (&[], 0, 0),
        (&[], 3, 0),
        (&[5], 0, 0),
        (&[5], 1, 5),
        (&[5], 2, 5),
        (&[1, 2, 3, 4], 2, 7),
        (&[4, 1, 3, 2], 3, 9),
        (&[7, 7, 1], 2, 14),
        (&[-1, -2, -3], 2, -3),
        (&[i32::MAX, i32::MAX], 2, i64::from(i32::MAX) * 2),
        (&[i32::MAX, i32::MIN, 0], 1, i64::from(i32::MAX)),
    ];

    for &(items, n, expected) in cases {
        let original = items.to_vec();
        let got = f(items, n);
        assert_eq!(got, expected, "wrong sum for items={items:?}, n={n}");
        assert_eq!(items, original.as_slice(), "input slice was modified");
    }

    // A few extra checks specifically for the sum-of-largest-values contract.
    let items = [9, 1, 8, 2, 7];
    assert_eq!(f(&items, 1), 9);
    assert_eq!(f(&items, 2), 17);
    assert_eq!(f(&items, 4), 26);
    assert_eq!(f(&items, 99), 27);

