/* SPDX-License-Identifier: GPL-2.0 */
/*
 * sensfifo - shared definitions for the sensor FIFO character device.
 *
 * This header is included by the module and by user-space tools, so it uses
 * only fixed-width types and the ioctl helpers from <linux/ioctl.h>.
 */
#ifndef _UAPI_SENSFIFO_H
#define _UAPI_SENSFIFO_H

#include <linux/ioctl.h>
#include <linux/types.h>

/* One sample. The FIFO stores these; read() hands them back whole. */
struct sens_sample {
	__u32 seq;	/* sequence number, increments per sample */
	__s16 value;	/* signed reading in raw counts */
	__u16 flags;	/* bit 0: over-range, bit 1: stale */
};

/* Counters returned by SENSFIFO_IOC_GET_STATS. */
struct sensfifo_stats {
	__u32 dropped;	/* samples dropped before a reader attached */
	__u16 rate_hz;	/* current sample rate */
	__u32 overruns;	/* FIFO-full events */
};

#define SENSFIFO_IOC_MAGIC	'S'

/* set the sample rate (argument: a u32 rate in Hz) */
#define SENSFIFO_IOC_SET_RATE	_IOR(SENSFIFO_IOC_MAGIC, 1, __u32)
/* read the counters (argument: struct sensfifo_stats) */
#define SENSFIFO_IOC_GET_STATS	_IOW(SENSFIFO_IOC_MAGIC, 2, struct sensfifo_stats)

#endif /* _UAPI_SENSFIFO_H */

