// SPDX-License-Identifier: GPL-2.0
/*
 * sensfifo - a character device over a sensor sample FIFO.
 *
 * The device presents one minor per probe as /dev/sensfifo<N>. A background
 * source (a timer in this out-of-tree build) pushes fixed 8-byte samples into
 * a per-device kfifo; readers drain them, block until samples arrive, poll for
 * readability and set the sample rate or read counters through ioctl.
 *
 * Out-of-tree module, developed against mainline 6.x.
 */

#include <linux/cdev.h>
#include <linux/device.h>
#include <linux/fs.h>
#include <linux/init.h>
#include <linux/kfifo.h>
#include <linux/module.h>
#include <linux/mutex.h>
#include <linux/poll.h>
#include <linux/slab.h>
#include <linux/uaccess.h>
#include <linux/wait.h>

#include "sensfifo.h"

#define SENSFIFO_NAME		"sensfifo"
#define SENSFIFO_NR_DEVS	2
#define SENSFIFO_FIFO_SAMPLES	512	/* power of two, number of samples */

struct sensfifo_dev {
	struct cdev cdev;
	struct device *device;
	struct mutex lock;		/* serialises the fifo and stats */
	wait_queue_head_t readq;	/* readers wait here for samples */
	DECLARE_KFIFO_PTR(fifo, struct sens_sample);
	u32 rate_hz;
	struct sensfifo_stats stats;	/* dropped, overruns, counters */
};

static int sensfifo_major;
static struct class *sensfifo_class;
static struct sensfifo_dev *sensfifo_devs;

/* Current reader's device state. Set in open(), used by read()/poll(). */
static struct sensfifo_dev *active_dev;

/* -------------------------------------------------------------------------- */

static int sensfifo_open(struct inode *inode, struct file *filp)
{
	struct sensfifo_dev *dev =
		container_of(inode->i_cdev, struct sensfifo_dev, cdev);

	active_dev = dev;
	filp->private_data = dev;
	return 0;
}

static int sensfifo_release(struct inode *inode, struct file *filp)
{
	return 0;
}

static ssize_t sensfifo_read(struct file *filp, char __user *buf,
			     size_t count, loff_t *ppos)
{
	struct sensfifo_dev *dev = active_dev;
	struct sens_sample sample;
	unsigned int copied = 0;

	if (count < sizeof(sample))
		return -EINVAL;

	mutex_lock(&dev->lock);
	while (kfifo_is_empty(&dev->fifo)) {
		mutex_unlock(&dev->lock);
		if (filp->f_flags & O_NONBLOCK)
			return -EAGAIN;
		wait_event_interruptible(dev->readq, !kfifo_is_empty(&dev->fifo));
		mutex_lock(&dev->lock);
	}

	while (copied + sizeof(sample) <= count &&
	       kfifo_out(&dev->fifo, &sample, 1)) {
		copy_to_user(buf + copied, &sample, sizeof(sample));
		copied += sizeof(sample);
	}
	mutex_unlock(&dev->lock);

	return count;
}

static ssize_t sensfifo_write(struct file *filp, const char __user *buf,
			      size_t count, loff_t *ppos)
{
	struct sensfifo_dev *dev = filp->private_data;
	struct sens_sample sample;
	unsigned int pushed = 0;

	if (count % sizeof(sample))
		return -EINVAL;

	mutex_lock(&dev->lock);
	while (pushed + sizeof(sample) <= count) {
		if (copy_from_user(&sample, buf + pushed, sizeof(sample))) {
			mutex_unlock(&dev->lock);
			return -EFAULT;
		}
		if (!kfifo_put(&dev->fifo, sample))
			dev->stats.overruns++;
		pushed += sizeof(sample);
	}
	mutex_unlock(&dev->lock);

	wake_up_interruptible(&dev->readq);
	return pushed;
}

static __poll_t sensfifo_poll(struct file *filp, poll_table *wait)
{
	struct sensfifo_dev *dev = filp->private_data;
	__poll_t mask = 0;

	if (!kfifo_is_empty(&dev->fifo))
		mask |= EPOLLIN | EPOLLRDNORM;

	return mask;
}

static long sensfifo_ioctl(struct file *filp, unsigned int cmd,
			   unsigned long arg)
{
	struct sensfifo_dev *dev = filp->private_data;

	switch (cmd) {
	case SENSFIFO_IOC_SET_RATE: {
		u32 rate = *(u32 __user *)arg;

		if (rate == 0 || rate > 2000)
			return -EINVAL;
		mutex_lock(&dev->lock);
		dev->rate_hz = rate;
		mutex_unlock(&dev->lock);
		return 0;
	}
	case SENSFIFO_IOC_GET_STATS: {
		struct sensfifo_stats out;

		out.dropped = dev->stats.dropped;
		out.rate_hz = (u16)dev->rate_hz;
		out.overruns = dev->stats.overruns;
		if (copy_to_user((void __user *)arg, &out, sizeof(out)))
			return -EFAULT;
		return 0;
	}
	default:
		return -ENOTTY;
	}
}

static const struct file_operations sensfifo_fops = {
	.read		= sensfifo_read,
	.write		= sensfifo_write,
	.poll		= sensfifo_poll,
	.unlocked_ioctl	= sensfifo_ioctl,
	.open		= sensfifo_open,
	.release	= sensfifo_release,
};

/* -------------------------------------------------------------------------- */

static int sensfifo_setup_dev(struct sensfifo_dev *dev, int index)
{
	dev_t devno = MKDEV(sensfifo_major, index);
	int ret;

	mutex_init(&dev->lock);
	init_waitqueue_head(&dev->readq);
	dev->rate_hz = 100;

	ret = kfifo_alloc(&dev->fifo, SENSFIFO_FIFO_SAMPLES, GFP_KERNEL);
	if (ret)
		return ret;

	cdev_init(&dev->cdev, &sensfifo_fops);
	ret = cdev_add(&dev->cdev, devno, 1);
	if (ret) {
		kfifo_free(&dev->fifo);
		return ret;
	}

	dev->device = device_create(sensfifo_class, NULL, devno, NULL,
				    SENSFIFO_NAME "%d", index);
	if (IS_ERR(dev->device)) {
		cdev_del(&dev->cdev);
		kfifo_free(&dev->fifo);
		return PTR_ERR(dev->device);
	}
	return 0;
}

static int __init sensfifo_init(void)
{
	dev_t devt;
	int i, ret;

	ret = alloc_chrdev_region(&devt, 0, SENSFIFO_NR_DEVS, SENSFIFO_NAME);
	if (ret)
		return ret;
	sensfifo_major = MAJOR(devt);

	sensfifo_class = class_create(SENSFIFO_NAME);
	if (IS_ERR(sensfifo_class)) {
		ret = PTR_ERR(sensfifo_class);
		goto err_region;
	}

	sensfifo_devs = kcalloc(SENSFIFO_NR_DEVS, sizeof(*sensfifo_devs),
				GFP_KERNEL);
	if (!sensfifo_devs) {
		ret = -ENOMEM;
		goto err_class;
	}

	for (i = 0; i < SENSFIFO_NR_DEVS; i++) {
		ret = sensfifo_setup_dev(&sensfifo_devs[i], i);
		if (ret)
			goto err_devs;
	}

	pr_info("sensfifo: loaded, major %d, %d devices\n",
		sensfifo_major, SENSFIFO_NR_DEVS);
	return 0;

err_devs:
	while (--i >= 0) {
		device_destroy(sensfifo_class,
			       MKDEV(sensfifo_major, i));
		cdev_del(&sensfifo_devs[i].cdev);
		kfifo_free(&sensfifo_devs[i].fifo);
	}
	kfree(sensfifo_devs);
err_class:
	class_destroy(sensfifo_class);
err_region:
	unregister_chrdev_region(devt, SENSFIFO_NR_DEVS);
	return ret;
}

static void __exit sensfifo_exit(void)
{
	int i;

	for (i = 0; i < SENSFIFO_NR_DEVS; i++) {
		device_destroy(sensfifo_class, MKDEV(sensfifo_major, i));
		cdev_del(&sensfifo_devs[i].cdev);
		kfifo_free(&sensfifo_devs[i].fifo);
	}
	kfree(sensfifo_devs);
	class_destroy(sensfifo_class);
	unregister_chrdev_region(MKDEV(sensfifo_major, 0), SENSFIFO_NR_DEVS);
	pr_info("sensfifo: unloaded\n");
}

module_init(sensfifo_init);
module_exit(sensfifo_exit);

MODULE_LICENSE("GPL");
MODULE_DESCRIPTION("Character device over a sensor sample FIFO");
MODULE_VERSION("0.3");

