use std::borrow::Cow;

fn clean(s: &str) -> Cow<'_, str> {
    let trimmed = s.trim_matches(' ');
    let mut needs_change = trimmed.len() != s.len();
    let mut prev_space = false;
    for ch in trimmed.chars() {
        if ch == ' ' {
            if prev_space {
                needs_change = true;
                break;
            }
            prev_space = true;
        } else {
            prev_space = false;
            if ch.is_ascii_uppercase() {
                needs_change = true;
                break;
            }
        }
    }

    if !needs_change {
        return Cow::Borrowed(s);
    }

    let mut out = String::with_capacity(trimmed.len());
    let mut in_space_run = false;
    for ch in trimmed.chars() {
        if ch == ' ' {
            if !in_space_run {
                out.push(' ');
                in_space_run = true;
            }
        } else {
            out.push(ch.to_ascii_lowercase());
            in_space_run = false;
        }
    }
    Cow::Owned(out)
}

fn clean_all<'a>(lines: &[&'a str]) -> Vec<Cow<'a, str>> {
    lines.iter().map(|line| clean(line)).collect()
}

fn main() {
    let text = String::from("  ready  \nTwo   Spaces\nfine\n");
    let cleaned = {
        let lines: Vec<&str> = text.lines().collect();
        clean_all(&lines)
    }; // `lines` is dropped here; `cleaned` borrows from `text`
    for c in &cleaned {
        let how = if matches!(c, Cow::Borrowed(_)) { "borrowed" } else { "owned" };
        println!("{c:?} {how}");
    }
}

