using ShipmentPortal.Api.Contracts;
using ShipmentPortal.Api.Lookup;
using ShipmentPortal.Api.Security;
using ShipmentPortal.Api.Timeline;
using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;

namespace ShipmentPortal.Api.Controllers;

[ApiController]
[Route("api/shipments")]
[Authorize(Policy = Policies.CustomerUser)]
public class ShipmentsController : ControllerBase
{
    private readonly IShipmentTimelineService _timeline;
    private readonly IShipmentLookupService _lookup;

    public ShipmentsController(IShipmentTimelineService timeline, IShipmentLookupService lookup)
    {
        _timeline = timeline;
        _lookup = lookup;
    }

    // Customer scoping is applied by the DbContext global query filter (CustomerId from the token).

    [HttpGet("{id:int}/timeline")]
    [ProducesResponseType(typeof(TimelineDto), StatusCodes.Status200OK)]
    [ProducesResponseType(StatusCodes.Status404NotFound)]
    public async Task<ActionResult<TimelineDto>> GetTimeline(int id)
    {
        var timeline = await _timeline.GetTimelineAsync(id);
        return timeline is null ? NotFound() : Ok(timeline);
    }

    // TRK-405
    [HttpGet("by-tracking/{trackingNo}")]
    [ProducesResponseType(typeof(ShipmentSummaryDto), StatusCodes.Status200OK)]
    [ProducesResponseType(StatusCodes.Status404NotFound)]
    public async Task<ActionResult<ShipmentSummaryDto>> GetByTrackingNumber(string trackingNo, CancellationToken ct)
    {
        var shipment = await _lookup.FindByTrackingNumberAsync(trackingNo, ct);
        return shipment is null ? NotFound() : Ok(shipment);
    }
}

