fn head(text: &str, n: usize) -> &str {
    if n == 0 {
        return "";
    }

    let mut end = 0;
    for (i, ch) in text.char_indices() {
        if i == 0 {
            end = ch.len_utf8();
        } else {
            if text[..i].chars().count() == n {
                return &text[..i];
            }
            end = i + ch.len_utf8();
        }
    }

    let mut count = 0;
    for (i, ch) in text.char_indices() {
        count += 1;
        if count == n {
            return &text[..i + ch.len_utf8()];
        }
    }

    text
}

