use std::fmt::Display;

trait Label {
    fn label(&self) -> String;
}

// Every type that can be displayed gets a label for free.
impl<T: Display> Label for T {
    fn label(&self) -> String {
        format!("[{self}]")
    }
}

// Numbers should look different.
impl Label for i32 {
    fn label(&self) -> String {
        format!("#{self}")
    }
}

fn main() {
    println!("{}", "text".label());
    println!("{}", 5.label());
}

