// Write code: the smallest and largest item of any slice.
// Run: rustc --edition 2024 -o main p7.rs && ./main
// Submit runs hidden tests that call min_max on i32, f64 and char slices.
//
// `T` has no bounds yet. Add the bounds the body needs (and only those),
// then write the body. Do not change the return type.

/// (smallest, largest), or None for an empty slice.
/// min_max(&[4, 9, 1]) == Some((1, 9))
pub fn min_max<T: PartialOrd + Copy>(items: &[T]) -> Option<(T, T)> {
    let mut iter = items.iter().copied();
    let first = iter.next()?;
    let mut min = first;
    let mut max = first;

    for x in iter {
        if x < min {
            min = x;
        }
        if x > max {
            max = x;
        }
    }

    Some((min, max))
}

fn main() {
    println!("{:?}", min_max(&[4, 9, 1]));
    println!("{:?}", min_max(&[2.5, -1.0]));
    println!("{:?}", min_max(&['q', 'b', 'x']));
    let none: [i32; 0] = [];
    println!("{:?}", min_max(&none));
}

