use std::fmt;

pub struct Tags(pub Vec<String>);

impl fmt::Display for Tags {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        let mut first = true;
        for tag in &self.0 {
            if !first {
                write!(f, " ")?;
            }
            write!(f, "#{tag}")?;
            first = false;
        }
        Ok(())
    }
}

impl From<Vec<&str>> for Tags {
    fn from(words: Vec<&str>) -> Tags {
        let mut tags = Vec::new();
        for w in words {
            tags.push(w.to_string());
        }
        Tags(tags)
    }
}

fn main() {
    let tags = Tags(vec![String::from("rust"), String::from("cli")]);
    println!("[{tags}]");
    let more: Tags = vec!["a", "b", "c"].into();
    println!("[{more}]");
}

