use std::ops::Deref;

struct Labeled<T> {
    label: &'static str,
    value: T,
}

impl<T> Deref for Labeled<T> {
    type Target = T;
    fn deref(&self) -> &T {
        &self.value
    }
}

fn main() {
    let boxed = Box::new(String::from("box"));
    let from_box: String = *boxed;

    let mut wrapped = Labeled { label: "w", value: String::from("wrap") };
    wrapped.push_str("ped");
    let from_wrapper: String = wrapped.value.clone();

    println!("{from_box} {from_wrapper} [{}]", wrapped.label);
}

