// A batch of steps. If it is not committed, dropping it must roll back.
struct Batch {
    steps: Option<Vec<String>>,
}

impl Batch {
    fn add(&mut self, step: &str) {
        self.steps.as_mut().unwrap().push(step.to_string());
    }

    fn commit(mut self) -> Vec<String> {
        let steps = self.steps.take().unwrap();
        println!("commit {} steps", steps.len());
        steps
    }
}

impl Drop for Batch {
    fn drop(&mut self) {
        if let Some(steps) = &self.steps {
            println!("rollback {} steps", steps.len());
        }
    }
}

fn run(all_ok: bool) {
    let mut batch = Batch { steps: Some(Vec::new()) };
    batch.add("reserve");
    if !all_ok {
        return;
    }
    batch.add("confirm");
    let _steps = batch.commit();
}

fn main() {
    run(true);
    println!("--");
    run(false);
}

