fn digital_root(n: u64) -> (u64, u32) {
    let mut value = n;
    let mut rounds = 0;
    while value >= 10 {
        let mut sum = 0;
        let mut rest = value;
        while rest > 0 {
            sum += rest % 10;
            rest /= 10;
        }
        value = sum;
        rounds += 1;
    }
    (value, rounds)
}

