// Reference solution for p7 (Assess Tutor only).
pub fn min_max<T: PartialOrd + Copy>(items: &[T]) -> Option<(T, T)> {
    let [first, rest @ ..] = items else {
        return None;
    };
    let mut lo = *first;
    let mut hi = *first;
    for &x in rest {
        if x < lo {
            lo = x;
        }
        if x > hi {
            hi = x;
        }
    }
    Some((lo, hi))
}

fn main() {
    println!("{:?}", min_max(&[4, 9, 1]));
    println!("{:?}", min_max(&[2.5, -1.0]));
    println!("{:?}", min_max(&['q', 'b', 'x']));
    let none: [i32; 0] = [];
    println!("{:?}", min_max(&none));
