mod ledger {
    pub struct Account {
        cents: u64,
        ops: u32,
    }

    impl Account {
        pub fn open() -> Account {
            Account { cents: 0, ops: 0 }
        }

        pub fn deposit(&mut self, cents: u64) {
            self.cents += cents;
            self.ops += 1;
        }

        pub fn withdraw(&mut self, cents: u64) -> bool {
            let fee = fees::withdrawal_fee(cents);
            let total = cents + fee;
            if total > self.cents {
                return false;
            }
            self.cents -= total;
            self.ops += 1;
            true
        }

        pub fn balance(&self) -> u64 {
            self.cents
        }

        pub fn operations(&self) -> u32 {
            self.ops
        }
    }

    pub mod fees {
        /// 1% of the amount, rounded down, but at least 1 cent.
        pub fn withdrawal_fee(cents: u64) -> u64 {
            let fee = cents / 100;
            if fee < 1 { 1 } else { fee }
        }
    }
}

mod report {
    // Tip: format!("{:02}", 5) gives "05".
    pub fn summary(account: &crate::ledger::Account) -> String {
        let dollars = account.balance() / 100;
        let cents = account.balance() % 100;
        format!("balance {}.{:02} after {} operations", dollars, cents, account.operations())
    }
}

fn main() {
    let mut a = ledger::Account::open();
    a.deposit(2000);
    println!("{}", a.withdraw(500));
    println!("{}", a.withdraw(5000));
    println!("{}", report::summary(&a));
}
