// Fill in the todo!()s. Keep every visibility marker exactly as written.
// Rules:
// - Config::new(name) starts on port 8080.
// - with_port(port) gives the Config back on the new port, or None when the
//   port is outside 1024..=65535.
// - default_name() is "app".
// - start(port) builds a Config named default_name() and moves it to `port`.
//   It returns "app on 9000", or "bad port 80" when with_port refuses.

mod app {
    pub mod config {
        pub struct Config {
            pub name: String,
            port: u16,
        }

        impl Config {
            pub fn new(name: &str) -> Config {
                Config { name: name.to_string(), port: 8080 }
            }

            pub fn port(&self) -> u16 {
                self.port
            }

            pub(crate) fn with_port(self, port: u16) -> Option<Config> {
                if port < 1024 {
                    return None; // a u16 is never above 65535
                }
                Some(Config { port, ..self })
            }
        }

        pub(super) fn default_name() -> &'static str {
            "app"
        }
    }

    pub fn start(port: u16) -> String {
        // default_name is pub(super): visible here in `app`, the parent of `config`.
        let config = config::Config::new(config::default_name());
        match config.with_port(port) {
            Some(c) => format!("{} on {}", c.name, c.port()),
            None => format!("bad port {port}"),
        }
    }
}

fn main() {
    println!("{}", app::start(9000));
    println!("{}", app::start(80));
    let c = app::config::Config::new("web");
    println!("{} on {}", c.name, c.port());
}

