#   make test                                ring, stats and msgpool tests
#   make SANITIZE=thread test                the same under ThreadSanitizer

CROSS_COMPILE	?=
CC		:= $(CROSS_COMPILE)gcc
CFLAGS		?= -O2 -g
BUILD		?= build

ALL_CFLAGS	= -std=c11 -D_GNU_SOURCE -Wall -Wextra -pthread -Isrc $(CFLAGS)
ALL_LDFLAGS	= -pthread $(LDFLAGS)

ifneq ($(SANITIZE),)
CC		:= clang
