endif

LIB_SRCS	:= src/ring.c src/crc32.c src/stats.c src/config.c src/msgpool.c \
		   src/capture.c src/writer.c src/uplink.c
TESTS		:= ring_stress stats_check msgpool_stress

all: $(BUILD)/telemetryd

$(BUILD)/telemetryd: src/main.c $(LIB_SRCS) | $(BUILD)
	$(CC) $(ALL_CFLAGS) -o $@ $^ $(ALL_LDFLAGS)

$(BUILD)/ring_stress: tests/ring_stress.c src/ring.c src/crc32.c | $(BUILD)
	$(CC) $(ALL_CFLAGS) -o $@ $^ $(ALL_LDFLAGS)

$(BUILD)/stats_check: tests/stats_check.c $(LIB_SRCS) | $(BUILD)
	$(CC) $(ALL_CFLAGS) -o $@ $^ $(ALL_LDFLAGS)

$(BUILD)/msgpool_stress: tests/msgpool_stress.c src/msgpool.c | $(BUILD)
	$(CC) $(ALL_CFLAGS) -o $@ $^ $(ALL_LDFLAGS)

test: $(addprefix $(BUILD)/,$(TESTS))
	$(BUILD)/ring_stress
	$(BUILD)/stats_check
