use std::collections::HashMap;

/// For every word (split on whitespace, compared exactly), the 0-based
/// positions where it appears, in increasing order.
/// positions("to be or not to be")["to"] == vec![0, 4]
pub fn positions(text: &str) -> HashMap<String, Vec<usize>> {
    let mut index: HashMap<String, Vec<usize>> = HashMap::new();
    for (pos, word) in text.split_whitespace().enumerate() {
        index.entry(word.to_string()).or_default().push(pos);
    }
    index
}

fn main() {
    let index = positions("to be or not to be");
    let mut words: Vec<&String> = Vec::new();
    for w in index.keys() {
        words.push(w);
    }
    words.sort();
    for w in words {
        println!("{w}: {:?}", index[w]);
    }
}

