export type FieldKind = "text" | "number" | "select" | "checkbox" | "date";

export interface SelectOption {
  value: string;
  label: string;
}

export interface FieldConfig {
  name: string;
  label: string;
  kind: FieldKind;
  required?: boolean;
  helpText?: string;
  placeholder?: string;
  options?: SelectOption[];
  min?: number;
  max?: number;
  step?: number;
  defaultValue?: string | number | boolean;
}

export interface FormConfig {
  id: string;
  version: number;
  title: string;
  submitUrl: string;
  submitLabel?: string;
  fields: FieldConfig[];
}

export type FormValues = Record<string, any>;

--- src/forms/validate.ts ---
import type { FieldConfig, FormValues } from "./types";

export type FieldErrors = Record<string, string>;

export function validate(fields: FieldConfig[], values: FormValues): FieldErrors {
  const errors: FieldErrors = {};
  for (const f of fields) {
    const v = values[f.name];
    const empty = v === undefined || v === "" || v === false;
    if (f.required && empty) {
      errors[f.name] = `${f.label} is required`;
      continue;
    }
    if (f.kind === "number" && !empty) {
      if (f.min !== undefined && v < f.min) errors[f.name] = `Minimum is ${f.min}`;
      if (f.max !== undefined && v > f.max) errors[f.name] = `Maximum is ${f.max}`;
    }
  }
  return errors;
}

