/* uplink.h: uploads to the collector, at most GW_UPLINK_SLOTS at a time. */
#ifndef UPLINK_H
#define UPLINK_H

#include <pthread.h>
#include <semaphore.h>
#include <stdbool.h>
#include <stdint.h>
#include <time.h>

#include "gw.h"

enum up_result {
	UP_OK,          /* 201 */
	UP_RETRY,       /* 429, 5xx, timeout, connection error: back off and resend */
	UP_REJECTED,    /* other 4xx: the collector will never take this body */
};

struct uplink {
	const char      *host;
	const char      *port;
	const char      *device;
	sem_t            slots;          /* free upload slots */
	pthread_mutex_t  lock;           /* everything below */
	pthread_cond_t   stop_cv;        /* broadcast by uplink_stop() */
	bool             stopping;
	unsigned         in_flight;
	unsigned         in_flight_max;  /* since last stats */
	unsigned long    sent, http_429, rejected, failed;
	struct timespec  last_sent;      /* CLOCK_MONOTONIC */
};

struct uplink_stats {
	int           slots_free;
	unsigned      in_flight, in_flight_max;
	unsigned long sent, http_429, rejected, failed;
	double        since_sent_s;
};

int            uplink_init(struct uplink *u, const char *host, const char *port,
			   const char *device);
enum up_result uplink_send(struct uplink *u, const struct gw_buf *body, uint32_t seq);
/* Sleeps before retry number `attempt` (1, 2, 4 ... 60 s).
 * Returns true if the uplink is stopping. */
bool           uplink_backoff(struct uplink *u, unsigned attempt);
void           uplink_stop(struct uplink *u);
/* Copies the counters and starts a new in_flight_max. */
void           uplink_stats(struct uplink *u, struct uplink_stats *st);

#endif

