fn after<'a>(text: &'a str, marker: &str) -> &'a str {
    if let Some(i) = text.find(marker) {
        &text[i + marker.len()..]
    } else {
        ""
    }
}

// 2. The first item that contains `needle`, as a &str into `items`.
fn first_with<'a>(items: &'a [String], needle: &str) -> Option<&'a str> {
    for item in items {
        if item.contains(needle) {
            return Some(item.as_str());
        }
    }
    None
}

// 3. The shorter of the two (the first one if they are equally long).
//    Both inputs can be returned, so both carry 'a.
fn shorter<'a>(a: &'a str, b: &'a str) -> &'a str {
    if a.len() < b.len() {
        a
    } else {
        b
    }
}

