// Write `digital_root`: add up the decimal digits of `n`. If the result has more
// than one digit, add up its digits again. Repeat until one digit is left.
// Return (that digit, how many rounds of adding you did).
//
//   digital_root(7)     == (7, 0)   already one digit: no rounds
//   digital_root(38)    == (2, 2)   3 + 8 = 11, then 1 + 1 = 2
//   digital_root(99999) == (9, 2)   45, then 9
//
// `n % 10` is the last digit and `n / 10` drops it.
// Run prints the examples below. Submit checks your function against hidden tests.

fn digital_root(n: u64) -> (u64, u32) {
    if n < 10 {
        return (n, 0);
    }

    let mut current = n;
    let mut rounds = 0;

    loop {
        let mut sum = 0;
        let mut x = current;
        while x > 0 {
            sum += x % 10;
            x /= 10;
        }

        rounds += 1;
        if sum < 10 {
            return (sum, rounds);
        }
        current = sum;
    }
}

fn main() {
    for n in [7, 38, 99999, 1000000] {
        let (root, rounds) = digital_root(n);
        println!("{n}: root {root} after {rounds} rounds");
    }
}

