// A stand-in for llm-gw: each agent answers from its own list, in order, and
// repeats its last answer when the list runs out.
import type { LlmClient, LlmRequest } from "../src/llm.ts";

export type StubLlm = LlmClient & { calls: LlmRequest[] };

export function stubLlm(answers: Partial<Record<LlmRequest["agent"], string[]>>): StubLlm {
  const calls: LlmRequest[] = [];
  const used: Partial<Record<LlmRequest["agent"], number>> = {};
  return {
    calls,
    async complete(req) {
      calls.push(req);
      const list = answers[req.agent] ?? [""];
      const i = used[req.agent] ?? 0;
      used[req.agent] = i + 1;
      const text = list[Math.min(i, list.length - 1)] ?? "";
      return { text, usage: { model: req.model, tokens: 100, toolCalls: 0, ms: 1 } };
    },
  };
}

