// Exercise 3: a flat parser with let-else.
// Run: rustc --edition 2024 --test -o main ex3_let_else.rs && ./main --test-threads=4
//
// Lines look like "name=12". Replace both todo!()s.
// Keep the happy path flat: use let-else, not nested if let.
// `text.split_once('=')` gives Some((left, right)) or None.
// `text.trim().parse::<u32>()` gives Ok(n) or Err(..) (covered in 13):
//     let Ok(n) = text.trim().parse::<u32>() else { ... };

/// Some((name, value)) for a good line, None otherwise.
/// The name is trimmed and must not be empty.
fn parse_line(line: &str) -> Option<(&str, u32)> {
    let Some((name, value)) = line.split_once('=') else {
        return None;
    };
    let name = name.trim();
    if name.is_empty() {
        return None;
    }
    let Ok(n) = value.trim().parse::<u32>() else {
        return None;
    };
    Some((name, n))
}

/// The sum of the values of every good line. Bad lines are skipped.
fn sum_values(lines: &[&str]) -> u32 {
    let mut total = 0;
    for line in lines {
        let Some((_, n)) = parse_line(line) else {
            continue;
        };
        total += n;
    }
    total
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn parses_good_lines() {
        assert_eq!(parse_line("width=12"), Some(("width", 12)));
        assert_eq!(parse_line(" depth = 3 "), Some(("depth", 3)));
    }

    #[test]
    fn rejects_bad_lines() {
        assert_eq!(parse_line("width"), None);
        assert_eq!(parse_line("width=abc"), None);
        assert_eq!(parse_line(" =4"), None);
    }

    #[test]
    fn sums_and_skips() {
        assert_eq!(sum_values(&["a=1", "junk", "b=x", "c = 5", "=9"]), 6);
        assert_eq!(sum_values(&[]), 0);
    }
}



