use std::error::Error;
use std::fmt;
use std::num::ParseIntError;

#[derive(Debug)]
enum LoadError {
    Timeout,
    BadData(ParseIntError),
}

impl fmt::Display for LoadError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            LoadError::Timeout => write!(f, "timed out"),
            LoadError::BadData(e) => write!(f, "bad data: {e}"),
        }
    }
}

impl Error for LoadError {
    fn source(&self) -> Option<&(dyn Error + 'static)> {
        match self {
            LoadError::Timeout => None,
            LoadError::BadData(e) => Some(e),
        }
    }
}

fn load(attempt: u32) -> Result<i32, LoadError> {
    if attempt < 2 {
        return Err(LoadError::Timeout);
    }
    let n: i32 = "x7".parse().map_err(LoadError::BadData)?;
    Ok(n)
}

fn main() {
    // Retry only timeouts, stop on bad data.
    for attempt in 0..4 {
        match load(attempt) {
            Ok(n) => {
                println!("loaded {n}");
                break;
            }
            Err(LoadError::Timeout) => println!("attempt {attempt} failed: timed out"),
            Err(e) => {
                println!("attempt {attempt} failed: {e}");
                break;
            }
        }
    }
}

