import { useState } from "react";
import type { FieldConfig, FormConfig } from "./types";

type ValueFor<F extends FieldConfig> =
  F["kind"] extends "checkbox" ? boolean :
  F["kind"] extends "multiselect" ? string[] :
  F["kind"] extends "number" ? number :
  string;

export type FormValuesOf<C extends FormConfig> = {
  [F in C["fields"][number] as F["name"]]: ValueFor<F>;
};

export function useFormValues<C extends FormConfig>(config: C) {
  const [values, setValues] = useState<Partial<FormValuesOf<C>>>(() => {
    const initial = config.fields.map((f) => [f.name, f.defaultValue]);
    return Object.fromEntries(initial) as Partial<FormValuesOf<C>>;
  });

  function setValue<K extends keyof FormValuesOf<C>>(name: K, value: FormValuesOf<C>[K]) {
    setValues((prev) => ({ ...prev, [name]: value }));
  }

  return { values, setValue };
}
