import { getJson, postJson } from "./http";
import type { FormConfig, FormValues } from "../forms/types";

export function getFormConfig(formId: string): Promise<FormConfig> {
  return getJson<FormConfig>(`/api/forms/${encodeURIComponent(formId)}`);
}

export function submitForm(config: FormConfig, values: FormValues): Promise<{ id: string }> {
  return postJson<{ id: string }>(config.submitUrl, values);
}

--- src/api/http.ts ---
export class HttpError extends Error {
  readonly status: number;

  constructor(status: number, url: string) {
    super(`${status} from ${url}`);
    this.status = status;
  }
}

export async function getJson<T>(url: string): Promise<T> {
  const res = await fetch(url, {
    headers: { Accept: "application/json" },
    credentials: "include",
  });
  if (!res.ok) throw new HttpError(res.status, url);
  return res.json();
}

export async function postJson<T>(url: string, body: unknown): Promise<T> {
  const res = await fetch(url, {
    method: "POST",
    headers: { "Content-Type": "application/json", Accept: "application/json" },
    credentials: "include",
    body: JSON.stringify(body),
  });
  if (!res.ok) throw new HttpError(res.status, url);
  return res.json();
}

