/*
 * mm.h - fixed-arena block allocator for the sensor controller.
 *
 * No malloc after boot. One static arena (see mm_arena.c) is carved into a
 * small set of size classes; each class keeps an intrusive singly linked free
 * list threaded through the free blocks themselves. Every live block is
 * reachable through a handle table, so the compactor can move a block's bytes
 * and only rewrite one table slot.
 *
 * Target: 32-bit Cortex-M4 (sizeof(void*) == 4, max_align 8), newlib. The host
 * test build (test/) compiles the same sources with clang.
 *
 * Return convention: 0 (MM_OK) on success, a negative MM_E* on failure. The
 * caller's pointer is written only on MM_OK.
 */
#ifndef MM_H
#define MM_H

#include <stddef.h>
#include <stdint.h>

#define MM_OK           0
#define MM_ENOMEM     (-1)   /* no free block in a class big enough */
#define MM_EINVAL     (-2)   /* bad argument (size 0, NULL out, ...) */
#define MM_EHANDLE    (-3)   /* handle table full */

/* Size classes, in bytes of usable payload. A request is served from the
 * smallest class that fits. These are the only sizes the arena is carved into. */
#define MM_CLASS_COUNT  4
extern const uint16_t mm_class_bytes[MM_CLASS_COUNT];   /* {16, 32, 64, 128} */

/* Handle: a stable index into the manager's handle table. A payload pointer can
 * be turned back into its handle (the block header carries it), which is how
 * mm_free and the compactor find the table slot to clear or rewrite. */
typedef uint16_t mm_handle_t;
#define MM_HANDLE_NONE  ((mm_handle_t)0xFFFF)

typedef struct mm mm_t;

/* Bind the manager to its static arena. Call once at boot. */
void mm_init(mm_t *m);

/* Allocate one block of at least n payload bytes. On MM_OK, *out holds the
 * payload pointer. */
int mm_alloc(mm_t *m, size_t n, void **out);

/* Allocate `count` blocks of n bytes each. On MM_OK, *out_array holds a pointer
 * to a caller-visible array of `count` payload pointers (taken from the arena,
 * one block itself). Release with mm_free on each payload, then on the array.
 * On failure nothing is allocated. */
int mm_alloc_many(mm_t *m, size_t n, size_t count, void ***out_array);

/* Free the block whose payload is *pp, and set *pp to NULL so the caller cannot
 * reuse a dangling pointer. No-op if *pp is NULL. */
void mm_free(mm_t *m, void **pp);

/* Move live blocks toward the start of each class's storage so that the free
 * blocks in a class become contiguous. Payload addresses change; handles do
 * not. Any raw payload pointer held across this call is stale afterwards; read
 * it again through mm_resolve(). */
void mm_compact(mm_t *m);

/* Current payload address for a handle, or NULL if the handle is free. */
void *mm_resolve(mm_t *m, mm_handle_t h);

/* The handle for a payload pointer returned by mm_alloc / mm_alloc_many. */
mm_handle_t mm_handle_of(mm_t *m, const void *payload);

/* Bytes still free in the class that would serve a request of n bytes. */
size_t mm_class_free_bytes(mm_t *m, size_t n);

#endif /* MM_H */

--- src/mm_alloc.c ---
/*
 * mm_alloc.c - the public alloc / alloc_many / free entry points.
 */
#include "mm_internal.h"

/* from mm_block.c */
void        *mm_hdr_to_payload(block_hdr_t *hdr);
block_hdr_t *mm_payload_to_hdr(void *payload);
void         mm_freelist_push(mm_class_t *cl, block_hdr_t *hdr);
block_hdr_t *mm_freelist_pop(mm_class_t *cl);
int          mm_class_for(mm_t *m, size_t n);

/* Find a free handle-table slot, bind it to `payload`, and return the handle,
 * or MM_HANDLE_NONE when the table is full. */
static mm_handle_t handle_bind(mm_t *m, void *payload) {
    for (mm_handle_t h = 0; h < MM_HANDLE_MAX; h++) {
        if (m->handles[h] == NULL) {
            m->handles[h] = payload;
            return h;
        }
    }
    return MM_HANDLE_NONE;
}

int mm_alloc(mm_t *m, size_t n, void **out) {
    if (n == 0 || out == NULL) {
        return MM_EINVAL;
    }
    int c = mm_class_for(m, n);
    if (c < 0) {
        return MM_ENOMEM;
    }
    mm_class_t *cl = &m->cls[c];

    block_hdr_t *hdr = mm_freelist_pop(cl);
    if (hdr == NULL) {
        return MM_ENOMEM;
    }

    void *payload = mm_hdr_to_payload(hdr);
    mm_handle_t h = handle_bind(m, payload);
    if (h == MM_HANDLE_NONE) {
        mm_freelist_push(cl, hdr);     /* give the block back */
        return MM_EHANDLE;
    }
    hdr->handle = h;
    hdr->tag    = MM_TAG_LIVE;

    *out = payload;
    return MM_OK;
}

/* Hand back `count` payloads through one pointer array. The array itself is
 * one block (from the class that fits count pointers); the payloads are
 * `count` further blocks. */
int mm_alloc_many(mm_t *m, size_t n, size_t count, void ***out_array) {
    if (n == 0 || count == 0 || out_array == NULL) {
        return MM_EINVAL;
    }
    /* The array of `count` void* must fit in one block of the biggest class. */
    if (count * sizeof(void *) > m->cls[MM_CLASS_COUNT - 1].payload) {
        return MM_EINVAL;
    }

    void **arr = NULL;
    if (mm_alloc(m, count * sizeof(void *), (void **)&arr) != MM_OK) {
        return MM_ENOMEM;
    }

    for (size_t i = 0; i < count; i++) {
        void *blk = NULL;
        if (mm_alloc(m, n, &blk) != MM_OK) {
            /* roll back the ones we did get, then the array */
            for (size_t j = 0; j < i; j++) {
                mm_free(m, &arr[j]);
            }
            mm_free(m, (void **)&arr);
            return MM_ENOMEM;
        }
        arr[i] = blk;
    }

    out_array = &arr;
    return MM_OK;
}

void mm_free(mm_t *m, void **pp) {
    if (pp == NULL || *pp == NULL) {
        return;
    }
    void *payload = *pp;
    block_hdr_t *hdr = mm_payload_to_hdr(payload);

    if (hdr->tag != MM_TAG_LIVE) {
        return;                         /* not a live block; ignore */
    }
    if (hdr->handle != MM_HANDLE_NONE && hdr->handle < MM_HANDLE_MAX) {
        m->handles[hdr->handle] = NULL;
    }

    mm_freelist_push(&m->cls[hdr->cls], hdr);
    *pp = NULL;
}

--- src/mm_arena.c ---
/*
 * mm_arena.c - the one static arena and how it is carved into size classes.
 *
 * The arena is a plain byte array in .bss. mm_init() splits it into four
 * classes (16, 32, 64, 128 payload bytes) and threads each class's blocks onto
 * its free list. No allocation ever grows the arena.
 */
#include "mm_internal.h"

#include <string.h>

/* 4 KiB of static arena, 8-byte aligned so the first header is aligned. */
#define MM_ARENA_BYTES  4096u
static uint8_t g_arena[MM_ARENA_BYTES] __attribute__((aligned(8)));

const uint16_t mm_class_bytes[MM_CLASS_COUNT] = { 16, 32, 64, 128 };

/* Fraction of the arena given to each class, in sixteenths. 128-byte blocks are
 * rare, 16- and 32-byte blocks are the common sensor-sample case. */
static const uint8_t k_class_share[MM_CLASS_COUNT] = { 6, 5, 3, 2 };

uint8_t *mm_arena_base(void) { return g_arena; }
size_t   mm_arena_size(void) { return MM_ARENA_BYTES; }

/* Round x up to the next multiple of a (a a power of two). */
static uint16_t align_up(uint16_t x, uint16_t a) {
    return (uint16_t)((x + (a - 1u)) & ~(uint16_t)(a - 1u));
}

void mm_init(mm_t *m) {
    memset(m, 0, sizeof(*m));

    uint8_t *p = mm_arena_base();
    uint8_t *end = p + mm_arena_size();

    for (int c = 0; c < MM_CLASS_COUNT; c++) {
        mm_class_t *cl = &m->cls[c];
        cl->payload = mm_class_bytes[c];
        /* A block is a header followed by its payload. Keep whole blocks
         * 8-byte aligned so successive payloads stay aligned. */
        cl->stride  = align_up((uint16_t)(sizeof(block_hdr_t) + cl->payload), 8u);

        size_t share = (size_t)mm_arena_size() * k_class_share[c] / 16u;
        uint8_t *cl_end = p + share;
        if (cl_end > end) cl_end = end;

        cl->base = p;
        cl->free_list = NULL;

        /* Thread every whole block in the slab onto the free list, newest at
         * the head. */
        uint8_t *b = p;
        while (b + cl->stride <= cl_end) {
            block_hdr_t *hdr = (block_hdr_t *)b;
            hdr->size   = cl->payload;
            hdr->handle = MM_HANDLE_NONE;
            hdr->cls    = (uint8_t)c;
            hdr->tag    = MM_TAG_FREE;

            node_t *node = (node_t *)(hdr + 1);
            node->next = cl->free_list;
            cl->free_list = node;

            b += cl->stride;
        }
        cl->brk = b;
        p = cl_end;
    }
    m->inited = 1;
}

--- src/mm_block.c ---
/*
 * mm_block.c - block header <-> payload conversions and the free-list link
 * operations shared by alloc, free and the compactor.
 */
#include "mm_internal.h"

/* Payload pointer for a header: the bytes right after the header. */
void *mm_hdr_to_payload(block_hdr_t *hdr) {
    return (void *)(hdr + 1);
}

/* Header for a payload pointer: step back one header's worth of bytes. */
block_hdr_t *mm_payload_to_hdr(void *payload) {
    block_hdr_t *p = (block_hdr_t *)payload;
    return (block_hdr_t *)(p - sizeof(block_hdr_t));
}

/* Push a block onto the head of its class free list. */
void mm_freelist_push(mm_class_t *cl, block_hdr_t *hdr) {
    node_t *node = (node_t *)mm_hdr_to_payload(hdr);
    node->next = cl->free_list;
    cl->free_list = node;
    hdr->tag = MM_TAG_FREE;
    hdr->handle = MM_HANDLE_NONE;
}

/* Pop the head block off a class free list, or NULL if the class is empty. */
block_hdr_t *mm_freelist_pop(mm_class_t *cl) {
    node_t *node = cl->free_list;
    if (node == NULL) {
        return NULL;
    }
    cl->free_list = node->next;
    return mm_payload_to_hdr(node);
}

/* Remove one specific node from a class free list (used by the compactor, which
 * takes a free block out of the middle of the list before moving bytes into
 * it). Returns 1 if the node was found and unlinked, 0 otherwise.
 *
 * Walk a pointer-to-pointer over the list so the head and the interior are the
 * same case: *link is the field that points at the current node. */
int mm_freelist_remove(mm_class_t *cl, node_t *target) {
    node_t **link = &cl->free_list;
    node_t  *cur  = *link;
    while (cur != NULL) {
        if (cur == target) {
            *link = cur->next;
            return 1;
        }
        cur  = cur->next;
        link = &cur->next;
    }
    return 0;
}

/* Index of the smallest class whose payload is >= n, or -1 if none fits. */
int mm_class_for(mm_t *m, size_t n) {
    for (int c = 0; c < MM_CLASS_COUNT; c++) {
        if ((size_t)m->cls[c].payload >= n) {
            return c;
        }
    }
    return -1;
}

--- src/mm_compact.c ---
/*
 * mm_compact.c - slide live blocks to the low end of each class so the free
 * blocks become one contiguous run at the top of the class.
 *
 * A block's bytes move, but its handle does not: after moving a block we write
 * the new payload address into its handle-table slot, so mm_resolve(handle)
 * stays correct. Raw payload pointers the caller kept are not updated and must
 * be re-fetched with mm_resolve() after this returns.
 */
#include "mm_internal.h"

#include <string.h>

void        *mm_hdr_to_payload(block_hdr_t *hdr);
void         mm_freelist_push(mm_class_t *cl, block_hdr_t *hdr);
int          mm_freelist_remove(mm_class_t *cl, node_t *target);

static void compact_class(mm_t *m, mm_class_t *cl) {
    uint8_t *dst = cl->base;

    /* Pack live blocks down to dst, lowest address first. When a live block
     * moves onto a slot that is currently a free block, take that free node out
     * of the list before its bytes are overwritten, so the list never points
     * into memory we are about to rewrite. */
    for (uint8_t *src = cl->base; src + cl->stride <= cl->brk; src += cl->stride) {
        block_hdr_t *sh = (block_hdr_t *)src;
        if (sh->tag != MM_TAG_LIVE) {
            continue;
        }
        if (dst != src) {
            block_hdr_t *dh_old = (block_hdr_t *)dst;
            if (dh_old->tag == MM_TAG_FREE) {
                mm_freelist_remove(cl, (node_t *)mm_hdr_to_payload(dh_old));
            }
            memmove(dst, src, cl->stride);
            block_hdr_t *dh = (block_hdr_t *)dst;
            /* the handle slot must now point at the moved payload */
            m->handles[dh->handle] = mm_hdr_to_payload(dh);
            /* src is now stale storage; mark it free and give it to the list */
            sh->tag = MM_TAG_FREE;
            mm_freelist_push(cl, sh);
        }
        dst += cl->stride;
    }
}

void mm_compact(mm_t *m) {
    for (int c = 0; c < MM_CLASS_COUNT; c++) {
        compact_class(m, &m->cls[c]);
    }
}

void *mm_resolve(mm_t *m, mm_handle_t h) {
    if (h >= MM_HANDLE_MAX) {
        return NULL;
    }
    return m->handles[h];
}

mm_handle_t mm_handle_of(mm_t *m, const void *payload) {
    for (mm_handle_t h = 0; h < MM_HANDLE_MAX; h++) {
        if (m->handles[h] == payload) {
            return h;
        }
    }
    return MM_HANDLE_NONE;
}

size_t mm_class_free_bytes(mm_t *m, size_t n) {
    int c = -1;
    for (int i = 0; i < MM_CLASS_COUNT; i++) {
        if ((size_t)m->cls[i].payload >= n) { c = i; break; }
    }
    if (c < 0) {
        return 0;
    }
    size_t count = 0;
    for (node_t *node = m->cls[c].free_list; node != NULL; node = node->next) {
        count++;
    }
    return count * m->cls[c].payload;
}

--- src/mm_internal.h ---
/*
 * mm_internal.h - layout shared by the allocator sources. Not a public API.
 *
 * Arena layout, per size class:
 *
 *     [ hdr ][ payload ... ][ hdr ][ payload ... ] ...
 *
 * Every block starts with a block_hdr_t. On a free block the first bytes of the
 * payload hold a node_t that links it into its class free list; on a live block
 * those same bytes are the caller's data.
 */
#ifndef MM_INTERNAL_H
#define MM_INTERNAL_H

#include "mm.h"

/* Free-list link, stored in the first bytes of a free block's payload. */
typedef struct node {
    struct node *next;
} node_t;

/* Block header, placed immediately before every payload. Packed to 6 bytes so
 * the header costs as little arena as possible: two 16-bit fields and a byte of
 * class index plus a tag. The payload begins at (hdr + 1). */
typedef struct __attribute__((packed)) block_hdr {
    uint16_t    size;       /* payload bytes for this block */
    mm_handle_t handle;     /* owning handle, or MM_HANDLE_NONE when free */
    uint8_t     cls;        /* size-class index 0..MM_CLASS_COUNT-1 */
    uint8_t     tag;        /* MM_TAG_LIVE / MM_TAG_FREE */
} block_hdr_t;

#define MM_TAG_FREE  0x00u
#define MM_TAG_LIVE  0xA5u

#define MM_HANDLE_MAX  64u   /* handle table slots */

/* One size class: a slab of the arena and the head of its free list. */
typedef struct {
    uint8_t *base;      /* first header in the class */
    uint8_t *brk;       /* end of storage carved for the class */
    uint16_t payload;   /* payload bytes per block in this class */
    uint16_t stride;    /* header + payload, rounded up to alignment */
    node_t  *free_list; /* head of the intrusive free list, or NULL */
} mm_class_t;

struct mm {
    mm_class_t  cls[MM_CLASS_COUNT];
    void       *handles[MM_HANDLE_MAX];  /* handle -> payload pointer */
    int         inited;
};

/* The one static arena, defined in mm_arena.c. */
uint8_t *mm_arena_base(void);
size_t   mm_arena_size(void);

#endif /* MM_INTERNAL_H */

