// Reference solution for p6 (never shown to the learner).
//
// Run:    rustc --edition 2024 -o main p6.rs && ./main

struct Settings<'a> {
    pairs: Vec<(&'a str, &'a str)>,
}

impl<'a> Settings<'a> {
    fn parse(text: &'a str) -> Settings<'a> {
        let mut pairs = Vec::new();
        for line in text.lines() {
            let line = line.trim();
            if line.is_empty() || line.starts_with('#') {
                continue;
            }
            // split_once slices `line`, which is a slice of `text`: still 'a.
            if let Some((k, v)) = line.split_once('=') {
                pairs.push((k.trim(), v.trim()));
            }
        }
        Settings { pairs }
    }

    fn get(&self, key: &str) -> Option<&'a str> {
        self.pairs.iter().rev().find(|(k, _)| *k == key).map(|(_, v)| *v)
    }

    fn keys(&self) -> Vec<&'a str> {
        let mut out: Vec<&'a str> = Vec::new();
        for (k, _) in &self.pairs {
            if !out.contains(k) {
                out.push(k);
            }
        }
        out
    }
}

fn main() {
    let text = String::from("# demo\nname = ada\n\nmode=fast\nname = grace\nbroken line\n");
    let name;
    {
        let settings = Settings::parse(&text);
        println!("keys: {:?}", settings.keys());
        let wanted = String::from("name");
        name = settings.get(&wanted);
    }
    println!("name: {name:?}");
}

