// Reference solution for exercise 3 (never shown to the learner).
// Run runs the tests: rustc --edition 2024 --test -o main ex3_take_first.rs && ./main
//
// take_first: take the first name out of the list, put `replacement` in its
// place, and return (the old first name, the list). The list has at least one name.
//
// `let old = names[0];` is error E0507: you cannot move out of a vector by index.
// Vector methods that move values in and out:
//   names.remove(i)        takes element i out (later ones shift left) and returns it
//   names.insert(i, value) moves value in at position i (later ones shift right)
// Both change the vector, so `names` must be mutable: `fn take_first(mut names: ...)`.
// Do not clone: the tests check that the old name is the original string.

fn take_first(mut names: Vec<String>, replacement: String) -> (String, Vec<String>) {
    let old = names.remove(0);
    names.insert(0, replacement);
    (old, names)
}

#[cfg(test)]
mod tests {
    use super::*;

    fn list(words: [&str; 3]) -> Vec<String> {
        vec![String::from(words[0]), String::from(words[1]), String::from(words[2])]
    }

    #[test]
    fn swaps_the_first_name() {
        let (old, names) = take_first(list(["ada", "bo", "cy"]), String::from("zed"));
        assert_eq!(old, "ada");
        assert_eq!(names, ["zed", "bo", "cy"]);
    }

    #[test]
    fn single_name_list() {
        let (old, names) = take_first(vec![String::from("only")], String::from("new"));
        assert_eq!(old, "only");
        assert_eq!(names, ["new"]);
    }

    #[test]
    fn old_name_is_moved_out_not_copied() {
        let names = list(["ada", "bo", "cy"]);
        let address = names[0].as_ptr();
        let (old, _names) = take_first(names, String::from("zed"));
        assert_eq!(old.as_ptr(), address, "the old name should be the original String, not a clone");
    }
}



