use std::fmt;
use std::num::ParseIntError;

#[derive(Debug, PartialEq)]
enum CalcError {
    Format,
    BadNumber(ParseIntError),
    UnknownOp(String),
    DivByZero,
    Overflow,
}

// Given.
impl fmt::Display for CalcError {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        match self {
            CalcError::Format => write!(f, "expected <number> <op> <number>"),
            CalcError::BadNumber(e) => write!(f, "bad number: {e}"),
            CalcError::UnknownOp(op) => write!(f, "unknown operator {op:?}"),
            CalcError::DivByZero => write!(f, "division by zero"),
            CalcError::Overflow => write!(f, "result does not fit in i64"),
        }
    }
}

impl std::error::Error for CalcError {}

impl From<ParseIntError> for CalcError {
    fn from(e: ParseIntError) -> Self {
        CalcError::BadNumber(e)
    }
}

fn eval(expr: &str) -> Result<i64, CalcError> {
    let mut parts = expr.split_whitespace();
    let left = parts.next().ok_or(CalcError::Format)?;
    let op = parts.next().ok_or(CalcError::Format)?;
    let right = parts.next().ok_or(CalcError::Format)?;
    if parts.next().is_some() {
        return Err(CalcError::Format);
    }

    let a: i64 = left.parse()?;
    let b: i64 = right.parse()?;

    match op {
        "+" => a.checked_add(b).ok_or(CalcError::Overflow),
        "-" => a.checked_sub(b).ok_or(CalcError::Overflow),
        "*" => a.checked_mul(b).ok_or(CalcError::Overflow),
        "/" => {
            if b == 0 {
                Err(CalcError::DivByZero)
            } else {
                a.checked_div(b).ok_or(CalcError::Overflow)
            }
        }
        other => Err(CalcError::UnknownOp(other.to_string())),
    }
}

fn eval_lines(text: &str) -> (Vec<i64>, Vec<String>) {
    let mut oks = Vec::new();
    let mut errs = Vec::new();

    for (i, line) in text.lines().enumerate() {
        let line_no = i + 1;
        if line.trim().is_empty() {
            continue;
        }
        match eval(line) {
            Ok(n) => oks.push(n),
            Err(e) => errs.push(format!("line {line_no}: {e}")),
        }
    }

    (oks, errs)
}

fn main() {
    for expr in ["6 ", "6 / 0", "9223372036854775807 + 1", "8 * 7"] {
        println!("{expr:?} -> {:?}", eval(expr));
    }

    let text = "1 + 2\n\n9 / 0\nfoo * 3\n7 * 8\n";
    let (vals, errs) = eval_lines(text);
    println!("vals: {vals:?}");
    println!("errs: {errs:?}");
}
