    let right: i64 = b.parse()?;

    match op {
        "+" => left.checked_add(right).ok_or(CalcError::Overflow),
        "-" => left.checked_sub(right).ok_or(CalcError::Overflow),
        "*" => left.checked_mul(right).ok_or(CalcError::Overflow),
        "/" => {
            if right == 0 {
                Err(CalcError::DivByZero)
            } else {
                left.checked_div(right).ok_or(CalcError::Overflow)
            }
        }
        other => Err(CalcError::UnknownOp(other.to_string())),
    }
}

fn eval_lines(text: &str) -> (Vec<i64>, Vec<String>) {
    let mut oks = Vec::new();
    let mut errs = Vec::new();

    for (i, line) in text.lines().enumerate() {
        if line.trim().is_empty() {
            continue;
        }
        match eval(line) {
            Ok(n) => oks.push(n),
            Err(e) => errs.push(format!("line {}: {e}", i + 1)),
        }
    }

    (oks, errs)
}

fn main() {
    for expr in ["6 + 7", "9 / 0", "1 ^ 2", "9223372036854775807 + 1", "x + 3"] {
        println!("{expr:?} => {:?}", eval(expr));
    }

    let text = "1 + 2\n\n9 / 0\n4 * 5\nx + 3\n";
    let (oks, errs) = eval_lines(text);
    println!("oks {oks:?}");
    println!("errs {errs:?}");
}
