    fn str_methods_through_deref() {
        let t = Trimmed::new(" rust ");
        assert_eq!(t.len(), 4);
        assert!(t.starts_with("ru"));
    }

    #[test]
    fn coerces_to_str() {
        let t = Trimmed::new("  ok");
        assert_eq!(shout(&t), "OK");
        let boxed = Box::new(Trimmed::new(" boxed "));
        assert_eq!(shout(&boxed), "BOXED");
    }
}


