// Reference solution for p6 (Assess Tutor only).
struct Node {
    value: i32,
    next: Option<Box<Node>>,
}

pub struct Stack {
    head: Option<Box<Node>>,
    len: usize,
}

impl Stack {
    pub fn new() -> Stack {
        Stack { head: None, len: 0 }
    }

    pub fn len(&self) -> usize {
        self.len
    }

    pub fn push(&mut self, value: i32) {
        let old = self.head.take(); // leave None behind while we build the new node
        self.head = Some(Box::new(Node { value, next: old }));
        self.len += 1;
    }

    pub fn pop(&mut self) -> Option<i32> {
        match self.head.take() {
            Some(node) => {
                let node = *node; // move the Node out of its Box (only Box allows this)
                self.head = node.next;
                self.len -= 1;
                Some(node.value)
            }
            None => None,
        }
    }

    pub fn peek(&self) -> Option<&i32> {
        match &self.head {
            Some(node) => Some(&node.value),
            None => None,
        }
    }
}

fn main() {
    let mut s = Stack::new();
    s.push(1);
    s.push(2);
    s.push(3);
    println!("peek {:?}, len {}", s.peek(), s.len());
    println!("{:?} {:?} {:?} {:?}", s.pop(), s.pop(), s.pop(), s.pop());
}

