/// a / b, or None when b is 0.
fn safe_div(a: i32, b: i32) -> Option<i32> {
    if b == 0 {
        None
    } else {
        Some(a / b)
    }
}

/// The sum when both are present, otherwise None.
/// Hint: match on the tuple (a, b).
fn add_both(a: Option<i32>, b: Option<i32>) -> Option<i32> {
    match (a, b) {
        (Some(x), Some(y)) => Some(x + y),
        _ => None,
    }
}

/// The item at index i, or "?" when i is out of range. Must never panic.
fn item_or_question(items: &[&str], i: usize) -> String {
    match items.get(i) {
        Some(item) => item.to_string(),
        None => "?".to_string(),
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn divides() {
        assert_eq!(safe_div(7, 2), Some(3));
        assert_eq!(safe_div(-9, 3), Some(-3));
    }

    #[test]
    fn division_by_zero_is_none() {
        assert_eq!(safe_div(1, 0), None);
    }

    #[test]
    fn adds_only_when_both_are_present() {
        assert_eq!(add_both(Some(2), Some(3)), Some(5));
        assert_eq!(add_both(Some(2), None), None);
        assert_eq!(add_both(None, Some(3)), None);
        assert_eq!(add_both(None, None), None);
    }

    #[test]
    fn reads_items_safely() {
        let items = ["a", "b"];
        assert_eq!(item_or_question(&items, 1), "b");
        assert_eq!(item_or_question(&items, 2), "?");
        assert_eq!(item_or_question(&[], 0), "?");
    }
}
