/// Returns the middle value of `items` after sorting them.
/// For an even count, returns the mean of the two middle values.
pub fn median(items: &mut [i32]) -> Option<f64> {
    if items.is_empty() {
        return None;
    }

    items.sort();
    let mid = items.len() / 2;

    if items.len() % 2 == 1 {
        Some(items[mid] as f64)
    } else {
        let a = items[mid - 1] as f64;
        let b = items[mid] as f64;
        Some((a + b) / 2.0)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn odd_count() {
        let mut items = [3, 1, 2];
        assert_eq!(median(&mut items), Some(2.0));
    }

    #[test]
    fn even_count_mean() {
        let mut items = [4, 1, 2, 3];
        assert_eq!(median(&mut items), Some(2.5));
    }

    #[test]
    fn empty_slice() {
        let mut items: [i32; 0] = [];
        assert_eq!(median(&mut items), None);
    }

    #[test]
    fn single_item() {
        let mut items = [42];
        assert_eq!(median(&mut items), Some(42.0));
    }

    #[test]
    fn negatives_and_duplicates() {
        let mut items = [5, -1, 5, 2, -1];
        assert_eq!(median(&mut items), Some(2.0));
    }
}

