/*
 * app_compact_demo.c - the capture task's current-frame pointer across a
 * maintenance compaction, built for the host.
 *
 * The capture task keeps a pointer to the frame it is filling. Between bursts
 * the maintenance task frees finished frames and calls mm_compact(). The task
 * then carries on with the frame it was filling.
 */
#include "mm.h"
#include "mm_internal.h"

#include <stdio.h>
#include <stdint.h>

static mm_t g_mm;

int main(void) {
    setvbuf(stdout, NULL, _IONBF, 0);
    mm_init(&g_mm);

    void *a = NULL, *b = NULL, *c = NULL;
    mm_alloc(&g_mm, 16, &a);  mm_handle_t ha = mm_handle_of(&g_mm, a);
    mm_alloc(&g_mm, 16, &b);
    mm_alloc(&g_mm, 16, &c);  mm_handle_t hc = mm_handle_of(&g_mm, c);

    *(uint32_t *)a = 0xAAAA0001u;
    *(uint32_t *)c = 0xCCCC0003u;

    uint32_t *cur = (uint32_t *)c;          /* the frame being filled */
    printf("before compact: cur=%p reads 0x%08X\n", (void *)cur, *cur);

    mm_free(&g_mm, &b);                     /* maintenance: b is finished */
    mm_compact(&g_mm);

    printf("after compact : cur=%p reads 0x%08X\n", (void *)cur, *cur);
    cur[2] = 0xCCCC0005u;                   /* the task keeps filling its frame */

    uint32_t *viac = (uint32_t *)mm_resolve(&g_mm, hc);
    printf("after compact : mm_resolve(hc)=%p reads [0]=0x%08X [2]=0x%08X\n",
           (void *)viac, viac[0], viac[2]);
    uint32_t *viaa = (uint32_t *)mm_resolve(&g_mm, ha);
    printf("after compact : mm_resolve(ha)=%p reads [0]=0x%08X\n",
           (void *)viaa, viaa[0]);
    return 0;
}

--- test/test_freelist.c ---
/*
 * test_freelist.c - focused test of mm_freelist_remove, the pointer-to-pointer
 * unlink the compactor relies on. Builds a known free list of six blocks in one
 * class, removes the head (node[0]) and two nodes further down (node[3] and
 * node[5]), and checks the list after each. Output is test_freelist.out.
 */
#include "mm.h"
#include "mm_internal.h"

#include <stdio.h>
#include <stdint.h>

int mm_freelist_remove(mm_class_t *cl, node_t *target);

static mm_t g_mm;

/* Collect the current free list of class 0 into out[], return its length. */
static int snapshot(mm_class_t *cl, node_t *out[], int max) {
    int n = 0;
    for (node_t *nd = cl->free_list; nd && n < max; nd = nd->next) {
        out[n++] = nd;
    }
    return n;
}

/* Print the list as fixture names; nodes past the fixture are counted. */
static void show(mm_class_t *cl, node_t *fixture[], int nfix) {
    int more = 0;
    printf("  list:");
    for (node_t *nd = cl->free_list; nd; nd = nd->next) {
        int k = -1;
        for (int i = 0; i < nfix; i++) if (fixture[i] == nd) k = i;
        if (k >= 0 && more == 0) printf(" node[%d]", k);
        else more++;
    }
    printf(" + %d more\n", more);
}

static int contains(node_t *list[], int n, node_t *x) {
    for (int i = 0; i < n; i++) if (list[i] == x) return 1;
    return 0;
}

int main(void) {
    setvbuf(stdout, NULL, _IONBF, 0);
    mm_init(&g_mm);
    mm_class_t *cl = &g_mm.cls[0];

    /* Take the first six nodes of the class as our fixture list, in list order:
     * node[0] is the head. */
    node_t *node[6];
    int len = snapshot(cl, node, 6);
    printf("fixture: %d-node free list, head = node[0]\n", len);
    show(cl, node, 6);

    /* 1. Remove the head. */
    int r1 = mm_freelist_remove(cl, node[0]);
    node_t *after1[8]; int n1 = snapshot(cl, after1, 8);
    printf("remove node[0]: ret=%d, head still on list=%d (want ret=1, 0)\n",
           r1, contains(after1, n1, node[0]));
    show(cl, node, 6);

    /* 2. Remove a node further down (node[3]). */
    int r2 = mm_freelist_remove(cl, node[3]);
    node_t *after2[8]; int n2 = snapshot(cl, after2, 8);
    printf("remove node[3]: ret=%d, node[3] still on list=%d (want ret=1, 0)\n",
           r2, contains(after2, n2, node[3]));
    show(cl, node, 6);

    /* 3. Remove another one (node[5]). */
    int r3 = mm_freelist_remove(cl, node[5]);
    node_t *after3[72]; int n3 = snapshot(cl, after3, 72);
    printf("remove node[5]: ret=%d, node[5] still on list=%d (want ret=1, 0)\n",
           r3, contains(after3, n3, node[5]));
    show(cl, node, 6);

    int still = contains(after3, n3, node[0]) + contains(after3, n3, node[3])
              + contains(after3, n3, node[5]);
    printf("3 removes all returned success; %d of the 3 targets are still on the list\n",
           still);
    return 0;
}

